window.TIMELINE_RESEARCH_DATA = {"format_version":1,"source":"docs/timeline/data","entities":[{"id":"cul_akan_asante","name":"Akan (Asante)","region":["West Africa"],"date_range":null,"notes":"Akan-speaking peoples of modern Ghana/Côte d'Ivoire; Asante specifically is the dominant historical Akan polity/culture from the late 17th century.","_entity_type":"Culture","_source_path":"docs/timeline/data/entities/cultures/cul_akan_asante.json"},{"id":"cul_aksumite","name":"Aksumite","region":["Horn of Africa/Aksum"],"date_range":{"earliest":1,"latest":700,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"notes":"The Kingdom of Aksum's population, modern Ethiopia/Eritrea highlands, roughly 1st-7th century CE. Distinct from the earlier Kingdom of D'mt (~8th-5th c. BCE) and from later medieval/early-modern Christian-Ethiopian (Amhara-highland) society, which is a separately-dated, better-documented topic not covered by this batch — see gs_aksumite notes.","_entity_type":"Culture","_source_path":"docs/timeline/data/entities/cultures/cul_aksumite.json"},{"id":"cul_fon","name":"Fon","region":["West Africa"],"date_range":null,"notes":"Fon-speaking (Gbe-language-family) peoples of the Kingdom of Dahomey, modern Benin; oral tradition traces migration from Tado (Mono River) via Allada to Abomey, linguistically dated by comparative Gbe scholarship to roughly the 12th-13th century CE.","_entity_type":"Culture","_source_path":"docs/timeline/data/entities/cultures/cul_fon.json"},{"id":"cul_juhoansi","name":"Ju/'hoansi","region":["Southern Africa"],"date_range":null,"notes":"A San language/cultural group of the Nyae Nyae/Dobe area (Namibia-Botswana border region); living communities, documented chiefly via 20th-century ethnography (Marshall, Lee, Shostak, Katz, Biesele, Wiessner). Distinct from /Xam.","_entity_type":"Culture","_source_path":"docs/timeline/data/entities/cultures/cul_juhoansi.json"},{"id":"cul_kongo","name":"BaKongo (Kingdom of Kongo)","region":["Central Africa"],"date_range":{"earliest":1390,"latest":1914,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"notes":"Kikongo-speaking peoples of the Kongo Kingdom, modern northern Angola/western DRC/Republic of Congo.","_entity_type":"Culture","_source_path":"docs/timeline/data/entities/cultures/cul_kongo.json"},{"id":"cul_shona","name":"Shona","region":["Southern Africa"],"date_range":null,"notes":"Shona-speaking peoples of the Zimbabwean plateau, historically including the Great Zimbabwe state and later Rozvi (Changamire) polity.","_entity_type":"Culture","_source_path":"docs/timeline/data/entities/cultures/cul_shona.json"},{"id":"cul_xam","name":"/Xam","region":["Southern Africa"],"date_range":{"earliest":1700,"latest":1910,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"notes":"A distinct San language/cultural group, Cape Colony region; the spoken /Xam language and its living tradition did not survive the early 20th century. Not interchangeable with \"San\" generally or with Ju/'hoansi — a genuinely distinct group, period, and evidentiary base (primarily the 1870s-1880s Bleek-Lloyd archive).","_entity_type":"Culture","_source_path":"docs/timeline/data/entities/cultures/cul_xam.json"},{"id":"cul_yoruba","name":"Yoruba","region":["West Africa"],"date_range":null,"notes":"Historical Yorubaland: modern southwestern Nigeria, Benin, Togo.","_entity_type":"Culture","_source_path":"docs/timeline/data/entities/cultures/cul_yoruba.json"},{"id":"dty_esu","name":"Èṣù / Eshu (Yoruba)","region":["West Africa"],"identifications":[],"domain_history":[{"domain":"messenger/intermediary between Olódùmarè, the other Òrìṣà, and humanity; enforcer of divine law","claim_id":"claim_esu_domain_and_mistranslation"},{"domain":"mischaracterized as \"Satan\"/\"the Devil\" in 19th-century missionary translation","period":{"earliest":1843,"latest":1900,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"claim_id":"claim_esu_domain_and_mistranslation"}],"notes":"The trickster reputation is explained in devotional/academic-adjacent sources as pedagogical (using irony/paradox to push humans toward wisdom and correct ritual conduct) rather than malevolent — flagged as interpretive gloss, not traced to a single named peer-reviewed anthropologist at HIGH confidence.","_entity_type":"Deity","_source_path":"docs/timeline/data/entities/deities/dty_esu.json"},{"id":"dty_kaggen","name":"/Kaggen (the Mantis, /Xam)","region":["Southern Africa"],"identifications":[],"domain_history":[{"domain":"trickster-creator, shapeshifting (mantis, eland, snake, louse, hare)","claim_id":"claim_kaggen_domain"}],"notes":"Central figure in /Xam narrative as recorded in the Bleek-Lloyd archive; morally ambiguous, not purely benevolent. Creator of the first eland (from a piece of shoe leather, nurtured with honey); when the eland was killed by his in-laws, his tears/released gall created the first darkness. Source: Bleek and Lloyd, Specimens of Bushman Folklore (1911).","_entity_type":"Deity","_source_path":"docs/timeline/data/entities/deities/dty_kaggen.json"},{"id":"dty_mahrem","name":"Mahrem / Maḥrem (Aksum)","region":["Horn of Africa/Aksum"],"identifications":[],"domain_history":[{"domain":"war god; Aksumite kings styled themselves \"son of the invincible Mahrem\" in their own inscriptions","claim_id":"claim_mahrem_attestation"}],"notes":"Attested via interpretatio graeca as \"Ares\" in the Monumentum Adulitanum and directly by name in Ezana's own pre-Christian Ge'ez inscriptions. Comparison to South Arabian war god Almaqah is repeatedly made in secondary literature but the degree of identity is explicitly uncertain — DISPUTED/LOW confidence, not settled equivalence.","_entity_type":"Deity","_source_path":"docs/timeline/data/entities/deities/dty_mahrem.json"},{"id":"dty_mawu_lisa","name":"Mawu-Lisa (Fon)","region":["West Africa"],"identifications":[],"domain_history":[{"domain":"composite creator deity (Mawu: moon/night, female; Lisa: sun/day, male), generated by the withdrawn primordial figure Nana Buluku; head of the Dahomean state pantheon","period":{"earliest":1740,"latest":1774,"precision":"DECADE","date_semantics":"EVENT_DATE"},"claim_id":"claim_mawu_lisa_hwanjile_import"}],"notes":"The Mawu-Lisa cult was imported from Aja territory and installed as head of the Dahomean state pantheon specifically by Hwanjile, the kpojito (\"queen mother\"/reign-mate) of King Tegbesu (r. c.1740-1774) — a documented act of religious-political legitimation tied to consolidating Tegbesu's contested succession, not a static inherited cosmology. Edna G. Bay, Wives of the Leopard: Gender, Politics, and Culture in the Kingdom of Dahomey (University of Virginia Press, 1998).","_entity_type":"Deity","_source_path":"docs/timeline/data/entities/deities/dty_mawu_lisa.json"},{"id":"dty_mwari","name":"Mwari / Mwali (Shona)","region":["Southern Africa"],"identifications":[],"domain_history":[{"domain":"high god, oracular voice delivered through mediums at cave shrines (principal historical shrine: Njelele/Matonjeni, Matopo Hills), consulted especially for rainmaking and political counsel","claim_id":"claim_mwari_structure"}],"notes":"M.L. Daneel, The God of the Matopo Hills: An Essay on the Mwari Cult in Rhodesia (Mouton, 1970), based on 1965-67 fieldwork — foundational modern academic study. Served both Shona/Kalanga and, after Ndebele settlement in the 1830s-40s, Ndebele consultors. See trad_shona_religion for the disputed relationship to Great Zimbabwe/Rozvi political power.","_entity_type":"Deity","_source_path":"docs/timeline/data/entities/deities/dty_mwari.json"},{"id":"dty_nyame","name":"Nyame / Onyankopon (Akan)","region":["West Africa"],"identifications":[],"domain_history":[{"domain":"supreme being/creator; multiple praise-titles (Onyame, Onyankopon, Odomankoma, Borebore) used contextually, not fully interchangeable","claim_id":"claim_nyame_titles"}],"notes":"DISPUTED whether Nyame functions as a deus otiosus (withdrawn, non-interventionist after creation): Danquah's own reading treats Nyame as active/personally addressed; a general comparative-African-religion framing (and a reported, not directly verified, Geoffrey Parrinder reading closer to a first-ancestor figure) leans toward the withdrawn-god pattern — the Danquah/Parrinder disagreement itself is only verified via secondary summary, not primary texts, in this research pass.","_entity_type":"Deity","_source_path":"docs/timeline/data/entities/deities/dty_nyame.json"},{"id":"dty_nzambi_mpungu","name":"Nzambi a Mpungu (Kongo)","region":["Central Africa"],"identifications":[],"domain_history":[{"domain":"high-god/creator term (post-missionary Christianized usage, used to translate the Christian God from the 16th-17th century onward)","period":{"earliest":1600,"latest":1900,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"claim_id":"claim_nzambi_meaning_disputed"},{"domain":"DISPUTED original precolonial meaning: personification of death (MacGaffey 2022, via early-20th-century Laman-collection texts), with the life/creation valence instead carried by bisimbi","claim_id":"claim_nzambi_meaning_disputed"}],"notes":"This project should NOT present \"Nzambi a Mpungu, benevolent sky-father creator\" as settled precolonial fact — see claim_nzambi_meaning_disputed for the two named camps.","_entity_type":"Deity","_source_path":"docs/timeline/data/entities/deities/dty_nzambi_mpungu.json"},{"id":"dty_ogun","name":"Ògún (Yoruba)","region":["West Africa"],"identifications":[],"domain_history":[{"domain":"iron-working, hunting, and war","claim_id":"claim_ogun_domain_history"},{"domain":"expanded to new iron/steel-adjacent technologies over time","claim_id":"claim_ogun_domain_history"}],"notes":"Sandra T. Barnes, ed., Africa's Ogun: Old World and New (Indiana UP, 1989/1997) — standard scholarly edited volume on the deity's transformations across West Africa and the Americas. A popular (non-academic) claim that Ògún was \"a real person, an Ifè king\" could NOT be verified against any academic source — contrast with Ṣàngó below, where historicization is well-attested in academic literature; do not treat the Ògún-as-historical-king claim with the same confidence.","_entity_type":"Deity","_source_path":"docs/timeline/data/entities/deities/dty_ogun.json"},{"id":"dty_osun","name":"Ọ̀ṣun (Yoruba)","region":["West Africa"],"identifications":[],"domain_history":[{"domain":"river deity, wealth, power, and femininity, principal shrine at Òṣogbo","claim_id":"claim_osun_badejo"}],"notes":"Diedre L. Badejo, Ọ̀ṣun Ṣèègèsí: The Elegant Deity of Wealth, Power, and Femininity (Africa World Press, 1996) — described as the first full-length original research study of a major Yorùbá goddess, based on fieldwork at Òṣogbo, tracing her presence across West Africa, Cuba, Brazil, and the US.","_entity_type":"Deity","_source_path":"docs/timeline/data/entities/deities/dty_osun.json"},{"id":"dty_sango","name":"Ṣàngó (Yoruba)","region":["West Africa"],"identifications":[],"domain_history":[{"domain":"thunder and lightning, associated with fire and (in some sources) justice/retribution","claim_id":"claim_sango_historicization"}],"notes":"Historicization: Yorùbá oral-historical tradition (Samuel Johnson, The History of the Yorubas, completed 1897, published 1921) places Ṣàngó within the Òyó Aláàfin king-list, though sources disagree on his exact ordinal position (3rd vs. 4th Aláàfin) — report as \"an early Aláàfin, ordinal position varies by source,\" not a fixed number. Sàngó in Africa and the African Diaspora (eds. Tishken, Falola, Akinyemi; Indiana UP, 2009) is explicitly organized around the mythic/historical/syncretic-diaspora split as an open scholarly question.","_entity_type":"Deity","_source_path":"docs/timeline/data/entities/deities/dty_sango.json"},{"id":"dty_yemoja","name":"Yemọja (Yoruba)","region":["West Africa"],"identifications":[],"domain_history":[{"domain":"river deity, specifically associated with the Ògùn River in Nigeria","claim_id":"claim_yemoja_diaspora_domain_shift"},{"domain":"ocean deity (diaspora domain shift)","period":{"earliest":1600,"latest":1900,"precision":"CENTURY","date_semantics":"ESTIMATED_COMPOSITION"},"claim_id":"claim_yemoja_diaspora_domain_shift"}],"notes":"Weaker sourcing than Ògún/Ṣàngó/Ọ̀ṣun — no single named academic monograph specifically on Yemọja comparable to Badejo's on Ọ̀ṣun was located. The river-to-ocean domain shift in the Americas is widely attested across sources but the specific causal mechanism is not traced to one named academic citation — see claim.","_entity_type":"Deity","_source_path":"docs/timeline/data/entities/deities/dty_yemoja.json"},{"id":"gs_akan_asante","culture_id":"cul_akan_asante","region":["West Africa"],"period":{"earliest":1700,"latest":1900,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"dimensions":{"gendered_labor":{"assessment":"Gracia Clark, Onions Are My Husband: Survival and Accumulation by West African Market Women (University of Chicago Press, 1994), based on 4+ years of fieldwork from 1978, documents women dominating market trade/commerce, including powerful female \"market queens\" controlling wholesale flows of staples at Kumasi Central Market. Men historically dominated hunting, long-distance/inter-regional trade, and certain craft guilds (per Rattray).","confidence":"HIGH","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Clark, Gracia. Onions Are My Husband: Survival and Accumulation by West African Market Women. University of Chicago Press, 1994.","author":"Gracia Clark","year":1994,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"political_inequality":{"assessment":"Central/paramount office (Asantehene, council of elders/kingmakers, and a male bureaucracy expanded in the 1760s \"patrifiliation\" process) was predominantly male; BUT the parallel Asantehemaa/ohemaa (Queen Mother) institution held real, non-symbolic nomination, destoolment-initiation, and judicial powers at every level of the polity. In the 1760s the Kumasi government created stools for sons of the Asantehene and wealthy loyal men (Oberempon), measurably weakening the political weight of matrilineages and female-held authority — \"no women were appointed to the new government\" per Wilks/McCaskie-sourced secondary synthesis. Yaa Asantewaa (district-level Queen Mother of Ejisu) led the 1900 War of the Golden Stool — a real, exceptional case, not evidence of a general pattern of female military command.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Stoeltje, Beverly J. \"Asante Queen Mothers: Precolonial Authority in a Postcolonial Society.\" Research Review, 2003.","author":"Beverly J. Stoeltje","year":2003,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Wilks, Ivor. Asante in the Nineteenth Century: The Structure and Evolution of a Political Order. Cambridge University Press, 1975.","author":"Ivor Wilks","year":1975,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"legal_economic_status":{"assessment":"Matrilineal inheritance (abusua) gave women structural standing as conduits and holders of lineage property/office. Women were not typically economically dependent on husbands (no alimony system; a wife was always assured a place to return to) per secondary synthesis of the customary-law literature.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Rattray, R.S. Ashanti Law and Constitution. Oxford University Press, 1929.","author":"R.S. Rattray","year":1929,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"household_authority":{"assessment":"Underdocumented in this research pass specifically for everyday household decision-making authority (as opposed to political office) — Rattray (1929) reportedly discusses husband/father authority in the customary-legal framework but specific passages were not obtained. Flagged as needing dedicated follow-up rather than inferred.","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Rattray, R.S. Ashanti Law and Constitution. Oxford University Press, 1929.","author":"R.S. Rattray","year":1929,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"gendered_legal_restrictions":{"assessment":"Jean Allman, \"Rounding Up Spinsters: Gender Chaos and Unmarried Women in Colonial Asante,\" Journal of African History 37:2 (1996): 195-214, documents that between 1929-1932 Asante chiefs (entangled with colonial administration) ordered arrest of unmarried women over 15 across rural Asante towns — coercive control over women's labor/reproduction amid colonial economic disruption. This is a colonial-period, not precolonial, data point and should not be read backward without qualification.","confidence":"HIGH","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Allman, Jean. \"Rounding Up Spinsters: Gender Chaos and Unmarried Women in Colonial Asante.\" Journal of African History 37:2, 1996: 195-214.","author":"Jean Allman","year":1996,"venue":"Journal of African History","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"ideological_patriarchy":{"assessment":"Not directly evidenced in this research pass by a named scholar making an explicit textual/oral-tradition claim of women's natural subordination among the Akan — what was found is structural (the 1760s patrifiliation process, male-dominated central office) rather than explicit ideological/textual assertion. Recorded as UNKNOWN rather than inferred from the structural facts, to avoid conflating dimensions.","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General absence of a dedicated ideological-content study found in this research pass.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"notes":"Matrilineal descent (abusua) is a distinct axis from household/political male authority — do not treat matriliny as automatically implying gender egalitarianism (the 1760s patrifiliation process is direct evidence against that inference). Required does_not_demonstrate: Yaa Asantewaa's 1900 war leadership demonstrates the pre-existing Queen Mother institution's real authority could be activated at maximum scale under crisis — not that Asante women generally held military command."},"notes":null,"_entity_type":"GenderSystem","_source_path":"docs/timeline/data/entities/gender_systems/gs_akan_asante.json"},{"id":"gs_aksumite","culture_id":"cul_aksumite","region":["Horn of Africa/Aksum"],"period":{"earliest":1,"latest":700,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"dimensions":{"gendered_labor":{"assessment":"UNKNOWN. No Aksumite-period-specific source was found; projecting later, better-documented highland-Ethiopian labor divisions backward onto Aksum would be unfounded inference and was deliberately not done.","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"Absence of a dedicated Aksumite-period source, explicitly flagged rather than filled by inference.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"political_inequality":{"assessment":"Every securely Aksumite-attested monarch in king lists, coinage, and inscriptions is male; Ezana's own inscriptions name only male co-rulers/relatives. No surviving Aksumite legal text formally excludes women from rule, so \"formal exclusion\" itself is UNKNOWN — only the observed pattern is documented. Important negative finding: the \"Candace\"/Kandake queen-mother matrilineal-succession tradition belongs to the separate Kingdom of Kush/Meroë, not Aksum — popular sources conflate them, and this project should not. A claim of \"21 queens ruling Ethiopia until the 9th century\" traces to later Ethiopian oral tradition/king-lists, not Aksumite-period inscriptions or archaeology, and could not be traced to a primary citation — report as unverified likely later political tradition, not fact.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Munro-Hay, Stuart C. Aksum: An African Civilization of Late Antiquity. Edinburgh University Press, 1991.","author":"Stuart C. Munro-Hay","year":1991,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"legal_economic_status":{"assessment":"UNKNOWN for the Aksumite period — no surviving Aksumite legal code exists at all. The Fetha Nagast (sometimes loosely cited for \"Ethiopian law\") is a 13th-century Coptic-Arabic compilation only translated into Ge'ez in the 15th century; applying it to Aksum (already declined by then) would be anachronistic.","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General absence of a surviving Aksumite legal corpus, noted across the consulted secondary literature.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"household_authority":{"assessment":"UNKNOWN for the Aksumite period specifically. (A separately-dated, better-documented data point exists for the medieval/early-modern Christian-Ethiopian highland period — Allan Hoben, Land Tenure Among the Amhara of Ethiopia, University of Chicago Press, 1973, documents the rist land-tenure system as bilateral/cognatic, giving women independently litigable land claims — but this is centuries after Aksum's decline and is deliberately NOT merged into this Aksumite-period record.)","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Hoben, Allan. Land Tenure Among the Amhara of Ethiopia: The Dynamics of Cognatic Descent. University of Chicago Press, 1973 — cited here only to explain why it is NOT used to fill this Aksumite-period gap.","author":"Allan Hoben","year":1973,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"gendered_legal_restrictions":{"assessment":"UNKNOWN for the Aksumite period specifically. (A separately-dated medieval/early-modern data point exists: Zär'a Ya'ǝqob, r. 1434-1468, undertook documented marriage-law reform campaigns against polygamy; Emperor Menilek II's 1908 decree formally banned polygamy for Christians while he himself practiced it selectively — but these post-date Aksum by roughly a millennium and are not merged into this record.)","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General absence of an Aksumite-period-specific source, explicitly flagged.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"ideological_patriarchy":{"assessment":"UNKNOWN/LOW direct evidence for the Aksumite period — no surviving religious-ideological text on gender hierarchy from this period was located.","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General absence of a dedicated source, explicitly flagged.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"notes":"This record is deliberately UNKNOWN-heavy — it reflects genuine evidentiary thinness for the ancient Aksumite period specifically, not a research shortfall to paper over. Later medieval/early-modern Christian-Ethiopian (Amhara-highland) gender history is a separate, much better-documented topic explicitly not merged in here; it would need its own Culture entity and GenderSystem record in a future research batch."},"notes":null,"_entity_type":"GenderSystem","_source_path":"docs/timeline/data/entities/gender_systems/gs_aksumite.json"},{"id":"gs_fon","culture_id":"cul_fon","region":["West Africa"],"period":{"earliest":1645,"latest":1894,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"dimensions":{"gendered_labor":{"assessment":"Women documented as dominant in regional textile/fabric trade and general market commerce (a general West-African-coast pattern; Dahomey-specific sourcing in what was accessible this pass was weaker than the general regional corroboration).","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General West African market-commerce literature, Bight of Benin coast.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"political_inequality":{"assessment":"A documented dual-sex administrative structure existed: each male titled court official reportedly had a female counterpart (\"mother\"/parallel officer), described in Herskovits's 1938 ethnography and elaborated by Edna Bay, with systematization sometimes attributed specifically to King Ghezo (r. 1818-1858). This is a real parallel-hierarchy structure, but Bay's broader thesis is that it may have functioned as much as royal surveillance/control of male officials as female empowerment per se, and that women's (and lower-class men's) access to power in this system contracted over the 19th century as slave-trade-derived economic resources declined.","confidence":"MODERATE","claim_tier":"INTERPRETATION","sources":[{"type":"PRIMARY","citation":"Bay, Edna G. Wives of the Leopard: Gender, Politics, and Culture in the Kingdom of Dahomey. University of Virginia Press, 1998.","author":"Edna G. Bay","year":1998,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Herskovits, Melville J. Dahomey: An Ancient West African Kingdom. J.J. Augustin, 1938.","author":"Melville J. Herskovits","year":1938,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"legal_economic_status":{"assessment":"General regional (West African, polygynous-system) customary-law literature suggests inheritance-share/maternal-resource-claim protections for women, but this was not confirmed as Dahomey-specific in what was accessible this research pass — treat as a weak proxy only, not a confirmed Dahomean finding.","confidence":"LOW","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General West African customary-law/kinship literature, not confirmed Dahomey-specific.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"household_authority":{"assessment":"Not independently verified for ordinary (non-royal) Fon households in this research pass. The ahosi (\"king's wives\") royal-household system is documented (numbering in the hundreds; all Agojie were nominally counted as ahosi, though not all ahosi were Agojie), but this is a royal-household-specific data point, not evidence about ordinary household authority patterns.","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General absence of ordinary-household-specific sourcing, explicitly flagged.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"gendered_legal_restrictions":{"assessment":"Polygyny was normative (documented structurally via the royal ahosi system); specific restrictions on ordinary women (movement, testimony, property rights) were not found in accessible sourcing this pass — do not assert specifics beyond \"polygyny was the norm.\"","confidence":"LOW","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General absence of itemized-restriction sourcing beyond the polygyny norm, explicitly flagged.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"ideological_patriarchy":{"assessment":"Robin Law, \"The 'Amazons' of Dahomey,\" Paideuma 39 (1993): 245-260, argues trained female warriors (Agojie/Mino) were culturally understood to symbolically \"become men,\" especially at the moment of a first kill — direct evidence the conceptual category of \"warrior\" remained gendered male even when filled by women, i.e. evidence of an underlying patriarchal ideological structure persisting alongside, not contradicted by, the Agojie's existence. Agojie were also required to be nominally celibate/non-childbearing during active service, and some were conscripted after being reported for \"misconduct\" by husbands/fathers — a disciplinary/control mechanism exercised by male kin, closer to evidence of subordination than empowerment.","confidence":"MODERATE","claim_tier":"INTERPRETATION","sources":[{"type":"PRIMARY","citation":"Law, Robin. \"The 'Amazons' of Dahomey.\" Paideuma: Mitteilungen zur Kulturkunde 39, 1993: 245-260.","author":"Robin Law","year":1993,"venue":"Paideuma","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"notes":"Required does_not_demonstrate re: the Agojie/Mino (see claim_agojie_does_not_demonstrate): their existence as a real, large, professionally organized, combat-effective female military institution does NOT demonstrate general Fon/Dahomean gender equality — Law's \"become men\" argument, the enforced-celibacy service requirement, and the misconduct-based conscription channel all point toward the institution operating within, not against, an underlying patriarchal structure. Stanley B. Alpern, Amazons of Black Sparta: The Women Warriors of Dahomey (NYU Press, 1998; 2nd ed. Hurst, 2011) is the standard monograph on the corps itself; its popular film treatment (The Woman King, 2022) is documented to substantially sanitize Dahomey's slave-trade economy and Ghezo's role in it — do not import the film's framing."},"notes":null,"_entity_type":"GenderSystem","_source_path":"docs/timeline/data/entities/gender_systems/gs_fon.json"},{"id":"gs_juhoansi","culture_id":"cul_juhoansi","region":["Southern Africa"],"period":{"earliest":1950,"latest":1990,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"dimensions":{"gendered_labor":{"assessment":"Men predominantly hunt, women predominantly gather, but gathered plant foods made up roughly two-thirds of caloric intake in Lee's Dobe-area data — women's labor was the larger single source of subsistence calories. Women are documented as owning/distributing meat as arrow-owners even without hunting themselves; female hunting occurs but is atypical (San-specific frequency not quantified in sources found). Women's central role in the healing dance (singers/clappers, and per Katz roughly 1/4 of healers) is a documented exception to a gathering-only framing.","confidence":"HIGH","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Lee, Richard B. The !Kung San: Men, Women, and Work in a Foraging Society. Cambridge University Press, 1979.","author":"Richard B. Lee","year":1979,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"political_inequality":{"assessment":"DISPUTED on two axes. Gender axis: Lorna Marshall's Nyae Nyae fieldwork documents headmen with no formal privileges, achieved (not inherited) status, and consensus decision-making in which women's voices are documented as part of the process — but headmen in recorded cases appear predominantly male; no documented female headman among Ju/'hoansi specifically was located. Structural-historical axis (the \"Kalahari Debate\"): Lee/DeVore/Solway treated observed egalitarianism as reflecting a foraging-adapted social system; Edwin Wilmsen (Land Filled with Flies, University of Chicago Press, 1989) and James Denbow argued the San had been enmeshed in regional trade/political relationships with Bantu agropastoralists for up to ~1,500 years and that observed \"egalitarianism\" partly reflects a historically produced underclass position, not a pristine foraging baseline; Lee and Solway later co-acknowledged a long interaction history rather than pristine isolation.","confidence":"DISPUTED","claim_tier":"INTERPRETATION","sources":[{"type":"PRIMARY","citation":"Wilmsen, Edwin. Land Filled with Flies: A Political Economy of the Kalahari. University of Chicago Press, 1989.","author":"Edwin Wilmsen","year":1989,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Lee, Richard B., and Jacqueline Solway. \"Foragers, Genuine or Spurious? Situating the Kalahari San in History.\" Current Anthropology.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"legal_economic_status":{"assessment":"Land/resource tenure organized around the n!ore (band territory) with k'\"ausi (owners of the waterhole/resources), typically related elders with continuous tenure rights. Polly Wiessner's hxaro system (delayed-reciprocity gift exchange, PhD thesis 1977) documents both men and women holding and initiating individual exchange partnerships granting access to resources up to ~200km from home n!ore. Women's arrow-ownership functions as a documented, specific instance of female economic entitlement independent of the hunt.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Wiessner, Polly. \"Hxaro: A Regional System of Reciprocity for Reducing Risk among the !Kung San.\" PhD thesis, 1977.","author":"Polly Wiessner","year":1977,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"household_authority":{"assessment":"Marjorie Shostak, Nisa: The Life and Words of a !Kung Woman (Harvard UP, 1981) documents bride-service of roughly 8-10 years (groom labors for bride's family before independent residence), often following marriages arranged for very young (sometimes pre-pubescent) girls to considerably older men — the age gap cited as part of the reason bride-service exists. Household labor is not rigidly gender-segregated: men participate in gathering and child discipline alongside wives. Nisa's own account documents a woman successfully resisting/fleeing an arranged marriage she did not consent to — real, documented female agency within the system.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Shostak, Marjorie. Nisa: The Life and Words of a !Kung Woman. Harvard University Press, 1981.","author":"Marjorie Shostak","year":1981,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"gendered_legal_restrictions":{"assessment":"Arranged, often significant-age-gap marriage for young/pre-pubescent girls to older partners is documented as a real, differentially-applied norm (girls, not boys, married young to older partners). Polygyny is documented but statistically concentrated among healers with strong reputations, suggesting it functions partly as a status marker tied to religious/healing prestige rather than general practice.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Shostak, Marjorie. Nisa: The Life and Words of a !Kung Woman. Harvard University Press, 1981.","author":"Marjorie Shostak","year":1981,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"ideological_patriarchy":{"assessment":"No basis found for either \"straightforwardly subordinates women\" or \"straightforwardly gender-egalitarian\" as a documented scholarly consensus for Ju/'hoansi cosmology specifically — report as genuinely unresolved rather than picking a side.","confidence":"UNKNOWN","claim_tier":"INTERPRETATION","sources":[{"type":"SECONDARY","citation":"General absence of a dedicated study found in this research pass.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"notes":"Distinct group/period from /Xam (gs_xam) — do not merge. Do not import Apollo 11 Cave rock-art age (~26,000-30,000 BP) or Khoe-San population-genetic divergence dates (Chan et al. 2019, Nature, itself disputed by other geneticists) into any claim about the age of this specific documented social/gender system — those are categorically different kinds of evidence."},"notes":null,"_entity_type":"GenderSystem","_source_path":"docs/timeline/data/entities/gender_systems/gs_juhoansi.json"},{"id":"gs_kongo","culture_id":"cul_kongo","region":["Central Africa"],"period":{"earliest":1491,"latest":1710,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"dimensions":{"gendered_labor":{"assessment":"Women bore substantial (commonly majority) agricultural labor responsibility; men controlled resource allocation/distribution; polygyny functioned partly to expand household labor capacity and cement inter-lineage alliances. Kongo-specific (16th-18th century) sourcing distinct from general Bantu Central African ethnography extrapolated backward was not located — flagged as a real limitation.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General Central African Bantu-region ethnographic/historical literature on gendered agricultural labor.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"political_inequality":{"assessment":"Kingship (manikongo) was male-only. The queen mother held recognized special status and could serve as regent during royal minorities. Thornton (2006) documents that after the civil wars beginning 1665 (Battle of Mbwila), elite women began exercising overt, direct territorial/political control in some provinces, independent of male relatives, a shift from the earlier (16th-17th c.) pattern of indirect influence through male relatives. Elite Kongo women never took formal sovereign control of the state itself — unlike the related-but-distinct kingdoms of Ndongo and Matamba, where Njinga Mbande held the throne outright as reigning monarch (r. from 1624) — this is a different polity and must not be conflated with Kongo.","confidence":"HIGH","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Thornton, John K. \"Elite Women in the Kingdom of Kongo: Historical Perspectives on Women's Political Power.\" Journal of African History 47(3), 2006: 437-460.","author":"John K. Thornton","year":2006,"venue":"Journal of African History","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"legal_economic_status":{"assessment":"Elite women could accumulate significant personal wealth and control lineage assets directly. No Kongo-specific (rather than modern-DRC) source on formal legal doctrine (inheritance law, property litigation) for the historical kingdom was located — flagged UNKNOWN at that level of granularity.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Thornton, John K. \"Elite Women in the Kingdom of Kongo.\" Journal of African History 47(3), 2006.","author":"John K. Thornton","year":2006,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"MacGaffey, Wyatt. Kongo Political Culture: The Conceptual Challenge of the Particular. Indiana University Press, 2000.","author":"Wyatt MacGaffey","year":2000,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"household_authority":{"assessment":"DISPUTED. Kongo kinship is not simply matrilineal: Wyatt MacGaffey, \"A Note on Vansina's Invention of Matrilinearity,\" Journal of African History 54(2), 2013, critiques Jan Vansina's Paths in the Rainforests (1990) thesis that matrilineality was a datable historical \"invention\"/development in the Lower Congo region, arguing instead for persistent, complex, often bilateral kinship forms. Even where matrilineal descent-group membership existed, authority over matrilineal kin groups typically rested with maternal uncles, not the women themselves (the general Central African \"matrilineal puzzle\" pattern) — a point drawn from broader regional scholarship, not confirmed as a Kongo-specific MacGaffey/Thornton statement in this pass.","confidence":"DISPUTED","claim_tier":"INTERPRETATION","sources":[{"type":"PRIMARY","citation":"MacGaffey, Wyatt. \"A Note on Vansina's Invention of Matrilinearity.\" Journal of African History 54(2), 2013: 269-280.","author":"Wyatt MacGaffey","year":2013,"venue":"Journal of African History","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Vansina, Jan. Paths in the Rainforests. University of Wisconsin Press, 1990.","author":"Jan Vansina","year":1990,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"gendered_legal_restrictions":{"assessment":"UNKNOWN at meaningful historical granularity. No period-specific (pre-19th-century) documentation of formal legal restrictions specifically targeting women was located distinct from general regional custom; polygyny was normative and male-privileging in structure, a documented structural (not itemized-legal-code) asymmetry.","confidence":"LOW","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General absence of a dedicated primary-source study found in this research pass; recommend Cavazzi's 17th-century account as a likely source base for follow-up.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"ideological_patriarchy":{"assessment":"Male exclusivity of the kingship itself, and primogeniture doctrine specifically imported/reinforced by Afonso I to strengthen his succession claim, together constitute documented ideological-structural male privileging at the level of dynastic ideology, alongside normative polygyny. Deeper cosmological argumentation for gendered political authority was not traced to a specific named scholar in this pass.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"EBSCO Research Starters / Britannica summary on Afonso I's use of primogeniture doctrine.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"notes":"Required does_not_demonstrate re: Kimpa Vita (see claim_kimpa_vita_does_not_demonstrate) — her case demonstrates a Kongo woman could achieve the highest tier of religious-political authority available, within a preexisting cultural space for female spirit possession, but does NOT demonstrate routine/institutionalized female political authority generally, nor comparable access for non-elite women; her authority was charismatic/crisis-contingent, and she was ultimately tried and executed as a heretic by the same institutional structure that had elsewhere accommodated elite women's authority."},"notes":null,"_entity_type":"GenderSystem","_source_path":"docs/timeline/data/entities/gender_systems/gs_kongo.json"},{"id":"gs_shona","culture_id":"cul_shona","region":["Southern Africa"],"period":{"earliest":1700,"latest":1900,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"dimensions":{"gendered_labor":{"assessment":"Clear sexual division of labor: women performed the bulk of routine farming/cultivation, food processing, brewing, pottery, domestic labor; men handled cattle-herding, hunting, ironworking, and heavier land-clearing tasks. Cattle, the primary wealth/status marker, were male-controlled.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"Everyculture.com ethnographic summary, consistent with Bourdillon 1976 and Schmidt 1992 general findings; not independently cross-checked against Bourdillon's full monograph text in this research pass.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"political_inequality":{"assessment":"Formal chieftainship was overwhelmingly male; the Charewa chieftaincy (Mutoko district) is cited in the literature as one of the only recorded exceptions to female exclusion from political authority. Colonial administration (Native Commissioners) further entrenched, and in some cases retroactively invented, \"male-only\" succession norms with no precolonial precedent, erasing prior instances of women's political roles. Women held real but informal authority as mothers, as vatete (paternal aunts, with authority over brothers' children's upbringing/marriage), and as senior women over married daughters' households. Mbuya Nehanda, medium of the Nehanda mhondoro spirit, was a central religious-political leader of the 1896-97 First Chimurenga, executed 27 April 1898 — an exceptional case (see notes for the required does_not_demonstrate analysis), not evidence of general female political authority.","confidence":"HIGH","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Terence Ranger, Revolt in Southern Rhodesia 1896-97: A Study in African Resistance. Heinemann, 1967.","author":"Terence Ranger","year":1967,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"David Beach, \"An Innocent Woman, Unjustly Accused? Charwe, Medium of Nehanda Mhondoro Spirit, and the 1896-97 Central Shona Rising in Zimbabwe.\" 1998.","author":"David Beach","year":1998,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"legal_economic_status":{"assessment":"Diana Jeater, Marriage, Perversion, and Power: The Construction of Moral Discourse in Southern Rhodesia, 1894-1930 (Oxford, Clarendon Press, 1993) is the standard academic source on colonial-era customary-law codification of marriage; Elizabeth Schmidt (1992, see ideological_patriarchy below) argues colonial \"customary law\" codification interacted with and worsened women's economic position, layering European patriarchal legal concepts atop Shona patrilineal structures — restricting women's mobility, independent trade, etc. This is documented for the colonial period specifically; direct-text verification of exact phrasing (e.g. a \"perpetual legal minor\" characterization) was not completed in this research pass.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Jeater, Diana. Marriage, Perversion, and Power: The Construction of Moral Discourse in Southern Rhodesia, 1894-1930. Oxford: Clarendon Press, 1993.","author":"Diana Jeater","year":1993,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"household_authority":{"assessment":"Patrilineal, patrilocal kinship system: at marriage, women moved into the husband's family homestead/lineage; descent, lineage headship, and household authority passed through the male line.","confidence":"HIGH","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General ethnographic consensus, Bourdillon, M.F.C. The Shona Peoples. Mambo Press, 1976 (cited via secondary summary).","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"gendered_legal_restrictions":{"assessment":"The roora/lobola (bride-wealth, typically cattle) system: rutsambo (paid first, establishing a husband's sexual rights) and roora (paid over time, establishing paternal rights to children) are documented marriage-transfer institutions. The degree to which this system was/is exploitative (invoked to assert ownership-like claims over a wife) is debated among contemporary Zimbabwean scholars; the basic institutional structure (patrilineal transfer via bride-wealth) is not disputed.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General Zimbabwean gender-scholarship literature on roora/lobola, including contemporary debate on the \"mapere/hyena\" metaphor.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"ideological_patriarchy":{"assessment":"Elizabeth Schmidt, Peasants, Traders, and Wives: Shona Women in the History of Zimbabwe, 1870-1939 (Heinemann/Baobab Books/James Currey, 1992), argues women's status declined over the colonial period specifically because preexisting Shona patriarchal controls (over labor, marriage, sexuality) were reinforced by and interacted with an added layer of European colonial patriarchal structures (missionary education norms, colonial administrative law) — a dual-patriarchy thesis, not a claim colonialism created inequality from nothing.","confidence":"MODERATE","claim_tier":"INTERPRETATION","sources":[{"type":"PRIMARY","citation":"Schmidt, Elizabeth. Peasants, Traders, and Wives: Shona Women in the History of Zimbabwe, 1870-1939. Portsmouth, NH: Heinemann; Harare: Baobab Books; London: James Currey, 1992.","author":"Elizabeth Schmidt","year":1992,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"notes":"Required does_not_demonstrate re: Mbuya Nehanda — her case demonstrates a specific woman could and did hold the highest religious-political authority position available at a moment of national crisis, and that spirit mediumship was not gender-restricted at the top tier (mediums could be possessed by a spirit of either sex). It does NOT demonstrate general political, legal, or economic equality for Shona women — mediumship access ran through spiritual selection, a fundamentally different channel from ordinary secular office, landholding, marriage law, or household headship, all structurally male-dominated in the same society per the dimensions above."},"notes":null,"_entity_type":"GenderSystem","_source_path":"docs/timeline/data/entities/gender_systems/gs_shona.json"},{"id":"gs_xam","culture_id":"cul_xam","region":["Southern Africa"],"period":{"earliest":1800,"latest":1884,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"dimensions":{"gendered_labor":{"assessment":"UNKNOWN with any precision for /Xam specifically beyond what the Bleek-Lloyd narrative content implies; not separately documented as an ethnographic subject in the archive as recorded.","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Bleek, Wilhelm, and Lucy Lloyd. Specimens of Bushman Folklore. 1911 (archive material, 1870s-1884).","author":null,"year":1911,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"political_inequality":{"assessment":"UNKNOWN — the /Xam informant community as recorded (via Cape Colony prisoners) does not provide documented evidence of political/leadership structure comparable to what exists for Ju/'hoansi.","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"Bank, Andrew. Bushmen in a Victorian World. Double Storey/Juta, 2006.","author":"Andrew Bank","year":2006,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"legal_economic_status":{"assessment":"UNKNOWN — not documented in the accessible archive material for this research pass.","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Bleek and Lloyd archive, general.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"household_authority":{"assessment":"UNKNOWN — not documented in the accessible archive material for this research pass.","confidence":"UNKNOWN","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Bleek and Lloyd archive, general.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"gendered_legal_restrictions":{"assessment":"Extensive documented menarcheal-seclusion cosmology: a secluded girl is symbolically equated with the potency of the new moon and !Khwa (the Rain); violating seclusion rules is narrated as having severe consequences (a man who looks at her turns to stone/tree). No equivalent seclusion/restriction practice documented for post-pubescent men — an asymmetric, sex-specific regulatory system as recorded.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"PRIMARY","citation":"Hewitt, Roger. Structure, Meaning and Ritual in the Narratives of the Southern San. 1986.","author":"Roger Hewitt","year":1986,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"ideological_patriarchy":{"assessment":"DISPUTED/genuinely mixed evidence. Female figures are cosmologically significant and not uniformly subordinate (the \"Girl who made the Milky Way\" narrative centers a female creator-figure), but the menarcheal-girl material frames female reproductive potency as simultaneously powerful and dangerous to men — a \"potency-as-danger\" framing distinct from a simple subordination/celebration binary. Anne Solomon, \"Mythic Women\": A Study in Variability in San Rock Art and Narrative (in Lewis-Williams & Dowson, eds., Contested Images, Witwatersrand UP, 1994), concludes gender representation in San rock art/narrative does not reduce to one settled pattern and varies across sites/groups/genres — that non-conclusion is itself the most defensible finding.","confidence":"DISPUTED","claim_tier":"INTERPRETATION","sources":[{"type":"PRIMARY","citation":"Solomon, Anne. \"'Mythic Women': A Study in Variability in San Rock Art and Narrative.\" In Contested Images: Diversity in Southern African Rock Art Research, eds. Lewis-Williams and Dowson. Witwatersrand University Press, 1994.","author":"Anne Solomon","year":1994,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"notes":"/Xam is a distinct group/period from Ju/'hoansi (gs_juhoansi) — do not merge these two GenderSystem records into one \"San\" verdict. Evidentiary base is almost entirely the 1870s-1880s Bleek-Lloyd archive, filtered through Victorian transcription and a coercive collection context (informants were Cape Colony prisoners)."},"notes":null,"_entity_type":"GenderSystem","_source_path":"docs/timeline/data/entities/gender_systems/gs_xam.json"},{"id":"gs_yoruba","culture_id":"cul_yoruba","region":["West Africa"],"period":{"earliest":1700,"latest":1900,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"dimensions":{"gendered_labor":{"assessment":"Labor divided by sex (men: farming, hunting, crafts; women: trading, food processing, mat-weaving, pottery, cooking) but with documented situational flexibility, not rigidity; women held a dominant, well-evidenced role in long-distance trade specifically, a major avenue for wealth accumulation and title-acquisition.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General ethnographic/historical consensus on Yorùbá gendered labor and women's trade dominance.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"political_inequality":{"assessment":"Central state offices (Aláàfin, Òyó Mèsì, most town obas) were predominantly male, but the Ìyálóde title (\"mother of the women\") held real, non-ceremonial legislative and judicial authority on councils alongside male chiefs; a named historical example, Efúnṣetán Aníwúrà (second Ìyálóde of Ìbàdàn), built one of the largest 19th-century fortunes via long-distance trade (including the slave trade) and used wealth/position to strengthen Ìbàdàn's military. Does NOT demonstrate comparable rates of office-holding between men and women, nor integration into the general chieftaincy structure beyond the parallel women's-affairs office.","confidence":"MODERATE","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"Bolanle Awe, doctoral work on 19th-century militarized Ìbàdàn (pioneering Nigerian historian of women); general secondary sourcing on the Ìyálóde/Ìyálója/Ìyálàje titles and Efúnṣetán Aníwúrà.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"legal_economic_status":{"assessment":"Both men and women held rights to possess property including land, generally as communal/family rather than strictly individual property in the precolonial era. Multiple sources frame colonial administration as having fixed binary gender categories and concentrated property/inheritance rights in male hands via imposed patrilineal succession rules — an increase in gender-based property restriction attributed to the colonial period, not a straightforward codification of a preexisting patriarchal baseline. This causal claim could not be traced to one specific peer-reviewed citation with a named author in this research pass.","confidence":"MODERATE","claim_tier":"INTERPRETATION","sources":[{"type":"SECONDARY","citation":"General literature associated with the Oyèrónkẹ́ Oyěwùmí school on colonial-era gender-category imposition.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"household_authority":{"assessment":"Insa Nolte, \"Yoruba Histories of Marriage and Belonging: Gender, Power and Innovation in Eighteenth-Century West Africa,\" Gender & History (Wiley), using ìtàn (oral-historical genre) as evidence, argues marriage structured 18th-century Yorùbá political/social change and that patrilineal kinship associated \"husbandly\" authority-and-belonging-by-birth roles with power, and \"wifely\" support/outsider-origin roles with less — but crucially \"husbandly roles were frequently open to women,\" i.e. authority attached more to a kinship role than to biological sex per se.","confidence":"MODERATE","claim_tier":"INTERPRETATION","sources":[{"type":"PRIMARY","citation":"Nolte, Insa. \"Yoruba Histories of Marriage and Belonging: Gender, Power and Innovation in Eighteenth-Century West Africa.\" Gender & History, Wiley.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"gendered_legal_restrictions":{"assessment":"Polygyny was normative/legal for men (multiple wives); no source found showing an equivalent legal/customary allowance for women to take multiple husbands — an asymmetry, though thinly sourced beyond this. Premarital chastity norms, adultery penalties by sex, and divorce-initiation rights specifically for precolonial Yorùbá society were not confirmed by academic sourcing in this research pass.","confidence":"LOW","claim_tier":"OBSERVATION","sources":[{"type":"SECONDARY","citation":"General ethnographic consensus on normative Yorùbá polygyny.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"evidence":[],"change_events":[]},"ideological_patriarchy":{"assessment":"DISPUTED at the center of Yorùbá gender scholarship. Oyèrónkẹ́ Oyěwùmí, The Invention of Women: Making an African Sense of Western Gender Discourses (University of Minnesota Press, 1997), argues gender was not an indigenous organizing principle in precolonial Yorùbá society — social hierarchy ran on seniority (age), not sex, and systematic gender categorization/ideological subordination was a colonial import. Bibi Bakare-Yusuf, \"Yorubas Don't Do Gender: A Critical Review of Oyèrónkẹ́ Oyěwùmí's The Invention of Women,\" directly challenges this as overstated. No independent third source citing specific Yorùbá proverbs/oral literature/ritual texts asserting female natural subordination was located — the dispute itself is documented; the underlying primary textual evidence is thin on both sides.","confidence":"DISPUTED","claim_tier":"INTERPRETATION","sources":[{"type":"PRIMARY","citation":"Oyěwùmí, Oyèrónkẹ́. The Invention of Women: Making an African Sense of Western Gender Discourses. University of Minnesota Press, 1997.","author":"Oyèrónkẹ́ Oyěwùmí","year":1997,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Bakare-Yusuf, Bibi. \"Yorubas Don't Do Gender: A Critical Review of Oyèrónkẹ́ Oyěwùmí's The Invention of Women.\"","author":"Bibi Bakare-Yusuf","year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"evidence":[],"change_events":[]},"notes":"Ifá priesthood (babaláwo) gender: historically male-dominated in most documented lineages; the Iyanifa/Ìyánífá controversy over female initiation is live and explicitly split by lineage (Nigerian lineages more accepting; some Cuban Lucumí lineages rejecting) — see claim_iyanifa_controversy. Required does_not_demonstrate note: Efúnṣetán Aníwúrà and the Ìyálóde institution demonstrate some Yorùbá women held real political/economic power; they do NOT demonstrate general gender egalitarianism or resolve the Oyěwùmí/Bakare-Yusuf dispute."},"notes":null,"_entity_type":"GenderSystem","_source_path":"docs/timeline/data/entities/gender_systems/gs_yoruba.json"},{"id":"pop_denisovan","name":"Denisovan","taxonomic_status":{"classification":"Denisovan (informal name; no Linnaean binomial formally and uncontestedly established at time of writing)","disputed":true,"alternative_classifications":["Identified primarily via ancient DNA rather than a type fossil in the traditional sense — see claim_denisovan_genome_before_morphology"]},"date_range":{"earliest":-250000,"latest":-52000,"precision":"ORDER_OF_MAGNITUDE","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Central Asia","East Asia"],"notes":"Type site is Denisova Cave, Siberia. The Xiahe mandible (Tibetan Plateau, ≥160,000 years) is the first physical evidence outside the type site — see claim_xiahe_mandible.","_entity_type":"Population","_source_path":"docs/timeline/data/entities/populations/pop_denisovan.json"},{"id":"pop_early_homo","name":"Early Homo (genus-level, earliest attestation)","taxonomic_status":{"classification":"Genus Homo, unassigned to species at the earliest attested material","disputed":true,"alternative_classifications":["Some researchers dispute genus-level assignment of the earliest (LD 350-1) specimen from dental/mandibular material alone","A 2026 minority proposal (Towle) would fold Australopithecus, Paranthropus, and Kenyanthropus into an expanded Homo reaching back ~4-5 Ma"]},"date_range":{"earliest":-2800000,"latest":-2500000,"precision":"ORDER_OF_MAGNITUDE","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Africa"],"notes":"Represents the taxonomically contested earliest material assigned to genus Homo, not a coherent single population. See claim_ld350_earliest_homo and claim_ledi_geraru_overlap_2025.","_entity_type":"Population","_source_path":"docs/timeline/data/entities/populations/pop_early_homo.json"},{"id":"pop_homo_erectus","name":"Homo erectus","taxonomic_status":{"classification":"Homo erectus (sensu lato, worldwide polytypic species — trending majority position)","disputed":true,"alternative_classifications":["Homo ergaster for early/African material, Homo erectus sensu stricto reserved for Asian material (Groves & Mazák 1975; defended on phylogenetic grounds by Wood & Collard 1999)","Homo georgicus proposed by some for the Dmanisi material specifically (minority position)"]},"date_range":{"earliest":-1900000,"latest":-108000,"precision":"ORDER_OF_MAGNITUDE","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Africa","Europe","East Asia","Southeast Asia"],"notes":"Latest date (108,000 ya, Ngandong, Java) and earliest date (1.9 Ma, East Turkana) are both fossil-evidence bounds, not the true origin/extinction of the population.","_entity_type":"Population","_source_path":"docs/timeline/data/entities/populations/pop_homo_erectus.json"},{"id":"pop_homo_habilis","name":"Homo habilis","taxonomic_status":{"classification":"Homo habilis (Leakey, Tobias & Napier 1964)","disputed":true,"alternative_classifications":["Homo habilis sensu stricto + Homo rudolfensis (Wood 1991 split, supported by Spoor et al. 2015)"]},"date_range":{"earliest":-2400000,"latest":-1500000,"precision":"ORDER_OF_MAGNITUDE","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Africa"],"notes":null,"_entity_type":"Population","_source_path":"docs/timeline/data/entities/populations/pop_homo_habilis.json"},{"id":"pop_homo_sapiens","name":"Homo sapiens","taxonomic_status":{"classification":"Homo sapiens","disputed":false,"alternative_classifications":[]},"date_range":{"earliest":-315000,"latest":null,"precision":"ORDER_OF_MAGNITUDE","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Africa"],"gene_flow_edges":[{"with_population_id":"pop_neanderthal","direction":"BIDIRECTIONAL","confidence":"HIGH","estimated_percentage_range":{"low":1.5,"high":2.6,"applies_to":"non-African modern populations (varies by population; see claim_neanderthal_ancestry_by_population)"},"claim_id":"claim_neanderthal_ancestry_by_population"},{"with_population_id":"pop_denisovan","direction":"BIDIRECTIONAL","confidence":"HIGH","estimated_percentage_range":{"low":0.1,"high":6,"applies_to":"Melanesian/Papuan/Aboriginal Australian populations highest (~3-6%); mainland East Asian populations much lower (~0.1-0.2%); see claim_denisovan_ancestry_by_population"},"claim_id":"claim_denisovan_ancestry_by_population"}],"notes":"No single point in time can currently be identified for the species’ origin (Bergström et al. 2021); earliest fossil evidence spans multiple African sites (Jebel Irhoud, Morocco; Omo Kibish, Ethiopia), not one “cradle.”","_entity_type":"Population","_source_path":"docs/timeline/data/entities/populations/pop_homo_sapiens.json"},{"id":"pop_neanderthal","name":"Homo neanderthalensis (Neanderthal)","taxonomic_status":{"classification":"Homo neanderthalensis","disputed":false,"alternative_classifications":["Sometimes classified as Homo sapiens neanderthalensis (subspecies) rather than a separate species"]},"date_range":{"earliest":-430000,"latest":-39260,"precision":"ORDER_OF_MAGNITUDE","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Europe","Western Asia"],"gene_flow_edges":[{"with_population_id":"pop_homo_sapiens","direction":"BIDIRECTIONAL","confidence":"HIGH","estimated_percentage_range":{"low":1.5,"high":2.6,"applies_to":"non-African modern populations; small back-migration-derived signal (~0.3%) also documented in West African populations"},"claim_id":"claim_neanderthal_ancestry_by_population"},{"with_population_id":"pop_denisovan","direction":"BIDIRECTIONAL","confidence":"HIGH","estimated_percentage_range":null,"claim_id":"claim_neanderthal_denisovan_divergence"}],"notes":"Fossil date range (earliest confirmed ~430 ka at Sima de los Huesos; youngest ~39,260-41,030 cal BP) is distinct from the lineage-divergence date from Homo sapiens (~550,000-765,000 years ago, a genetic estimate) — see claim_neanderthal_sapiens_divergence. Do not conflate the two.","_entity_type":"Population","_source_path":"docs/timeline/data/entities/populations/pop_neanderthal.json"},{"id":"pty_aksum_kingdom","name":"Kingdom of Aksum","region":["Horn of Africa/Aksum"],"date_range":{"earliest":50,"latest":940,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"patronage_edges":[],"notes":"Numismatic chronology anchors the early kings (coinage from King Endubis, c. 270-300 CE); Ezana's reign conventionally early-to-mid 320s-c.360 CE. Munro-Hay, Aksum: An African Civilization of Late Antiquity (Edinburgh UP, 1991); Phillipson, Foundations of an African Civilisation (James Currey, 2012).","_entity_type":"Polity","_source_path":"docs/timeline/data/entities/polities/pty_aksum_kingdom.json"},{"id":"pty_asante_empire","name":"Asante Empire","region":["West Africa"],"date_range":{"earliest":1701,"latest":1901,"precision":"YEAR","date_semantics":"EVENT_DATE"},"patronage_edges":[],"notes":"Founded per Asante oral tradition under Osei Tutu I and priest Okomfo Anokye, conventionally c. 1701 (Battle of Feyiase against Denkyira); formally annexed as a British Crown colony/protectorate 1 January 1902. Ivor Wilks, Asante in the Nineteenth Century (Cambridge UP, 1975); T.C. McCaskie, State and Society in Pre-Colonial Asante (Cambridge UP, 1995).","_entity_type":"Polity","_source_path":"docs/timeline/data/entities/polities/pty_asante_empire.json"},{"id":"pty_dahomey_kingdom","name":"Kingdom of Dahomey","region":["West Africa"],"date_range":{"earliest":1645,"latest":1894,"precision":"YEAR","date_semantics":"EVENT_DATE"},"patronage_edges":[],"notes":"Houegbadja/Wegbaja (r. c.1645-1685) most consistently credited as effective first king (built Abomey palaces, formalized Annual Customs, centralized religious authority). Do-Aklin (c.1600-1620) and Dakodonou (c.1620-1645) precede him in the dynastic king-list, but Robin Law's source-critical historiography argues Dakodonou may have been retroactively inserted in the 18th century to legitimize the dynasty's claim over the Abomey plateau's original inhabitants — flag the earliest portion of the king-list as contested, not settled. Absorbed into French West Africa after the Second Franco-Dahomean War (1892-94), King Béhanzin captured 1893.","_entity_type":"Polity","_source_path":"docs/timeline/data/entities/polities/pty_dahomey_kingdom.json"},{"id":"pty_great_zimbabwe_state","name":"Great Zimbabwe (state)","region":["Southern Africa"],"date_range":{"earliest":1200,"latest":1550,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"patronage_edges":[],"notes":"Chirikure, Pollard, Manyanga, Bandama, \"A Bayesian Chronology for Great Zimbabwe: Re-threading the Sequence of a Vandalised Monument,\" Antiquity 87 (2013): 1-19 — modern methodological benchmark; stone construction begins c. 1200 CE (later than older \"11th century\" popular framing), architectural peak 14th-15th c., occupation continuing into 16th-17th c. Much original stratigraphy destroyed by Richard Nicklin Hall's 1902-4 excavation (funded by Cecil Rhodes/BSAC with an explicit brief to establish non-African origin) — flagged as a documented act of evidentiary destruction entangled with racist settler-colonial historiography, not a neutral methodological gap.","_entity_type":"Polity","_source_path":"docs/timeline/data/entities/polities/pty_great_zimbabwe_state.json"},{"id":"pty_kongo_kingdom","name":"Kingdom of Kongo","region":["Central Africa"],"date_range":{"earliest":1390,"latest":1914,"precision":"CENTURY","date_semantics":"TRADITION_INTERNAL_CLAIM"},"patronage_edges":[],"notes":"Traditional founding account: Lukeni lua Nimi, c. 1390 (alternative account names Nimi a Nzima of Mpemba Kasi and Nsaku Lau of Mbata) — a genealogical/oral-traditional date, not archaeologically fixed. First Portuguese contact 1483 (Diogo Cão). John K. Thornton's body of work is the standard modern academic history.","_entity_type":"Polity","_source_path":"docs/timeline/data/entities/polities/pty_kongo_kingdom.json"},{"id":"pty_oyo_empire","name":"Oyo Empire","region":["West Africa"],"date_range":{"earliest":1600,"latest":1836,"precision":"CENTURY","date_semantics":"EARLIEST_WRITTEN_ATTESTATION"},"patronage_edges":[],"notes":"Robin Law, The Oyo Empire, c.1600-c.1836 (Oxford, Clarendon Press, 1977) — standard academic history, reconstructed from scarce written sources plus oral tradition. Probably West Africa's most powerful state through the late 17th-18th centuries; collapse/relocation to \"New Oyo\" at Ago-Oja associated with Aláàfin Atiba, 1820s-30s.","_entity_type":"Polity","_source_path":"docs/timeline/data/entities/polities/pty_oyo_empire.json"},{"id":"text_behistun_inscription","name":"Behistun Inscription","writing_system_id":"ws_cuneiform","decipherment_status":"DECIPHERED","witness_chain":{"composition_date":{"earliest":-521,"latest":-486,"precision":"DECADE","date_semantics":"EVENT_DATE"},"earliest_witness_date":{"earliest":-521,"latest":-486,"precision":"DECADE","date_semantics":"SURVIVING_MANUSCRIPT_DATE"}},"region":["Western Asia"],"notes":"Trilingual (Old Persian, Elamite, Babylonian) cliff inscription of Darius I. Copied by Henry Rawlinson 1835-1847 at great physical risk; publication of the Old Persian decipherment 1846-1847 was the key that unlocked Babylonian/Akkadian cuneiform, publicly confirmed via the 1857 Royal Asiatic Society blind-translation test (Rawlinson, Hincks, Oppert, and Fox Talbot working independently on a newly discovered text).","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_behistun_inscription.json"},{"id":"text_cascajal_block","name":"Cascajal Block","writing_system_id":"ws_epi_olmec","decipherment_status":"UNDECIPHERED","witness_chain":{"composition_date":{"earliest":-900,"latest":-900,"precision":"CENTURY","date_semantics":"ESTIMATED_COMPOSITION"},"earliest_witness_date":null},"region":["North America"],"notes":"Discovered in the late 1990s near Lomas de Tacamichapan, Veracruz, in a debris pile — not found in situ/stratified excavation. The ~900 BCE date rests on associated pottery/figurine dating, not direct stratigraphy of the block itself. Authenticity is disputed (David Grove, Christopher Pool have voiced skepticism; Englehardt et al. 2020 material-science analysis supports genuine Formative-period manufacture without resolving the stratigraphic-context problem). Never read; UNDECIPHERED regardless of the authenticity question. See claim_cascajal_authenticity_disputed.","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_cascajal_block.json"},{"id":"text_hunminjeongeum_haerye","name":"Hunminjeongeum Haerye","writing_system_id":"ws_hangul","decipherment_status":"DECIPHERED","witness_chain":{"composition_date":{"earliest":1446,"latest":1446,"precision":"YEAR","date_semantics":"EVENT_DATE"},"earliest_witness_date":{"earliest":1446,"latest":1446,"precision":"YEAR","date_semantics":"SURVIVING_MANUSCRIPT_DATE"}},"region":["East Asia"],"notes":"The companion commentary explaining Hangul's featural design rationale, promulgated 1446, rediscovered 1940 in Andong. An unusually direct surviving primary document of a script's own design intent — most scripts have no comparable contemporary explanation.","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_hunminjeongeum_haerye.json"},{"id":"text_indus_seal_corpus","name":"Indus Valley Seal and Tablet Corpus","writing_system_id":"ws_indus","decipherment_status":"UNDECIPHERED","witness_chain":{"composition_date":{"earliest":-2600,"latest":-1900,"precision":"CENTURY","date_semantics":"ESTIMATED_COMPOSITION"},"earliest_witness_date":{"earliest":-2600,"latest":-1900,"precision":"CENTURY","date_semantics":"SURVIVING_MANUSCRIPT_DATE"}},"region":["South Asia"],"notes":"~400 distinct signs across roughly 4,000+ inscribed objects (seals, tablets, pottery marks); inscriptions overwhelmingly short (avg. ~5 signs, longest ~26). No bilingual anchor, no confirmed underlying language. UNDECIPHERED holds regardless of which side of the \"is it writing\" dispute (Farmer/Sproat/Witzel 2004 vs. Parpola 1994 / Rao et al. 2009) is correct.","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_indus_seal_corpus.json"},{"id":"text_khipu_epistolary_cords","name":"Epistolary/Narrative Khipu Corpus","writing_system_id":"ws_khipu","decipherment_status":"DISPUTED","witness_chain":{"composition_date":{"earliest":1400,"latest":1600,"precision":"CENTURY","date_semantics":"ESTIMATED_COMPOSITION"},"earliest_witness_date":{"earliest":1400,"latest":1600,"precision":"CENTURY","date_semantics":"SURVIVING_MANUSCRIPT_DATE"}},"region":["South America"],"notes":"Gary Urton (Signs of the Inka Khipu, University of Texas Press, 2003) argues khipu construction encodes binary-coded information beyond pure accounting. Newer analyzed cords with up to 95 distinct symbols (within logosyllabic range) and Zipf/Shannon-entropy statistical signatures consistent with natural-language structure have been reported, but no confirmed reading of narrative content exists. Mainstream caution holds most khipu are confidently readable only as numerical/accounting records — genuinely DISPUTED, not resolved either direction.","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_khipu_epistolary_cords.json"},{"id":"text_la_mojarra_stela_1","name":"La Mojarra Stela 1","writing_system_id":"ws_epi_olmec","decipherment_status":"DISPUTED","witness_chain":{"composition_date":{"earliest":157,"latest":162,"precision":"YEAR","date_semantics":"ESTIMATED_COMPOSITION"},"earliest_witness_date":{"earliest":1986,"latest":1986,"precision":"YEAR","date_semantics":"SURVIVING_MANUSCRIPT_DATE"}},"region":["North America"],"notes":"Discovered 1986, Veracruz; bears a Long Count date. Justeson and Kaufman (Science 259, 1993) claimed a decipherment identifying the underlying language as pre-proto-Zoquean; Houston and Coe (Mexicon 25, 2003) argue the claimed decipherment imposes Mayan grammatical/spelling assumptions and failed an independent test against a separate Isthmian-script mask. This is a live, named two-camp dispute; see claim_epi_olmec_decipherment_disputed.","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_la_mojarra_stela_1.json"},{"id":"text_linear_a_tablets","name":"Linear A Tablet Corpus","writing_system_id":"ws_linear_a","decipherment_status":"UNDECIPHERED","witness_chain":{"composition_date":{"earliest":-1800,"latest":-1450,"precision":"CENTURY","date_semantics":"ESTIMATED_COMPOSITION"},"earliest_witness_date":{"earliest":-1800,"latest":-1450,"precision":"CENTURY","date_semantics":"SURVIVING_MANUSCRIPT_DATE"}},"region":["Europe"],"notes":"Roughly 1,400-1,500 inscribed objects, ~7,300-7,400 signs total (Linear A Digital Corpus, J.G. Younger). Underlying Minoan language unclassified; Anatolian/Luwian, Semitic, and other hypotheses lack consensus. A 2026 unpublished, non-peer-reviewed \"AI-assisted Semitic decipherment\" claim (Tom Di Mino) is circulating and is explicitly treated with skepticism by specialists at Rutgers/Cambridge reviewing it — flagged as NOT changing decipherment_status from UNDECIPHERED.","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_linear_a_tablets.json"},{"id":"text_linear_b_tablets","name":"Linear B Tablet Corpus","writing_system_id":"ws_linear_b","decipherment_status":"DECIPHERED","witness_chain":{"composition_date":{"earliest":-1450,"latest":-1200,"precision":"CENTURY","date_semantics":"ESTIMATED_COMPOSITION"},"earliest_witness_date":{"earliest":-1450,"latest":-1200,"precision":"CENTURY","date_semantics":"SURVIVING_MANUSCRIPT_DATE"}},"region":["Europe"],"notes":"Michael Ventris announced in 1952 that Linear B encoded an archaic form of Greek; John Chadwick independently confirmed it; jointly published in the Journal of Hellenic Studies (1953) and Documents in Mycenaean Greek (Cambridge UP, 1956). A clean, consensus decipherment used here as the field's calibration case.","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_linear_b_tablets.json"},{"id":"text_oracle_bone_inscriptions","name":"Oracle Bone Inscriptions (Anyang)","writing_system_id":"ws_chinese_script","decipherment_status":"PARTIAL","witness_chain":{"composition_date":{"earliest":-1250,"latest":-1046,"precision":"CENTURY","date_semantics":"ESTIMATED_COMPOSITION"},"earliest_witness_date":{"earliest":-1250,"latest":-1046,"precision":"CENTURY","date_semantics":"SURVIVING_MANUSCRIPT_DATE"}},"region":["East Asia"],"notes":"Late Shang divination records, predominantly from Yinxu near Anyang. Roughly 4,500 distinct graphs identified; per a 2016 National Museum of Chinese Writing decipherment-reward program (China Daily, 28 Oct 2016), the meanings of over 3,000 remain unresolved — report as a range (roughly 30-40% reliably deciphered, not a single point figure, since sources diverge). Only three scholars had successfully claimed the reward as of 2016.","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_oracle_bone_inscriptions.json"},{"id":"text_rongorongo_tablets","name":"Rongorongo Tablets","writing_system_id":"ws_rongorongo","decipherment_status":"UNDECIPHERED","witness_chain":{"composition_date":{"earliest":1493,"latest":1900,"precision":"CENTURY","date_semantics":"ESTIMATED_COMPOSITION"},"earliest_witness_date":{"earliest":1493,"latest":1509,"precision":"YEAR","date_semantics":"SURVIVING_MANUSCRIPT_DATE"}},"region":["Oceania"],"notes":"Fischer's (1997, Oxford UP) claimed reading of the Santiago Staff as a repeating cosmogonic chant formula is specifically and substantively rebutted by Guy (1998) and Pozdniakov (1996, Journal de la Société des Océanistes), who show the statistical patterns Fischer relied on arise from the script's own repetitive triadic structure rather than his proposed content — not accepted by the field.","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_rongorongo_tablets.json"},{"id":"text_rosetta_stone","name":"Rosetta Stone","writing_system_id":"ws_egyptian_hieroglyphs","decipherment_status":"DECIPHERED","witness_chain":{"composition_date":{"earliest":-196,"latest":-196,"precision":"YEAR","date_semantics":"EVENT_DATE"},"earliest_witness_date":{"earliest":-196,"latest":-196,"precision":"YEAR","date_semantics":"SURVIVING_MANUSCRIPT_DATE"}},"region":["Africa"],"notes":"Trilingual decree (hieroglyphic, Demotic, Greek), discovered 1799 by French soldiers during Napoleon's Egyptian campaign at Rashid/Rosetta. The decree itself is a single, precisely dated 196 BCE inscription, so composition and earliest-witness dates coincide.","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_rosetta_stone.json"},{"id":"text_san_bartolo_murals","name":"San Bartolo Murals (Las Pinturas)","writing_system_id":"ws_maya_script","decipherment_status":"DECIPHERED","witness_chain":{"composition_date":{"earliest":-300,"latest":-200,"precision":"CENTURY","date_semantics":"ESTIMATED_COMPOSITION"},"earliest_witness_date":{"earliest":-300,"latest":-200,"precision":"CENTURY","date_semantics":"SURVIVING_MANUSCRIPT_DATE"}},"region":["North America"],"notes":"Saturno, Stuart and Beltrán, \"Early Maya Writing at San Bartolo, Guatemala,\" Science 311 (2006): earliest secure Maya hieroglyphic text, radiocarbon-dated via associated carbonized wood to c. 300-200 BCE. Already shows a mature, fully developed script with no obvious transitional forms linking back to Olmec symbols.","_entity_type":"Text","_source_path":"docs/timeline/data/entities/texts/text_san_bartolo_murals.json"},{"id":"trad_akan_traditional_religion","name":"Akan traditional religion (Nyame/abosom/asamanfo)","category_tags":["mixed","ancestor_veneration"],"region":["West Africa"],"dating":{"dating_summary":"The tripartite Nyame/abosom/asamanfo structure as commonly taught is substantially a 20th-century scholarly codification (Danquah 1944, Rattray 1923/1927, Opoku 1978) layered onto older, undated oral-ritual practice; earliest identified written attestation is Willem Bosman's 1704/1705 Dutch trading account; no archaeological or oral-origin date can be assigned with precision.","earliest_archaeological_evidence":{"range":null,"note":"UNKNOWN specifically for this cosmological system; Akan shrine-site archaeology exists but no dated find-specific attestation of Nyame/abosom worship was verified in this research pass."},"earliest_written_attestation":{"range":{"earliest":1704,"latest":1705,"precision":"YEAR"},"note":"Willem Bosman, A New and Accurate Description of the Coast of Guinea (Dutch 1704, English 1705) — an outside/colonial-trade observer's account, later quoted by Rattray."},"surviving_manuscript_date":{"range":{"earliest":1819,"latest":1927,"precision":"CENTURY"},"note":"Thomas Bowdich (1819), Joseph Dupuis (1824), then R.S. Rattray's early-20th-century fieldwork (Ashanti 1923; Religion and Art in Ashanti 1927), then Danquah (1944)."},"estimated_composition":{"range":null,"method":"The scholarly codification into the Nyame/abosom/asamanfo tripartite structure is substantially a 20th-century interpretive product (Danquah explicitly used Christian/Greek monotheistic categories as his comparative frame, per Fighting Words, Peter Lang 2017) layered onto older practice — this is a reasonable reading of the historiography, not a scholar's own verbatim claim.","disputed":true},"tradition_internal_claim":{"range":null,"note":"Presented as coextensive with Akan peoplehood itself; no origin point is claimed."},"estimated_oral_origin":{"range":null,"method":"Linguistic (shared vocabulary for Nyame-type high gods across Kwa-language-family Akan-related groups) would suggest deep pre-colonial antiquity, but no scholar in this research offered a specific glottochronological or archaeological date.","confidence":"UNKNOWN"}},"relationships":[],"notes":"J.B. Danquah, The Akan Doctrine of God (1944; 2nd ed. 1968) — Danquah himself an anticolonial political-intellectual figure (co-founder UGCC, died in Nkrumah-era detention 1965), not a neutral ethnographer; his monotheism-framing of Nyame/Onyankopon/Odomankoma/Borebore is now itself subject to critique. R.S. Rattray, Religion and Art in Ashanti (Oxford, 1927). Anthony Ephirim-Donkor, African Religion Defined: A Systematic Study of Ancestor Worship Among the Akan.","_entity_type":"Tradition","_source_path":"docs/timeline/data/entities/traditions/trad_akan_traditional_religion.json"},{"id":"trad_aksumite_christianity","name":"Aksumite Christianity (Ezana-era state adoption)","category_tags":["monotheism"],"region":["Horn of Africa/Aksum"],"dating":{"dating_summary":"A hard external terminus ante quem of 356 CE (Constantius II's letter, preserved in Athanasius) confirms Ezana was reigning and Christian by that date; the precise conversion year within the preceding ~15-20-year window (mid-330s-340s CE) remains disputed, not fixed.","earliest_archaeological_evidence":{"range":null,"note":"Ezana's coinage transitions from disc-and-crescent to an explicit cross — one of the earliest states anywhere to place a Christian symbol on its own coinage. Whether the numismatic transition was abrupt or gradual (transitional hybrid issues) is itself disputed across the sources found in this research pass and was not resolved to academic-source confidence."},"earliest_written_attestation":{"range":{"earliest":356,"latest":357,"precision":"YEAR"},"note":"Emperor Constantius II's letter to \"Aizanas and Sazanas\" (Ezana and co-ruler Saizana), preserved in Athanasius, Apologia ad Constantium (c. 356/357 CE), demanding Frumentius be sent to Alexandria for re-examination — independently confirms Ezana reigning and Christian by this date."},"surviving_manuscript_date":{"range":{"earliest":402,"latest":403,"precision":"YEAR"},"note":"Rufinus of Aquileia, continuation of Eusebius's Ecclesiastical History (Books 10-11), written c. 402-403 CE, states he heard the Frumentius account directly from Aedesius, Frumentius's companion, whom he met at Tyre — one source-remove from an eyewitness, within roughly 60-70 years of the events."},"estimated_composition":{"range":null,"method":null,"disputed":true},"tradition_internal_claim":{"range":null,"note":"Later Ethiopian tradition's honorific \"Abba Selama\" (\"Father of Peace\") for Frumentius, and elaborated hagiographic material (including elements folded into the 14th-century-redacted Kebra Nagast) are centuries-later elaboration on the Rufinus core, not independent corroboration."},"estimated_oral_origin":{"range":null,"method":null,"confidence":"UNKNOWN"}},"relationships":[{"edge_type":"MISSIONIZATION","target_id":"trad_aksumite_paganism","confidence":"HIGH","claim_id":"claim_aksum_missionization"},{"edge_type":"STATE_ADOPTION","target_id":"trad_aksumite_paganism","confidence":"MODERATE","claim_id":"claim_aksum_state_adoption"}],"notes":"This entity covers only the 4th-century conversion moment, not the later development of the distinctive Ethiopian Orthodox Tewahedo Church (a separate, much larger topic outside this batch's scope). No strong academic source was found directly tracing continuity from the pagan Mahrem/Astar/Beher-Meder complex into later Ethiopian Christian liturgy/theology — do not assert such continuity. The church's distinctive Old-Testament-inflected practices (dual Sabbath, dietary law, circumcision, Ark theology) are generally attributed by scholarship (Bowersock, The Throne of Adulis, Oxford UP 2013) to separate Judaic/South Arabian cultural contact, not to pagan-Aksumite continuity.","_entity_type":"Tradition","_source_path":"docs/timeline/data/entities/traditions/trad_aksumite_christianity.json"},{"id":"trad_aksumite_paganism","name":"Aksumite state paganism (Mahrem/Astar/Beher-Meder)","category_tags":["polytheism"],"region":["Horn of Africa/Aksum"],"dating":{"dating_summary":"Attested almost entirely from epigraphy and coinage at the very end of the tradition's history (Ezana's own pre-conversion inscriptions, likely 330s CE, and the Monumentum Adulitanum, original date uncertain 2nd-3rd c. CE, surviving only via a 6th-century copy) — no scriptural corpus, no earlier evidence of comparable specificity survives.","earliest_archaeological_evidence":{"range":{"earliest":270,"latest":300,"precision":"DECADE"},"note":"Aksumite coinage bearing disc-and-crescent symbolism from King Endubis, c. 270-300 CE, is the primary chronological anchor for early Aksumite religious material culture."},"earliest_written_attestation":{"range":{"earliest":330,"latest":339,"precision":"DECADE"},"note":"Ezana's own pre-Christian Ge'ez inscriptions (catalogued RIÉ 185 I/II = DAE 6-7), likely 330s CE, name the triad Mahrem/Astar/Beher(or Meder) directly."},"surviving_manuscript_date":{"range":null,"note":"The Monumentum Adulitanum (equating Mahrem/Beher/Meder with Ares/Poseidon/Zeus) survives only via a copy made by the monk Cosmas Indicopleustes at Adulis c. 518-525 CE, published in his Christian Topography (c. 547-549 CE); the original stone is lost and its own composition date is only estimated (2nd-3rd century CE, attributed to an unnamed pre-Ezana king)."},"estimated_composition":{"range":null,"method":null,"disputed":false},"tradition_internal_claim":{"range":null,"note":"N/A — no continuous adherent community survives to assert an origin claim."},"estimated_oral_origin":{"range":null,"method":"Comparative Semitic-religion scholarship situates the astral/war-god cult type within a South Arabian religious koine attested in Saba' from the early-to-mid 1st millennium BCE; the earlier, distinct Kingdom of D'mt (~8th-5th c. BCE, same region) shows related Almaqah worship, but bridging D'mt to Aksum religiously is inference, not documented continuity.","confidence":"LOW"}},"relationships":[],"notes":"Mahrem (war god; Aksumite kings styled themselves \"son of the invincible Mahrem\"); Astar (astral character disputed — Venus-analog vs. sun/moon deity, sources disagree); Beher/Meder (sea/sky, earth). Comparison of Mahrem to South Arabian Almaqah is repeatedly made in secondary literature but the degree of identity is explicitly uncertain — do not assert equivalence.","_entity_type":"Tradition","_source_path":"docs/timeline/data/entities/traditions/trad_aksumite_paganism.json"},{"id":"trad_antonianism","name":"Antonian movement (Kimpa Vita)","category_tags":["monotheism","ancestor_veneration","mixed"],"region":["Central Africa"],"dating":{"dating_summary":"A dated, bounded reform movement: began 1704 with Kimpa Vita's claimed possession by Saint Anthony of Padua; ended with her execution by burning in 1706.","earliest_archaeological_evidence":{"range":null,"note":null},"earliest_written_attestation":{"range":{"earliest":1704,"latest":1706,"precision":"YEAR"},"note":"No surviving African-authored primary source exists; the entire documentary record consists of accounts by Italian Capuchin missionaries (chiefly Bernardo da Gallo and Lorenzo da Lucca), hostile witnesses given she was tried and executed as a heretic largely on their testimony."},"surviving_manuscript_date":{"range":{"earliest":1704,"latest":1706,"precision":"YEAR"},"note":"Same Capuchin missionary accounts."},"estimated_composition":{"range":null,"method":null,"disputed":false},"tradition_internal_claim":{"range":null,"note":"Kimpa Vita claimed to have died and been reincarnated/possessed by Saint Anthony of Padua in 1704, and preached that Jesus, Mary, and the saints were themselves Kongolese/African."},"estimated_oral_origin":{"range":null,"method":null,"confidence":"UNKNOWN"}},"relationships":[{"edge_type":"REFORM","target_id":"trad_kongo_christianity","confidence":"HIGH","claim_id":"claim_antonianism_reform"}],"notes":"John K. Thornton, The Kongolese Saint Anthony: Dona Beatriz Kimpa Vita and the Antonian Movement, 1684-1706 (Cambridge UP, 1998) — the foundational modern academic monograph, reading the hostile Capuchin sources \"against the grain.\" Movement arose amid civil wars over the Kongo throne following the 1665 Battle of Mbwila; Thornton frames it as having taken on the character of \"something of a theocracy,\" aimed at ending the wars and restoring unified sacralized kingship. Executed on orders connected to King Pedro IV, with Capuchin missionary involvement in her heresy condemnation. See claim_kimpa_vita_does_not_demonstrate.","_entity_type":"Tradition","_source_path":"docs/timeline/data/entities/traditions/trad_antonianism.json"},{"id":"trad_fon_vodun","name":"Fon Vodun","category_tags":["henotheism","ancestor_veneration","polytheism"],"region":["West Africa"],"dating":{"dating_summary":"Aja-Fon migration from Tado is dated by comparative Gbe-language linguistics and oral-tradition triangulation to roughly the 12th-13th century CE; Vodun-type practice is inferred to predate the Dahomey kingdom itself (founded c. 1645) but no scholar-verified specific date was found beyond \"predates the 17th-century kingdom\" — the state-sponsored Mawu-Lisa cult specifically is a datable 1740s political act, not deep antiquity.","earliest_archaeological_evidence":{"range":null,"note":"No durable ritual architecture/inscriptions predate the 17th century; material culture is largely perishable — effectively absent as independent physical dating evidence."},"earliest_written_attestation":{"range":{"earliest":1600,"latest":1699,"precision":"CENTURY"},"note":"European documentation from 17th-century contact; sustained Dutch/French/British/Danish documentation from the 17th-18th centuries. A specific 1658 Doctrina Christiana citation for early Vodun awareness could not be independently verified in this research pass — flagged, not asserted."},"surviving_manuscript_date":{"range":{"earliest":1938,"latest":1938,"precision":"YEAR"},"note":"Melville J. Herskovits, Dahomey: An Ancient West African Kingdom (J.J. Augustin, 1938), based on 1931 fieldwork — the foundational modern ethnography."},"estimated_composition":{"range":null,"method":null,"disputed":false},"tradition_internal_claim":{"range":null,"note":"Migration narrative from Tado (Mono River) via Allada to Abomey, tied to the Agassou (leopard-ancestor) foundational myth."},"estimated_oral_origin":{"range":{"earliest":1100,"latest":1300,"precision":"CENTURY"},"method":"Comparative Gbe-language historical linguistics plus oral-tradition triangulation.","confidence":"MODERATE"}},"relationships":[{"edge_type":"STATE_ADOPTION","target_id":"pty_dahomey_kingdom","confidence":"HIGH","claim_id":"claim_mawu_lisa_hwanjile_import"}],"notes":"Nana Buluku (primordial figure who withdrew after birthing the twin deities Mawu/moon-night-female and Lisa/sun-day-male, who fuse into composite Mawu-Lisa) — a deus-otiosus pattern better fitting henotheism than monotheism, since worship in practice centers on the accessible vodun (Sakpata/earth, Sogbo-Xevioso/thunder, Agbe/sea, etc.). No named academic source was found directly adjudicating the monotheism-vs-henotheism classification dispute — flagged as this project's own tag judgment, not a cited scholarly consensus.","_entity_type":"Tradition","_source_path":"docs/timeline/data/entities/traditions/trad_fon_vodun.json"},{"id":"trad_ifa_orisa","name":"Ifá / Òrìṣà tradition (Yoruba)","category_tags":["polytheism","ancestor_veneration","mixed"],"region":["West Africa"],"dating":{"dating_summary":"Ifè was a functioning urban/religious center by 1200-1400 CE and the tradition's own oral corpus (Odù Ifá) locates origin there, but no archaeological find has been named-scholar-confirmed as Ifá divination practice specifically; the earliest substantive written attestation is mid-19th-century missionary/ethnographic (Crowther 1843; Ellis 1894; Johnson 1897/1921); the corpus itself is fundamentally oral, first systematically transcribed by Bascom (1950-51 fieldwork) and Abimbola (from the 1960s-70s) — treat pre-19th-century dating as genuinely open, not a settled figure.","earliest_archaeological_evidence":{"range":null,"note":"Ilé-Ifè classical period (naturalistic bronze/terracotta art) dated c. 1200-1400 CE (Met Museum); no named excavation report ties a specific dated artifact to Ifá divination practice specifically."},"earliest_written_attestation":{"range":{"earliest":1843,"latest":1843,"precision":"YEAR"},"note":"Samuel Ajayi Crowther, A Vocabulary of the Yoruba Language (London, 1843; expanded ed. with Owen Vidal, 1852) is the earliest identified substantive written source; no confirmed pre-19th-century European account of Ifá/Òrìṣà worship specifically was located."},"surviving_manuscript_date":{"range":null,"note":"No manuscript tradition; oral corpus first systematically transcribed by William Bascom (fieldwork 1950-51) and Wande Abimbola (Ifá Divination Poetry, NOK, 1977)."},"estimated_composition":{"range":null,"method":null,"disputed":true},"tradition_internal_claim":{"range":null,"note":"Odù Ifá locates origin at Ilé-Ifè, associated with Ọ̀rúnmìlà; some strands treat him as a primordial divinity, others as a historicized founding figure — internally contested within the tradition itself."},"estimated_oral_origin":{"range":null,"method":null,"confidence":"UNKNOWN"}},"relationships":[{"edge_type":"SYNCRETISM","target_id":"pty_oyo_empire","confidence":"MODERATE","claim_id":"claim_ifa_oyo_patronage"}],"notes":"Named scholars: Wande Abimbola (Ifá Divination Poetry, NOK 1977) and William Bascom (Ifa Divination: Communication Between Gods and Men in West Africa, Indiana UP, 1969/1991) — the two standard 20th-century academic authorities, both working from live oral recitation.","_entity_type":"Tradition","_source_path":"docs/timeline/data/entities/traditions/trad_ifa_orisa.json"},{"id":"trad_juhoansi_trance_healing","name":"Ju/'hoansi trance-healing tradition","category_tags":["animism","mixed"],"region":["Southern Africa"],"dating":{"dating_summary":"Documented via 20th-century ethnography (Marshall from the 1950s; Katz's fieldwork early-to-mid 1970s, published 1982; Biesele from the 1970s-90s) as a living practice; no independently dated time-depth for the specific institution as documented, though the general trickster-Mantis figure appears across many San groups' folklore per comparative work (Guenther 1999).","earliest_archaeological_evidence":{"range":null,"note":"Rock art potentially depicting trance-dance postures exists but the link is a contested interpretive claim (Lewis-Williams/Dowson vs. Solomon), not confirmed continuity — see claim_rock_art_shamanism_disputed."},"earliest_written_attestation":{"range":{"earliest":1950,"latest":1959,"precision":"DECADE"},"note":"Lorna Marshall's Nyae Nyae fieldwork, published from 1959 onward, is the earliest substantial published ethnography of this specific group."},"surviving_manuscript_date":null,"estimated_composition":{"range":null,"method":null,"disputed":false},"tradition_internal_claim":{"range":null,"note":"No single canonical origin narrative; described by practitioners as a longstanding living institution of \"emotional, social, and moral balance\" (Lee/Biesele framing)."},"estimated_oral_origin":{"range":null,"method":null,"confidence":"UNKNOWN"}},"relationships":[],"notes":"Richard Katz, Boiling Energy: Community Healing Among the Kalahari Kung (Harvard UP, 1982) — n/um (\"energy\") \"boiling\" during the all-night communal healing dance produces !kia/trance, enabling extraction of sickness; at dances Katz observed, roughly 1/4 of female singers and 2/3 of male dancers functioned as healers — both sexes participate, men a larger share of deep-trance healers. Megan Biesele, Women Like Meat (Witwatersrand UP/Indiana UP, 1993).","_entity_type":"Tradition","_source_path":"docs/timeline/data/entities/traditions/trad_juhoansi_trance_healing.json"},{"id":"trad_kongo_christianity","name":"Kongo Christianity (Afonso-era Catholic state cult)","category_tags":["monotheism","ancestor_veneration","mixed"],"region":["Central Africa"],"dating":{"dating_summary":"Baptism of Nzinga a Nkuwu (as João I) 3 May 1491 was a MISSIONIZATION event that did not durably hold (he apostatized c. 1494-95); durable STATE_ADOPTION dates to Afonso I's reign from 1509, combined with documented terminological/visual SYNCRETISM continuing through the 17th century Kimpasi society and the Cardoso 1624 catechism.","earliest_archaeological_evidence":{"range":null,"note":"Elaborate hybrid crucifixes and other Kongo Christian visual-art objects survive from the 16th-18th centuries (Cécile Fromont, The Art of Conversion, UNC Press 2014) but this research pass did not verify a specific earliest-dated excavated example."},"earliest_written_attestation":{"range":{"earliest":1491,"latest":1491,"precision":"YEAR"},"note":"Baptism of Nzinga a Nkuwu as João I, 3 May 1491, with son Nzinga a Mbemba (later Afonso I) and court officials baptized alongside him."},"surviving_manuscript_date":{"range":{"earliest":1624,"latest":1624,"precision":"YEAR"},"note":"The 1624 Kikongo catechism produced under Jesuit Mateus Cardoso, translated by named Kongo \"best masters of the church,\" is the earliest surviving full catechism (a now-lost 1557 Carmelite catechism preceded it but its exact wording is not independently verifiable). Also: John K. Thornton, Afonso I Mvemba a Nzinga, King of Kongo: His Life and Correspondence (Hackett, 2020) — Afonso I's own surviving letters, most famously a series from 1526 protesting the Atlantic slave trade to King João III of Portugal."},"estimated_composition":{"range":null,"method":null,"disputed":false},"tradition_internal_claim":{"range":null,"note":"N/A — an imported tradition with a documented, non-legendary founding sequence (unlike most traditions in this batch)."},"estimated_oral_origin":{"range":null,"method":null,"confidence":"UNKNOWN"}},"relationships":[{"edge_type":"MISSIONIZATION","target_id":"trad_kongo_traditional_religion","confidence":"HIGH","claim_id":"claim_kongo_1491_missionization"},{"edge_type":"STATE_ADOPTION","target_id":"trad_kongo_traditional_religion","confidence":"HIGH","claim_id":"claim_kongo_afonso_state_adoption"},{"edge_type":"SYNCRETISM","target_id":"trad_kongo_traditional_religion","confidence":"HIGH","claim_id":"claim_kongo_syncretism_translation"}],"notes":"Afonso I (r. 1509-1542) declared traditional \"idol\" worship illegal, burned at least one traditional shrine, built churches/schools, used Christian primogeniture doctrine to strengthen his own succession claim. Cécile Fromont documents the pre-existing Kongo dikenga/yowa cross-shaped cosmogram (four moments of the sun: kala/tukula/luvemba/musoni) as a genuine point of visual-cosmological convergence with the Christian crucifix, not a one-sided imposition.","_entity_type":"Tradition","_source_path":"docs/timeline/data/entities/traditions/trad_kongo_christianity.json"},{"id":"trad_kongo_traditional_religion","name":"Pre-Christian Kongo religion (Nzambi/bisimbi/minkisi)","category_tags":["mixed","ancestor_veneration"],"region":["Central Africa"],"dating":{"dating_summary":"Nearly everything popularly stated about \"precolonial Kongo religion\" is actually late-19th/early-20th-century ethnography (the Laman manuscript collection, c. 1915, written by Protestant converts) or the missionary-syncretic vocabulary retrojected backward; treat pre-1483 Kongo religious content as substantially reconstructed, not directly documented.","earliest_archaeological_evidence":{"range":null,"note":"The Kongo Kingdom's traditional founding (Lukeni lua Nimi, c. 1390) rests on genealogical/oral reconstruction, not archaeology; no specific dated excavated site for pre-contact religious material culture was verified in this research pass."},"earliest_written_attestation":{"range":{"earliest":1483,"latest":1491,"precision":"DECADE"},"note":"Portuguese contact from 1483 (Diogo Cão); these are external/colonial observer accounts, not Kongo-authored texts, and post-date any actual founding of the religious system by an unknown span."},"surviving_manuscript_date":{"range":{"earliest":1915,"latest":1915,"precision":"YEAR"},"note":"Karl Laman's ~10,000-page manuscript collection from Protestant converts, c. 1915 — over 400 years after first European contact, and already shaped by the missionary encounter."},"estimated_composition":{"range":null,"method":null,"disputed":false},"tradition_internal_claim":{"range":null,"note":"No single canonical origin narrative recoverable; oral traditions on kingdom founding vary by clan/dynastic line (Kimpanzu/Kinlaza/Kwilu)."},"estimated_oral_origin":{"range":null,"method":"Jan Vansina's comparative-historical-linguistics/Bantu-expansion dating places the general ancestor-veneration/nkisi-type cultural substrate as considerably older than the Kongo kingdom itself, plausibly first-millennium-CE Bantu-speaking Central Africa — a linguistic-reconstruction inference, not a hard date.","confidence":"LOW"}},"relationships":[],"notes":"DISPUTED: whether Nzambi a Mpungu was originally a benevolent creator/sky-father (older ethnographic synthesis, e.g. Fu-Kiau) or originally a personification of death, with the life/creation valence instead carried by bisimbi (chthonic land/water spirit forces) — per Wyatt MacGaffey, \"Precolonial Beliefs in God, Nzambi, and Chthonic Beings: Evidence from Kongo Texts,\" Journal of Religion in Africa 52(1-2), 2022, using the Laman manuscripts. See claim_nzambi_meaning_disputed. \"Fetish\" (from Portuguese feitiço) is a documented colonial mistranslation of nkisi/minkisi — MacGaffey, \"Fetishism Revisited: Kongo Nkisi in Sociological Perspective,\" Africa journal.","_entity_type":"Tradition","_source_path":"docs/timeline/data/entities/traditions/trad_kongo_traditional_religion.json"},{"id":"trad_shona_religion","name":"Shona religion (Mwari/mhondoro/vadzimu)","category_tags":["monolatry","ancestor_veneration"],"region":["Southern Africa"],"dating":{"dating_summary":"The Mwari cult's documented, source-rich history begins with its 17th-18th century Rozvi (Changamire dynasty) association and Matopos/Njelele shrine geography; its presence at Great Zimbabwe specifically (13th-15th c.) during the site's floruit is an inference/extrapolation backward from later evidence, not independently evidenced from the site's own archaeological record — report as contested, not settled.","earliest_archaeological_evidence":{"range":null,"note":"No archaeological dating specific to the Njelele shrine site (as distinct from general Matopos-region settlement) was located in this research pass."},"earliest_written_attestation":{"range":{"earliest":1570,"latest":1570,"precision":"YEAR"},"note":"Portuguese-era sources document Mwari as the Mutapa state's tutelary/creator deity from the 16th-17th century (referenced via Portuguese missionary accounts, e.g. Dom Gonçalo da Silveira's 1570 mission); an exact earliest-dated primary citation using the specific term \"Mwari\" was not independently verified in this pass."},"surviving_manuscript_date":{"range":{"earliest":1896,"latest":1970,"precision":"CENTURY"},"note":"Terence Ranger, Revolt in Southern Rhodesia 1896-97 (Heinemann, 1967); M.L. Daneel, The God of the Matopo Hills: An Essay on the Mwari Cult in Rhodesia (Mouton, 1970), based on 1965-67 fieldwork — the foundational modern academic study."},"estimated_composition":{"range":null,"method":null,"disputed":true},"tradition_internal_claim":{"range":null,"note":"Some oral accounts place cult origin around a 14th-century \"Mbire\" migration narrative of Karanga clans from the Lake regions — self-reported, not independently corroborated."},"estimated_oral_origin":{"range":null,"method":null,"confidence":"LOW"}},"relationships":[{"edge_type":"PATRONAGE","target_id":"pty_great_zimbabwe_state","confidence":"DISPUTED","claim_id":"claim_mwari_great_zimbabwe_disputed"}],"notes":"DISPUTED relationship to Great Zimbabwe/Rozvi state power: Camp 1 (some earlier/popular accounts + the Mbire migration tradition) treats the cult as continuous with or originating at Great Zimbabwe; Innocent Pikirayi (The Zimbabwe Culture, AltaMira Press, 2001) cautions against reading the cult as a mere instrument of state power even in its later Rozvi-era form; David Beach argued documentary/oral linkage between the archaeological site and the cult during the site's 13th-15th c. floruit is weak; Richard Werbner (Kalanga fieldwork) argues the cult historically never was structurally bound to any specific state/polity at all. mhondoro (territorial ancestral spirits, ranked above vadzimu/ordinary family ancestors) mediate between Mwari and the living; see claim_nehanda_does_not_demonstrate for the 1896-97 First Chimurenga case.","_entity_type":"Tradition","_source_path":"docs/timeline/data/entities/traditions/trad_shona_religion.json"},{"id":"trad_xam_cosmology","name":"/Xam cosmology (Kaggen narratives)","category_tags":["animism","mixed"],"region":["Southern Africa"],"dating":{"dating_summary":"Recorded 1870s-1880s from named /Xam informants (‡‡Kabbo, Dia!kwain, /A!kunta, /Han≠kass'o) by Wilhelm Bleek and Lucy Lloyd; the oral antecedents of this specific recorded content have no independently verified time-depth estimate by any named scholar — resist importing rock-art-age or population-genetic-age figures into a claim about this narrative content's age.","earliest_archaeological_evidence":{"range":null,"note":"No rock art panel has been securely, independently identified as depicting the Kaggen-eland narrative specifically (see trad claim on the shamanistic-interpretation dispute)."},"earliest_written_attestation":{"range":{"earliest":1870,"latest":1884,"precision":"DECADE"},"note":"Bleek and Lloyd notebooks, Cape Town, 1870s-1884; first major published selection Specimens of Bushman Folklore, 1911."},"surviving_manuscript_date":{"range":{"earliest":1870,"latest":1884,"precision":"DECADE"},"note":"Roughly 13,000-15,000 pages of notebooks/transcriptions/drawings, now held across UCT, Iziko South African Museum, and the National Library of South Africa; UNESCO Memory of the World Register, 1997."},"estimated_composition":{"range":null,"method":null,"disputed":true},"tradition_internal_claim":{"range":null,"note":"Narratives are framed as accounts of a mythic \"Early Race\" (ambiguous human-animal beings) — an internal mythological time-frame, not a historical founding-date claim."},"estimated_oral_origin":{"range":null,"method":null,"confidence":"UNKNOWN"}},"relationships":[],"notes":"/Kaggen (Mantis), shapeshifting trickster-creator, morally ambiguous; the eland-creation narrative and the \"Girl of the Early Race who made the stars\" (Milky Way) narrative are both directly attested in the Bleek-Lloyd corpus. Extensive menarcheal-seclusion cosmology (girl equated with potency of new moon and !Khwa the Rain) documented by Roger Hewitt, Structure, Meaning and Ritual in the Narratives of the Southern San (1986). Distinct from Ju/'hoansi tradition below — do not merge.","_entity_type":"Tradition","_source_path":"docs/timeline/data/entities/traditions/trad_xam_cosmology.json"},{"id":"ws_aramaic","name":"Aramaic Script","origin_type":"ADAPTATION","date_range":{"earliest":-800,"latest":-200,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Western Asia"],"script_type":"ABJAD","descends_from":[{"writing_system_id":"ws_phoenician","confidence":"HIGH","claim_id":"claim_aramaic_descends_phoenician"}],"notes":"Broad ancestor script behind Hebrew square script, Nabataean (-> Arabic), Syriac, and (contested — see ws_brahmi) possibly Brahmi. `latest` set to the Achaemenid-era window covered by this research batch; Aramaic-derived scripts persist to the present via descendants.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_aramaic.json"},{"id":"ws_bamum","name":"Bamum Script","origin_type":"STIMULUS_DIFFUSION","date_range":{"earliest":1896,"latest":null,"precision":"YEAR","date_semantics":"EVENT_DATE"},"region":["Africa"],"script_type":"SYLLABIC","descends_from":[],"notes":"Invented by King Njoya of the Bamum Kingdom (Cameroon), starting 1896, evolving through six documented stages over c. 14 years from an initial ~465-pictogram system to a true syllabary by 1902. Suppressed after French colonial administration took over in 1919 (materials destroyed, teaching banned); undergoing documented revival since 2022. `latest: null` reflects the ongoing revival rather than continuous unbroken use.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_bamum.json"},{"id":"ws_brahmi","name":"Brahmi Script","origin_type":"UNCERTAIN","date_range":{"earliest":-300,"latest":500,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["South Asia"],"script_type":"ABUGIDA","descends_from":[{"writing_system_id":"ws_aramaic","confidence":"DISPUTED","claim_id":"claim_brahmi_aramaic_contested"}],"notes":"The Aramaic-derivation hypothesis (Weber 1856) has been the traditionally dominant candidate, tied to Achaemenid administrative use of Aramaic in the Indus Valley, but no scholar has produced an adequate letter-by-letter derivation and significant structural mismatches remain unexplained. A rival indigenous/Indus-script-derivation hypothesis is characterized in the literature as speculative given the ~1000-year material gap. origin_type coded UNCERTAIN, not ADAPTATION, reflecting this unresolved state.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_brahmi.json"},{"id":"ws_cherokee","name":"Cherokee Syllabary","origin_type":"STIMULUS_DIFFUSION","date_range":{"earliest":1821,"latest":null,"precision":"YEAR","date_semantics":"EVENT_DATE"},"region":["North America"],"script_type":"SYLLABIC","descends_from":[],"notes":"Sequoyah (George Guess/Gist), a monolingual Cherokee speaker who never learned to read or write English, began work c. 1809 after observing literate soldiers during the War of 1812/Creek War; completed an 86-character (later 85) syllabary by 1821, formally adopted by the Cherokee National Council in 1825. His character shapes visibly resemble Latin/Greek/Cyrillic letterforms he had seen but could not read, while the sound values are entirely his own invention — the clean stimulus-diffusion signature. Still in active use — `latest: null`.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_cherokee.json"},{"id":"ws_chinese_script","name":"Chinese Script (Oracle Bone Script and descendant forms)","origin_type":"INDEPENDENT","date_range":{"earliest":-1250,"latest":null,"precision":"ORDER_OF_MAGNITUDE","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["East Asia"],"script_type":"LOGOGRAPHIC","descends_from":[],"notes":"Modeled as ONE WritingSystem entity spanning oracle bone script (jiǎgǔwén) through bronze inscriptions, seal script, clerical script, and modern characters, per the mainstream paleographic framing of this as continuous evolution rather than successive independent inventions (⟨INFERENCE⟩ modeling choice built on that documented continuity claim, not itself a cited scholarly statement about \"WritingSystem entities\"). `latest: null` because the script remains in active use. Neolithic \"proto-writing\" candidates (Jiahu ~6600 BCE, Banpo, Dinggong) are NOT treated as confirmed antecedents — see claim_chinese_neolithic_precursors_disputed.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_chinese_script.json"},{"id":"ws_cuneiform","name":"Cuneiform","origin_type":"INDEPENDENT","date_range":{"earliest":-3350,"latest":null,"precision":"ORDER_OF_MAGNITUDE","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Western Asia"],"script_type":"LOGOSYLLABIC","descends_from":[],"notes":"Proto-cuneiform (Uruk IV, c. 3350-3200 BCE) is administrative/economic proto-writing, not yet a full phonetic system; mature logo-syllabic cuneiform capable of recording continuous language develops over the Early Dynastic period (to c. 2900 BCE). `latest: null` reflects that this research batch verified the origin and decipherment history, not the script's end-of-use date (commonly cited as a 1st-century-CE astronomical almanac); that endpoint was not independently re-verified this session and should not be read as \"still in active use\" — flagged for a dedicated follow-up pass. See claim_cuneiform_origin_type and claim_cuneiform_decipherment_status.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_cuneiform.json"},{"id":"ws_cyrillic","name":"Cyrillic Script","origin_type":"ADAPTATION","date_range":{"earliest":890,"latest":null,"precision":"DECADE","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Europe"],"script_type":"ALPHABETIC","descends_from":[{"writing_system_id":"ws_greek","confidence":"HIGH","claim_id":"claim_cyrillic_descends_greek_not_glagolitic"}],"notes":"Commonly and incorrectly attributed to Saint Cyril; Cyril and Methodius actually created the distinct Glagolitic script (c. 863 CE) for their Moravian mission. Cyrillic was developed later, in the 890s CE, by their students (most specifically Saint Clement of Ohrid) at the Preslav Literary School, using uncial Greek letterforms as its base and named \"Cyrillic\" retrospectively in his honor. Still in active use — `latest: null`.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_cyrillic.json"},{"id":"ws_egyptian_hieroglyphs","name":"Egyptian Hieroglyphs","origin_type":"INDEPENDENT","date_range":{"earliest":-3320,"latest":null,"precision":"ORDER_OF_MAGNITUDE","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Africa"],"script_type":"LOGOSYLLABIC","descends_from":[],"notes":"`latest: null` reflects that hieroglyphic use is conventionally described as ending in Late Antiquity (the last securely dated hieroglyphic inscription is often cited as the Philae temple graffito of 394 CE); that endpoint was not independently re-verified this session and should not be read as \"still in active use\" — flagged for follow-up. Whether Egyptian hieroglyphs are independent of or influenced by contact with proto-cuneiform Mesopotamia (stimulus diffusion of the general idea of writing, not sign-borrowing) is a live, unresolved question — see claim_egyptian_origin_type.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_egyptian_hieroglyphs.json"},{"id":"ws_epi_olmec","name":"Epi-Olmec (Isthmian) Script","origin_type":"UNCERTAIN","date_range":{"earliest":-900,"latest":-300,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["North America"],"script_type":"LOGOSYLLABIC","descends_from":[],"notes":"Encompasses the disputed Cascajal Block (c. 900 BCE, recovered out of archaeological context, authenticity/status as writing contested) and the later La Mojarra Stela 1 / Tuxtla Statuette corpus (Isthmian script proper, 1st-2nd century CE). Whether these represent one continuous tradition or should be split is itself part of the dispute recorded in claim_cascajal_authenticity_disputed and claim_epi_olmec_decipherment_disputed.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_epi_olmec.json"},{"id":"ws_greek","name":"Greek Alphabet","origin_type":"ADAPTATION","date_range":{"earliest":-800,"latest":null,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Europe"],"script_type":"ALPHABETIC","descends_from":[{"writing_system_id":"ws_phoenician","confidence":"HIGH","claim_id":"claim_greek_descends_phoenician"}],"notes":"The first script with dedicated, systematic vowel letters: Phoenician consonant signs for sounds absent from Greek (glottal/pharyngeal, e.g. aleph, he, yod, ayin) were repurposed as vowels (alpha, epsilon, iota, omicron). Still in active use — `latest: null`.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_greek.json"},{"id":"ws_hangul","name":"Hangul","origin_type":"STIMULUS_DIFFUSION","date_range":{"earliest":1443,"latest":null,"precision":"YEAR","date_semantics":"EVENT_DATE"},"region":["East Asia"],"script_type":"ALPHABETIC","descends_from":[],"notes":"Created under King Sejong the Great (r. 1418-1450), completed December 1443, promulgated 1446 (Hunminjeongeum). The Hunminjeongeum Haerye, rediscovered in 1940, is an unusually direct surviving primary document explaining the featural design logic (consonant shapes as stylized diagrams of articulator positions). Gari Ledyard's minority hypothesis (Columbia PhD thesis 1966/1998) that 5-6 basic consonant shapes were adapted from the Mongol 'Phags-pa script is explicitly characterized in the literature as less popular than the mainstream original-invention position; even Ledyard's own account limits any borrowing to letter shapes, not the featural phonetic principle itself. Still in active use — `latest: null`.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_hangul.json"},{"id":"ws_indus","name":"Indus Valley Script","origin_type":"UNCERTAIN","date_range":{"earliest":-2600,"latest":-1900,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["South Asia"],"script_type":"UNKNOWN","descends_from":[],"notes":"origin_type is conditional: IF this is writing, INDEPENDENT is the best-supported classification (no evidence of derivation from Mesopotamian cuneiform or Egyptian hieroglyphs, despite documented Indus-Mesopotamia trade contact via \"Meluhha\"). But whether the ~400-sign corpus constitutes writing at all is a live, unresolved dispute — see claim_indus_writing_status_disputed. Precursor sign-like marks on Ravi-phase pottery go back to c. 3900-2800 BCE and are treated as proto-signs, not confirmed script.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_indus.json"},{"id":"ws_japanese_kana","name":"Japanese Kana (Hiragana and Katakana)","origin_type":"ADAPTATION","date_range":{"earliest":800,"latest":null,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["East Asia"],"script_type":"SYLLABIC","descends_from":[{"writing_system_id":"ws_chinese_script","confidence":"HIGH","claim_id":"claim_kana_descends_chinese"}],"notes":"Both syllabaries derive from man'yōgana (Chinese characters used purely phonetically for Japanese sounds, traceable to the 5th century CE); hiragana emerged as cursive simplification of whole kanji, katakana by taking fragments/components of kanji, both taking recognizable shape in the 9th-century Heian period. The popular attribution of hiragana's invention to the monk Kūkai is a legend, not documented history — no signed document supports it, and the Heian-period evidence instead shows a gradual, collective, multi-decade development with no single named inventor. Still in active use — `latest: null`.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_japanese_kana.json"},{"id":"ws_khipu","name":"Khipu (Quipu)","origin_type":"UNCERTAIN","date_range":{"earliest":1400,"latest":1600,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["South America"],"script_type":"UNKNOWN","descends_from":[],"notes":"Andean knotted-string recording devices (Inka and predecessor cultures). Whether khipu constitute writing at all — as opposed to a purely numerical/mnemonic accounting device — is itself a live, unresolved dispute, not merely an origin-type question; see claim_khipu_writing_status_disputed. Confidently read as numerical/accounting records; narrative/linguistic content (argued for by Urton 2003 and subsequent statistical work) remains unconfirmed by any accepted decipherment.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_khipu.json"},{"id":"ws_latin","name":"Latin Alphabet","origin_type":"ADAPTATION","date_range":{"earliest":-700,"latest":null,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Europe"],"script_type":"ALPHABETIC","descends_from":[{"writing_system_id":"ws_greek","confidence":"MODERATE","claim_id":"claim_latin_descends_greek_etruscan"}],"notes":"Transmitted via the Etruscan alphabet (itself imported from Euboean Greek colonies at Cumae/Ischia, 8th c. BCE); whether Latin's source is Etruscan-mediated or a more direct Cumaean-Greek borrowing bypassing Etruscan is a live, documented dispute. Still in active use — `latest: null`.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_latin.json"},{"id":"ws_linear_a","name":"Linear A","origin_type":"INDEPENDENT","date_range":{"earliest":-1800,"latest":-1450,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Europe"],"script_type":"SYLLABIC","descends_from":[],"notes":"Used on Crete and some Aegean islands, associated with Minoan civilization; corpus of roughly 1,400-1,500 inscribed objects (~7,300-7,400 signs), overwhelmingly short administrative/votive texts. Coded INDEPENDENT reflecting its internal Cretan development (as opposed to Linear B, which adapts Linear A's own signary for Greek — see ws_linear_b); Linear A's own relationship to the earlier, less-understood Cretan Hieroglyphic script is a separate, lower-certainty internal-evolution question not resolved by this research batch.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_linear_a.json"},{"id":"ws_linear_b","name":"Linear B","origin_type":"ADAPTATION","date_range":{"earliest":-1450,"latest":-1200,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Europe"],"script_type":"SYLLABIC","descends_from":[{"writing_system_id":"ws_linear_a","confidence":"HIGH","claim_id":"claim_linear_b_descends_linear_a"}],"notes":"Mycenaean scribes repurposed Linear A's syllabary (visually similar sign forms, shared inventory) to notate a different, and known, language — Mycenaean Greek — with phonetic modifications. This is why cracking Linear B did not solve Linear A: sign forms carry over, sign-to-sound values do not, since they were reapplied to a different language's phonology.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_linear_b.json"},{"id":"ws_maya_script","name":"Classic Maya Script","origin_type":"UNCERTAIN","date_range":{"earliest":-300,"latest":null,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["North America"],"script_type":"LOGOSYLLABIC","descends_from":[],"notes":"Region-level Mesoamerican writing has a strong claim to having developed with no Old World contact (INDEPENDENT at the macro level), but which Mesoamerican tradition (Olmec/Cascajal, Zapotec, Epi-Olmec/Isthmian) gave rise to Maya script specifically is unresolved — the 2005-2006 San Bartolo discovery shows a mature script by c. 300-200 BCE with no obvious transitional forms linking back to Olmec symbols, leading some scholars to treat Maya writing as a plausibly separate \"homegrown\" development. origin_type is coded UNCERTAIN at the system-derivation level; see claim_maya_origin_type. `latest: null` because a form of the script remains in ceremonial/decorative use and Mayan languages are still spoken, though the classic logosyllabic writing system itself fell out of common use after the Spanish conquest.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_maya_script.json"},{"id":"ws_meroitic","name":"Meroitic Script","origin_type":"ADAPTATION","date_range":{"earliest":-185,"latest":450,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Africa"],"script_type":"MIXED","descends_from":[{"writing_system_id":"ws_egyptian_hieroglyphs","confidence":"HIGH","claim_id":"claim_meroitic_descends_egyptian"}],"notes":"Used in the Kingdom of Kush/Meroe (Nile valley, modern Sudan). Two forms, both derived from Egyptian writing: hieroglyphic (descended from Egyptian hieroglyphs) and cursive (the majority of surviving texts, descended from Egyptian demotic). A strong PARTIAL-decipherment example: the 23-sign script's phonetic values were established by Francis Llewellyn Griffith (1909-1911), but the underlying Meroitic language remained largely unparsed for decades until Claude Rilly (CNRS) demonstrated it belongs to a Nilo-Saharan branch he named Northern East Sudanic (Rilly and de Voogt, Cambridge University Press, 2012).","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_meroitic.json"},{"id":"ws_nko","name":"N'Ko Script","origin_type":"STIMULUS_DIFFUSION","date_range":{"earliest":1949,"latest":null,"precision":"YEAR","date_semantics":"EVENT_DATE"},"region":["Africa"],"script_type":"ALPHABETIC","descends_from":[],"notes":"Created by Solomana Kanté (Souleymane Kanté) in Guinea/Côte d'Ivoire, completed 1949, after experimenting with and rejecting adaptations of Arabic and Latin script for Maninka's tone/vowel system. Visually resembles Arabic script (cursive, right-to-left) but is structurally a genuine alphabet with obligatory tone marking, built from scratch rather than adapted sign-by-sign from Arabic. The oft-repeated motivating anecdote (a Lebanese journalist claiming African languages were \"unwritable\") is well-attested as N'Ko community history but not independently confirmed outside that tradition — flagged accordingly. Still in active use — `latest: null`.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_nko.json"},{"id":"ws_phoenician","name":"Phoenician Alphabet","origin_type":"ADAPTATION","date_range":{"earliest":-1000,"latest":-300,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Western Asia"],"script_type":"ABJAD","descends_from":[{"writing_system_id":"ws_proto_sinaitic","confidence":"HIGH","claim_id":"claim_phoenician_descends_proto_sinaitic"}],"notes":"The conventional \"c. 1050 BCE\" start date is an epigraphic-record-gap convention, not a confirmed founding moment; the standardized 22-letter script emerges gradually, c. 1000-900 BCE.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_phoenician.json"},{"id":"ws_proto_sinaitic","name":"Proto-Sinaitic Script","origin_type":"ADAPTATION","date_range":{"earliest":-1850,"latest":-1500,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Western Asia","Africa"],"script_type":"ABJAD","descends_from":[{"writing_system_id":"ws_egyptian_hieroglyphs","confidence":"HIGH","claim_id":"claim_proto_sinaitic_descends_egyptian"}],"notes":"Acrophonic adaptation of a small subset of Egyptian hieroglyphic signs by Semitic-speaking workers, per Gardiner 1916 and refined by Goldwasser 2006-2020. Found at Serabit el-Khadim (Sinai) and Wadi el-Hol (Egypt proper).","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_proto_sinaitic.json"},{"id":"ws_rongorongo","name":"Rongorongo","origin_type":"UNCERTAIN","date_range":{"earliest":1493,"latest":1900,"precision":"CENTURY","date_semantics":"EARLIEST_SURVIVING_EVIDENCE"},"region":["Oceania"],"script_type":"UNKNOWN","descends_from":[],"notes":"First documented by Europeans in the 1860s; roughly two dozen (24-27 depending on counting method) surviving authentic tablets. Whether it predates European contact (1722) is genuinely unresolved even in the most recent (2024) primary radiocarbon literature (Ferrara et al., Scientific Reports 2024) — one tablet's wood dated 1493-1509 CE, but the authors themselves declined to treat this as settling the pre/post-contact question given the \"old wood\" problem (dated felling, not inscribing) and a sample size of one. Coded UNCERTAIN rather than resolved toward either INDEPENDENT or STIMULUS_DIFFUSION.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_rongorongo.json"},{"id":"ws_vai","name":"Vai Script","origin_type":"STIMULUS_DIFFUSION","date_range":{"earliest":1833,"latest":null,"precision":"YEAR","date_semantics":"EVENT_DATE"},"region":["Africa"],"script_type":"SYLLABIC","descends_from":[],"notes":"Created by Momolu Duwalu Bukele in Liberia, c. 1832-1834; the missionary-recorded \"dream\" founding narrative is internally inconsistent across near-contemporary transcriptions and is treated by scholars as a likely religious/status-conferring gloss on a mundane contact-inspired invention process. Vai characters bear no visual resemblance to Cherokee ones despite a documented possible indirect Cherokee contact channel (Austin Curtis, a Cherokee man who married into a Vai chief's family in 1823) — supporting transmission of the concept of syllabic writing rather than sign-copying. Still in active use — `latest: null`.","_entity_type":"WritingSystem","_source_path":"docs/timeline/data/entities/writing_systems/ws_vai.json"}],"claims":[{"id":"claim_ld350_earliest_homo","subject_type":"Population","subject_id":"pop_early_homo","statement":"The oldest fossil confidently attributed to genus Homo is LD 350-1, a partial mandible with five teeth from Ledi-Geraru, Afar, Ethiopia, dated 2.80-2.75 million years ago via argon-argon (⁴⁰Ar/³⁹Ar) dating of bracketing volcanic tephra layers combined with tephrostratigraphic and magnetostratigraphic correlation.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-2800000,"latest":-2750000,"central":-2775000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Africa"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Villmoare, B., Kimbel, W.H., Seyoum, C., et al. \"Early Homo at 2.8 Ma from Ledi-Geraru, Afar, Ethiopia.\" Science 347(6228): 1352-1355.","author":"Villmoare et al.","year":2015,"venue":"Science","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"DiMaggio, E.N., Campisano, C.J., Rowan, J., et al. \"Late Pliocene fossiliferous sedimentary record and the environmental context of early Homo from Afar, Ethiopia.\" Science 347(6228): 1355-1359.","author":"DiMaggio et al.","year":2015,"venue":"Science","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_ld350_earliest_homo.json"},{"id":"claim_ledi_geraru_overlap_2025","subject_type":"Population","subject_id":"pop_early_homo","statement":"A 2025/2026 study reports 13 additional fossil teeth from Ledi-Geraru showing Homo material at 2.78 and 2.59 million years ago and a new, unnamed Australopithecus species (not A. afarensis) at 2.63 million years ago, indicating early Homo and a distinct Australopithecus species co-existed at the same site 2.5-2.8 million years ago — alongside previously known Australopithecus garhi and Paranthropus material from the same general period in eastern Africa.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-2800000,"latest":-2590000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Africa"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Reed, K.E. et al. \"New discoveries of Australopithecus and Homo from Ledi-Geraru, Ethiopia.\" Nature 650: 374-380.","author":"Reed et al.","year":2026,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":"Published online Aug 2025 (PMID 40804525); formal issue 2026."}],"interpretations":[],"does_not_demonstrate":["that Homo evolved from Australopithecus via a single linear replacement in this region","that only one non-Homo hominin lineage was present alongside early Homo in this period — at least three (this new species, A. garhi, Paranthropus) are attested in eastern Africa in the same broad window"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_ledi_geraru_overlap_2025.json"},{"id":"claim_habilis_daterange","subject_type":"Population","subject_id":"pop_homo_habilis","statement":"Homo habilis-attributed material dates to approximately 2.4-1.5 million years ago, with the type specimen OH 7 (Olduvai Gorge, Tanzania) dated to approximately 1.8 million years ago and cranial capacity estimates of roughly 510-687 cm³ across attributed specimens.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-2400000,"latest":-1500000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Africa"],"evidence_types":["ARCHAEOLOGY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Leakey, L.S.B., Tobias, P.V., Napier, J.R. Original description of Homo habilis (type specimens OH 7, OH 4, OH 6, OH 8, OH 13).","author":null,"year":1964,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Smithsonian Human Origins Program, \"Homo habilis\" species page.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_habilis_daterange.json"},{"id":"claim_erectus_first_appearance","subject_type":"Population","subject_id":"pop_homo_erectus","statement":"The oldest confidently-dated Homo erectus/ergaster fossil is KNM-ER 2598 (an occipital/cranial fragment), East Turkana, Kenya, dated to approximately 1.88-1.9 million years ago, stratigraphically below the KBS Tuff; this dating was reaffirmed with new associated postcrania in 2021 after decades of uncertainty because the original specimen was a surface find.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-1900000,"latest":-1880000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Africa"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Hammond, A.S., Royer, D.F., Fox, N.S., et al. \"New hominin remains and revised context from the earliest Homo erectus locality in East Turkana, Kenya.\" Nature Communications 12: 1939.","author":"Hammond et al.","year":2021,"venue":"Nature Communications","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":"KNM-ER 3733, a more complete and famous cranium often cited in popular sources as illustrating the species’ first appearance, is actually dated to roughly 1.6-1.78 million years ago — several hundred thousand years younger than KNM-ER 2598 — and should not be used as the earliest-appearance anchor.","status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_erectus_first_appearance.json"},{"id":"claim_dmanisi_out_of_africa","subject_type":"Population","subject_id":"pop_homo_erectus","statement":"Hominin remains at Dmanisi, Georgia (Caucasus), dated 1.85-1.78 million years ago via the associated stratigraphy, represent the earliest confirmed hominin presence outside Africa. The material is anatomically primitive/mosaic, mixing habilis-like and erectus-like traits; the most complete specimen is Dmanisi Skull 5 (D4500), the most complete Early Pleistocene Homo skull known.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-1850000,"latest":-1780000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Western Asia"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Ferring, R., Oms, O., Agústí, J., et al. \"Earliest human occupations at Dmanisi (Georgian Caucasus) dated to 1.85-1.78 Ma.\" PNAS 108(26): 10432-10436.","author":"Ferring et al.","year":2011,"venue":"PNAS","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["that this was the only or the earliest possible dispersal of hominins out of Africa — it is the earliest currently confirmed by dated fossil evidence","that Dmanisi hominins are taxonomically identical to African Homo erectus populations — a minority position (led by the Dmanisi excavation team) treats them as a distinct taxon, \"Homo georgicus\""],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_dmanisi_out_of_africa.json"},{"id":"claim_neanderthal_sapiens_divergence","subject_type":"Population","subject_id":"pop_neanderthal","statement":"Genomic analysis of a high-coverage Neanderthal genome from the Altai Mountains estimates the population divergence between the Neanderthal/Denisovan ancestral lineage and the Homo sapiens lineage at approximately 550,000-765,000 years ago — a genetic model estimate, distinct from and often conflated with the much younger fossil date range of classic Neanderthal specimens themselves (see claim_sima_de_los_huesos_earliest and claim_neanderthal_extinction_date). Other calibrations and models produce somewhat different ranges.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-765000,"latest":-550000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Europe"],"evidence_types":["ANCIENT_DNA","SCIENTIFIC_ANALYSIS"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Prüfer, K. et al. \"The complete genome sequence of a Neanderthal from the Altai Mountains.\" Nature 505: 43-49.","author":"Prüfer et al.","year":2014,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Confidence set to MODERATE rather than HIGH because the reporting agent noted other calibrations/mutation-rate models give somewhat different divergence ranges; this is a model-dependent estimate, not a direct observation.","_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_neanderthal_sapiens_divergence.json"},{"id":"claim_neanderthal_denisovan_divergence","subject_type":"Population","subject_id":"pop_neanderthal","statement":"The Neanderthal and Denisovan lineages are estimated to have diverged from each other approximately 381,000-473,000 years ago — a distinct, more recent split than either lineage’s divergence from Homo sapiens (~550,000-765,000 years ago). A 2020 study additionally proposes the joint Neanderthal-Denisovan ancestral population itself interbred with a more distantly related \"super-archaic\" population (roughly 2 million years divergent) around 700,000 years ago, adding a layer of admixture complexity beneath the clean divergence figure without changing it.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-473000,"latest":-381000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Europe","Central Asia"],"evidence_types":["ANCIENT_DNA","SCIENTIFIC_ANALYSIS"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Prüfer, K. et al. \"The complete genome sequence of a Neanderthal from the Altai Mountains.\" Nature 505: 43-49.","author":"Prüfer et al.","year":2014,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Rogers, A.R., Harris, N.S., Achenbach, A.A. \"Neanderthal-Denisovan ancestors interbred with a distantly related hominin.\" Science Advances 6(8): eaay5483.","author":"Rogers et al.","year":2020,"venue":"Science Advances","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["a \"clean\" two-population divergence uncomplicated by further admixture — see the Rogers et al. 2020 \"super-archaic\" admixture proposal noted in the statement"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_neanderthal_denisovan_divergence.json"},{"id":"claim_sima_de_los_huesos_earliest","subject_type":"Population","subject_id":"pop_neanderthal","statement":"The oldest fossils confidently placed on the Neanderthal branch (post-dating the split from the modern-human lineage but pre-dating classic Neanderthal morphology) are from Sima de los Huesos, Atapuerca, Spain, dated to approximately 430,000 years ago via uranium-series and paleomagnetic methods, with nuclear DNA confirming their placement on the Neanderthal lineage.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-430000,"latest":-430000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Europe"],"evidence_types":["ARCHAEOLOGY","ANCIENT_DNA","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Arsuaga, J.L. et al. \"Neandertal roots: Cranial and chronological evidence from Sima de los Huesos.\" Science 344: 1358-1363.","author":"Arsuaga et al.","year":2014,"venue":"Science","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Meyer, M. et al. \"Nuclear DNA sequences from the Middle Pleistocene Sima de los Huesos hominins.\" Nature 531: 504-507.","author":"Meyer et al.","year":2016,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["that these individuals were \"Neanderthals\" in the strict classic morphological sense — they are proto-Neanderthal lineage material"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_sima_de_los_huesos_earliest.json"},{"id":"claim_jebel_irhoud_redate","subject_type":"Population","subject_id":"pop_homo_sapiens","statement":"Fossils from Jebel Irhoud, Morocco, previously estimated at roughly 40,000-160,000 years old, were redated in 2017 to 315 ± 34 thousand years ago via thermoluminescence dating of associated fire-heated flint artifacts (range approx. 349-281 ka at 1σ), cross-checked with electron spin resonance dating on a hominin tooth — making this the oldest well-dated Homo sapiens material at time of publication, roughly 100,000+ years older than the previous best-dated specimen (Omo Kibish).","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-349000,"latest":-281000,"central":-315000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Africa"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Hublin, J.-J., Ben-Ncer, A., Bailey, S.E., et al. \"New fossils from Jebel Irhoud, Morocco and the pan-African origin of Homo sapiens.\" Nature 546: 289-292. DOI: 10.1038/nature22336","author":"Hublin et al.","year":2017,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Richter, D., Grün, R., Joannes-Boyau, R., et al. \"The age of the hominin fossils from Jebel Irhoud, Morocco, and the origins of the Middle Stone Age.\" Nature 546: 293-296. DOI: 10.1038/nature22335","author":"Richter et al.","year":2017,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Report as \"315 ± 34 ka,\" not a bare rounded \"300,000\" — the precision matters for the app’s no-false-precision principle.","_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_jebel_irhoud_redate.json"},{"id":"claim_denisova_cave_date_range","subject_type":"Population","subject_id":"pop_denisovan","statement":"At the Denisova Cave type site, Bayesian modeling of the fossils themselves dates the oldest Denisovan fossil to approximately 195,000 years ago and the youngest to 52,000-76,000 years ago (with Neanderthal fossils at the same site, including a first-generation Neanderthal-Denisovan hybrid individual, falling between 80,000-140,000 years ago). A separate sediment (environmental) ancient-DNA study extends the earliest attested Denisovan genetic signal at the site to approximately 250,000-170,000 years ago, associated with early Middle Palaeolithic tools, and documents a Denisovan mitochondrial-DNA population turnover after roughly 80,000 years ago.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-250000,"latest":-52000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Central Asia"],"evidence_types":["ARCHAEOLOGY","ANCIENT_DNA","SCIENTIFIC_ANALYSIS"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Douka, K. et al. \"Age estimates for hominin fossils and the onset of the Upper Palaeolithic at Denisova Cave.\" Nature 565: 640-644.","author":"Douka et al.","year":2019,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Jacobs, Z. et al. \"Timing of archaic hominin occupation of Denisova Cave in southern Siberia.\" Nature 565: 594-599.","author":"Jacobs et al.","year":2019,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Zavala, E.I. et al. \"Pleistocene sediment DNA reveals hominin and faunal turnovers at Denisova Cave.\" Nature 595: 399-403.","author":"Zavala et al.","year":2021,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Confidence set to MODERATE because the fossil-based range (195,000-52,000 ya) and the sediment-DNA-based range (up to ~250,000 ya) rest on different evidence types and should not be silently merged into one number when rendered — report both, sourced separately.","_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_denisova_cave_date_range.json"},{"id":"claim_omo_kibish_redate","subject_type":"Population","subject_id":"pop_homo_sapiens","statement":"The Omo I fossil (Omo Kibish, Ethiopia) was originally dated to 195 ± 5 thousand years ago via argon-argon dating of bracketing volcanic tuffs (McDougall, Brown & Fleagle 2005); a 2022 study using geochemical fingerprinting of an overlying volcanic ash layer revised this to a minimum age of greater than 233,000 ± 22,000 years, since the ash constrains only a lower bound and the true age could be older.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-233000,"latest":null,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Africa"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"McDougall, I., Brown, F.H., Fleagle, J.G. \"Stratigraphic placement and age of modern humans from Kibish, Ethiopia.\" Nature 433: 733-736.","author":"McDougall et al.","year":2005,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Vidal, C.M., Lane, C.S., Asrat, A., et al. \"Age of the oldest known Homo sapiens from eastern Africa.\" Nature 601: 579-583. DOI: 10.1038/s41586-021-04275-8","author":"Vidal et al.","year":2022,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Complementary to, not competing with, the Jebel Irhoud dating: Jebel Irhoud remains older and shows more archaic cranial morphology; Omo I is younger and morphologically closer to fully modern humans.","_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_omo_kibish_redate.json"},{"id":"claim_xiahe_mandible","subject_type":"Population","subject_id":"pop_denisovan","statement":"A mandible from Baishiya Karst Cave, Xiahe, on the Tibetan Plateau, is the first physical/morphological Denisovan evidence found outside Denisova Cave. It was identified as Denisovan via ancient protein (paleoproteomic) analysis, since no DNA survived, and dated to at least approximately 160,000 years ago via uranium-series dating of an adhering carbonate matrix.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-160000,"latest":null,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["East Asia"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Chen, F. et al. \"A late Middle Pleistocene Denisovan mandible from the Tibetan Plateau.\" Nature 569: 409-412.","author":"Chen et al.","year":2019,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_xiahe_mandible.json"},{"id":"claim_erectus_ngandong_last","subject_type":"Population","subject_id":"pop_homo_erectus","statement":"The last confirmed appearance of Homo erectus is a bone bed at Ngandong, Java, modeled via 52 radiometric age estimates (uranium-series on speleothems, luminescence and ⁴⁰Ar/³⁹Ar on river terraces, and U-series/electron-spin-resonance on associated fossils) to 117,000-108,000 years ago — substantially overturning earlier, less rigorously dated claims of survival to as recently as ~27,000-53,000 years ago.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-117000,"latest":-108000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Southeast Asia"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Rizal, Y., Westaway, K.E., Zaim, Y., et al. \"Last appearance of Homo erectus at Ngandong, Java, 117,000-108,000 years ago.\" Nature 577: 381-385.","author":"Rizal et al.","year":2020,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["that Homo erectus and Homo sapiens populations had direct contact in this region — the finding establishes temporal overlap at a continental/regional scale, not encounter","that Homo erectus persisted this late anywhere outside this specific Javan locality"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_erectus_ngandong_last.json"},{"id":"claim_neanderthal_admixture_purging","subject_type":"Population","subject_id":"pop_homo_sapiens","statement":"The initial pulse of Neanderthal-to-modern-human gene flow (roughly 50,000-60,000 years ago) was likely substantially higher than 5% of the genome, and was subsequently reduced by natural selection purging deleterious archaic variants over succeeding generations — which is why the Neanderthal-ancestry fraction observed in living genomes today (see claim_neanderthal_ancestry_by_population) is much lower than the original admixture event itself.","claim_tier":"CAUSAL_EXPLANATION","related_observation_id":"claim_neanderthal_ancestry_by_population","date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-60000,"latest":-50000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Europe","Asia"],"evidence_types":["ANCIENT_DNA","SCIENTIFIC_ANALYSIS"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Harris, K. & Nielsen, R. \"The Genetic Cost of Neanderthal Introgression.\" Genetics 203(2): 881-891.","author":"Harris & Nielsen","year":2016,"venue":"Genetics","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Juric, I., Aeschbacher, S., Coop, G. \"The Strength of Selection against Neanderthal Introgression.\" PLOS Genetics 12(11): e1006340.","author":"Juric, Aeschbacher & Coop","year":2016,"venue":"PLOS Genetics","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_neanderthal_admixture_purging.json"},{"id":"claim_neanderthal_extinction_multicausal","subject_type":"Population","subject_id":"pop_neanderthal","statement":"Current literature treats the causes of Neanderthal extinction as multi-causal rather than settled on a single factor, with population size/genetic diversity, climate volatility (particularly during Marine Isotope Stage 3), competition and resource overlap with expanding Homo sapiens populations, interbreeding/absorption into the larger sapiens population, and inter-group social-network connectivity all treated as contributing mechanisms in recent (2021-2026) sources, with genuine disagreement over relative weighting and no field-wide consensus statement identified.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-60000,"latest":-40000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Europe"],"evidence_types":["ARCHAEOLOGY","ANCIENT_DNA","SCIENTIFIC_ANALYSIS"],"confidence":"DISPUTED","scholarly_disagreement":"Relative weighting of demography/population structure versus climate versus competition versus interbreeding-absorption versus social-network connectivity; a 2021 paper frames demography as the primary driver, while 2025-2026 modeling work treats demography as necessary-but-not-sufficient, decisive mainly in combination with climate-driven connectivity loss.","sources":[{"type":"SECONDARY","citation":"Multiple 2024-2026 sources (EU-funded research summaries, Smithsonian science coverage) stating that climate stress or direct competition alone cannot explain the extinction.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"SEARCH_SNIPPET","access_note":null},{"type":"SECONDARY","citation":"2025 preprint modeling inter-band connectivity and climate jointly as shaping Neanderthal extinction and Homo sapiens dispersal.","author":null,"year":2025,"venue":"bioRxiv","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"SEARCH_SNIPPET","access_note":null},{"type":"SECONDARY","citation":"\"An emerging consensus in palaeoanthropology\" (2021), arguing demography specifically was the main factor — one paper’s framing, not confirmed as field-wide.","author":null,"year":2021,"venue":"Scientific Reports","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"SEARCH_SNIPPET","access_note":null}],"interpretations":[{"position":"Demography (small, structured effective population size) was the primary driver","holders":[{"name":"Unnamed authors, \"An emerging consensus in palaeoanthropology,\" Scientific Reports (2021) — author names not independently confirmed in this research pass","camp":"[PALEOANTHROPOLOGY — DEMOGRAPHY-PRIMARY]"}],"status":"MINORITY","strongest_case":"Small, structured populations with reduced genetic diversity are demonstrably vulnerable to stochastic extinction independent of any single environmental trigger."},{"position":"Social/network connectivity, interacting with climate volatility, was decisive; demography alone is necessary but not sufficient","holders":[{"name":"Authors of 2025-2026 network-connectivity modeling studies (bioRxiv preprint and related coverage) — author names not independently confirmed in this research pass","camp":"[ARCHAEOLOGY / COMPUTATIONAL MODELING]"}],"status":"MAJORITY","strongest_case":"Modeling that incorporates inter-group connectivity alongside climate and demography better matches the observed regional and temporal pattern of Neanderthal disappearance than demography-only models."}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Author names for several of the most recent (2021, 2025, 2026) sources could not be independently confirmed in this research pass and are deliberately omitted rather than guessed — cite by publication/venue only until verified. A named attempt to attribute specific positions to Fred Smith or Katerina Harvati specifically failed verification and those names are not used here.","_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_neanderthal_extinction_multicausal.json"},{"id":"claim_neanderthal_ancestry_by_population","subject_type":"Population","subject_id":"pop_homo_sapiens","statement":"Neanderthal genetic ancestry in living human populations varies by population and is not one global figure: approximately 1.8-2.1% in Europeans and approximately 2.3-2.6% in East Asians (East Asians carrying roughly 12-20% more than Europeans, an asymmetry whose cause is disputed), with West African populations carrying a smaller (~0.3%) signal now attributed to back-migration of Eurasian, Neanderthal-ancestry-carrying lineages into Africa within roughly the last 20,000-50,000 years, rather than a separate direct African-Neanderthal admixture event.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-50000,"latest":-20000,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Europe","East Asia","Africa"],"evidence_types":["ANCIENT_DNA","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":"The cause of the higher Neanderthal-ancestry fraction in East Asians than Europeans is disputed: differential efficiency of purifying selection (Sankararaman et al. 2014) versus an additional pulse of Neanderthal gene flow specifically into East Asian ancestors, which selection/drift alone cannot fully explain (Vernot & Akey 2015).","sources":[{"type":"PRIMARY","citation":"Green, R.E. et al. \"A draft sequence of the Neandertal genome.\" Science 328(5979): 710-722.","author":"Green et al.","year":2010,"venue":"Science","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Sankararaman, S. et al. \"The genomic landscape of Neanderthal ancestry in present-day humans.\" Nature 507: 354-357.","author":"Sankararaman et al.","year":2014,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Vernot, B. & Akey, J.M. \"Resurrecting Surviving Neandertal Lineages from Modern Human Genomes.\" Science 343(6174): 1017-1021; and \"Selection and Reduced Population Size Cannot Explain Higher Amounts of Neandertal Ancestry in East Asian than European Populations.\" American Journal of Human Genetics 96(3): 448-453.","author":"Vernot & Akey","year":2014,"venue":"Science / American Journal of Human Genetics","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Chen, L., Wolf, A.B., Fu, W., Li, L., Akey, J.M. \"Identifying and Interpreting Apparent Neanderthal Ancestry in African Individuals.\" Cell 180(4): 677-687.","author":"Chen et al.","year":2020,"venue":"Cell","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Differential efficiency of purifying selection against deleterious Neanderthal variants explains the Europe/East-Asia asymmetry","holders":[{"name":"Sriram Sankararaman et al.","work":"Nature 507:354-357","year":2014,"camp":"[POPULATION GENETICS]"}],"status":"CONTESTED"},{"position":"Selection and reduced population size alone cannot explain the asymmetry; an additional gene-flow pulse into East Asian ancestors is required","holders":[{"name":"Benjamin Vernot & Joshua Akey","work":"American Journal of Human Genetics 96(3):448-453","year":2015,"camp":"[POPULATION GENETICS]"}],"status":"CONTESTED"}],"does_not_demonstrate":["that sub-Saharan African populations carry zero Neanderthal ancestry — that older framing is now an outdated oversimplification per Chen et al. 2020"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_neanderthal_ancestry_by_population.json"},{"id":"claim_neanderthal_extinction_date","subject_type":"Population","subject_id":"pop_neanderthal","statement":"Recalibrated AMS radiocarbon chronology places the end of Mousterian (Neanderthal-associated) archaeological assemblages at 41,030-39,260 calibrated years before present (95.4% probability) across the sampled European range — revising downward earlier claims of Neanderthal survival to as recently as ~24,000 years ago at some sites (e.g. Gorham’s Cave, Gibraltar), which this study attributes largely to contamination in older, unfiltered radiocarbon samples.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-41030,"latest":-39260,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Europe"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Higham, T. et al. \"The timing and spatiotemporal patterning of Neanderthal disappearance.\" Nature 512: 306-309.","author":"Higham et al.","year":2014,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Some subsequent work (e.g. on Northwest Europe) argues for regional refinements, but the ~40,000-year figure (not the older ~24,000-year claims) is the current mainstream consensus figure.","_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_neanderthal_extinction_date.json"},{"id":"claim_neanderthal_symbolic_behavior_disputed","subject_type":"Population","subject_id":"pop_neanderthal","statement":"Whether Neanderthals possessed symbolic or ritual behavior comparable to Homo sapiens remains genuinely contested among specialists, not resolved in either direction. Key contested cases include a deeply-impressed, cross-hatched engraving on bedrock at Gorham’s Cave, Gibraltar, sealed beneath an undisturbed Neanderthal-associated (Mousterian) layer dated to more than 39,000 years old (before Homo sapiens is attested in that region), and the burial status of remains at La Chapelle-aux-Saints, France, where a 2014 reanalysis argued for intentional burial and a direct 2015 reply disputed that the pit and body position are explicable by natural/taphonomic processes instead.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":-39000,"latest":null,"precision":"ORDER_OF_MAGNITUDE"},"zoom_min":"Z1","zoom_max":"Z2","region":["Europe"],"evidence_types":["ARCHAEOLOGY"],"confidence":"DISPUTED","scholarly_disagreement":"Whether the strongest claimed \"art\" evidence (Gorham’s Cave engraving) and the strongest claimed \"ritual\" evidence (La Chapelle-aux-Saints burial) meet the evidentiary bar for intentional, symbolic Neanderthal behavior, or are explicable by non-symbolic/taphonomic processes and pattern-matching to contemporary Homo sapiens material culture.","sources":[{"type":"PRIMARY","citation":"Rodríguez-Vidal, J. et al. \"A rock engraving made by Neanderthals in Gibraltar.\" PNAS 111(37): 13301-13306.","author":"Rodríguez-Vidal et al.","year":2014,"venue":"PNAS","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Rendu, W. et al. reanalysis of La Chapelle-aux-Saints. Journal of Human Evolution 69: 80-92.","author":"Rendu et al.","year":2014,"venue":"Journal of Human Evolution","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Dibble, H. et al. reply disputing intentional-burial interpretation. Journal of Human Evolution 89 (reply).","author":"Dibble et al.","year":2015,"venue":"Journal of Human Evolution","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Ornament use, pigment use, and burial evidence together demonstrate genuine Neanderthal symbolic behavior","holders":[{"name":"João Zilhão","camp":"[ARCHAEOLOGY — PRO-SYMBOLIC-BEHAVIOR]"},{"name":"Francesco d’Errico","camp":"[ARCHAEOLOGY — PRO-SYMBOLIC-BEHAVIOR]"}],"status":"CONTESTED","strongest_case":"Pierced marine shells, mineral pigments, and modified raptor talons at Iberian sites, and Châtelperronian ivory beads/pierced canines, are too distinctive to be mere imitation of contemporary Homo sapiens (Aurignacian) material culture."},{"position":"The strongest \"art\" and \"burial\" claims do not meet the evidentiary bar for intentional symbolic behavior","holders":[{"name":"Harold Dibble and colleagues","work":"Journal of Human Evolution 89 (reply on La Chapelle-aux-Saints)","year":2015,"camp":"[ARCHAEOLOGY — SYMBOLIC-BEHAVIOR SKEPTIC]"}],"status":"CONTESTED","strongest_case":"The La Chapelle-aux-Saints pit and body position are explicable by natural/taphonomic processes; foundational skepticism about Middle Paleolithic symbolism traces to earlier work by Chase & Dibble."}],"does_not_demonstrate":["that Neanderthals categorically lacked symbolic cognition — a \"sapiens cognitively outcompeted Neanderthals\" narrative is not supportable as a settled, documented finding on this evidence"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_neanderthal_symbolic_behavior_disputed.json"},{"id":"claim_denisovan_genome_before_morphology","subject_type":"Population","subject_id":"pop_denisovan","statement":"Denisovans were identified as a population distinct from both Neanderthals and modern humans primarily through ancient DNA — first a complete mitochondrial genome, then a nuclear genome — from a finger-bone fragment at Denisova Cave, Siberia, before any diagnostic morphological/skeletal type description existed. This is noted in the literature as an unusual, arguably first, case of a hominin lineage being defined by molecular data in the absence of a diagnostic fossil.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":-2010,"latest":-2010,"precision":"YEAR"},"zoom_min":"Z1","zoom_max":"Z2","region":["Central Asia"],"evidence_types":["ANCIENT_DNA"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Krause, J. et al. \"The complete mitochondrial DNA genome of an unknown hominin from southern Siberia.\" Nature 464: 894-897.","author":"Krause et al.","year":2010,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Reich, D. et al. \"Genetic history of an archaic hominin group from Denisova Cave in Siberia.\" Nature 468: 1053-1060.","author":"Reich et al.","year":2010,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"date field here records the discovery/publication event (2010), not the population’s existence window — see the pop_denisovan entity date_range for that.","_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_denisovan_genome_before_morphology.json"},{"id":"claim_aksum_missionization","subject_type":"Tradition","subject_id":"trad_aksumite_christianity","statement":"Frumentius, a young Tyrian shipwrecked into Aksumite royal service alongside his companion Aedesius, rose to influence as an administrator (per some accounts during a royal minority), used his position to give Christian merchants freedom of worship and encourage the faith, then traveled to Alexandria where Athanasius consecrated him bishop and sent him back. Rufinus of Aquileia, writing c. 402-403 CE, states he heard this account directly from Aedesius, whom he met at Tyre — one source-remove from an eyewitness, within roughly 60-70 years of the events. Later Ethiopian tradition's honorific \"Abba Selama\" and more elaborate hagiographic material are centuries-later elaboration on this core, not independent corroboration.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"ESTIMATED_COMPOSITION","date":{"earliest":320,"latest":340,"precision":"DECADE"},"zoom_min":"Z4","zoom_max":"Z6","region":["Horn of Africa/Aksum"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Rufinus of Aquileia, continuation of Eusebius's Ecclesiastical History, Books 10-11, c. 402-403 CE.","author":null,"year":null,"venue":null,"contemporary_with_event":false,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_aksum_missionization.json"},{"id":"claim_aksum_state_adoption","subject_type":"Tradition","subject_id":"trad_aksumite_christianity","statement":"A hard external terminus ante quem of 356 CE (Emperor Constantius II's letter to \"Aizanas and Sazanas,\" preserved in Athanasius's Apologia ad Constantium) confirms King Ezana was reigning and Christian by that date. The precise conversion year within the preceding mid-330s-340s CE window remains disputed, not fixed to a single scholarly-agreed year. Ezana's own coinage transitions from disc-and-crescent to an explicit cross, making Aksum one of the earliest states anywhere to place a Christian symbol on its own coinage — genuinely unusual, directly datable evidence of a ruler's own numismatic self-presentation of religious conversion. Whether the numismatic transition was abrupt or included transitional hybrid issues could not be resolved to academic-source confidence in this research pass.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_WRITTEN_ATTESTATION","date":{"earliest":330,"latest":357,"precision":"DECADE"},"zoom_min":"Z4","zoom_max":"Z6","region":["Horn of Africa/Aksum"],"evidence_types":["WRITTEN_PRIMARY","ARCHAEOLOGY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Athanasius, Apologia ad Constantium (preserving Constantius II's letter), c. 356/357 CE.","author":null,"year":null,"venue":null,"contemporary_with_event":true,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_aksum_state_adoption.json"},{"id":"claim_great_zimbabwe_dating","subject_type":"Polity","subject_id":"pty_great_zimbabwe_state","statement":"Chirikure, Pollard, Manyanga, and Bandama, \"A Bayesian Chronology for Great Zimbabwe: Re-threading the Sequence of a Vandalised Monument,\" Antiquity 87 (2013): 1-19, re-analyzes radiocarbon dates against limited surviving stratigraphy (much of the original stratigraphy was destroyed by Richard Nicklin Hall's 1902-4 excavation) plus datable imports, using Bayesian statistical modeling. Dry-stone-wall construction begins c. 1200 CE (later than the older, still-popular \"11th century\" framing, which better fits early settlement rather than stone building specifically), reaching architectural peak in the 14th-15th centuries, with occupation continuing into the 16th and possibly 17th century. Cross-dating evidence: imported Chinese porcelain/celadon, Persian faience, Arabian glass, and Indian glass beads, corroborating the medieval date range via the Sofala/Kilwa Indian Ocean gold-trade network — though a dedicated porcelain-typology publication was not independently verified in this research pass.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EARLIEST_SURVIVING_EVIDENCE","date":{"earliest":1200,"latest":1550,"precision":"CENTURY"},"zoom_min":"Z4","zoom_max":"Z6","region":["Southern Africa"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Chirikure, S., M. Pollard, M. Manyanga, and F. Bandama. \"A Bayesian Chronology for Great Zimbabwe: Re-threading the Sequence of a Vandalised Monument.\" Antiquity 87, 2013: 1-19.","author":"Chirikure et al.","year":2013,"venue":"Antiquity","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_great_zimbabwe_dating.json"},{"id":"claim_hangul_origin_type","subject_type":"WritingSystem","subject_id":"ws_hangul","statement":"Hangul was created under King Sejong the Great (r. 1418-1450), completed December 1443, promulgated 1446 (Hunminjeongeum, a 33-page document, UNESCO Memory of the World register). The Hunminjeongeum Haerye, rediscovered 1940 in Andong, Gyeongsang Province, is a companion commentary directly explaining the featural design logic: basic consonant shapes are stylized diagrams of the articulatory organs producing each sound, systematized through a heaven/earth/human philosophical framework for vowels — an unusually direct primary document of a script's own design intent. Sejong knew of the concept of writing (Chinese characters were already Korea's established administrative/literary script) but designed original, non-derivative letterforms — the calibration case for STIMULUS_DIFFUSION combined with genuine novel featural design (⟨INFERENCE⟩: mapping this documented situation onto Kroeber's \"stimulus diffusion\" category, 1940, is this claim's own inference, not a term any cited scholar applies to Hangul verbatim).","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":1443,"latest":1446,"precision":"YEAR","date_semantics":"EVENT_DATE"},"zoom_min":"Z4","zoom_max":"Z6","region":["East Asia"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"UNESCO Memory of the World, \"Hunminjeongum Manuscript\" register entry.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Kroeber, A.L. \"Stimulus Diffusion.\" American Anthropologist 42(1), 1940.","author":"A.L. Kroeber","year":1940,"venue":"American Anthropologist","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_hangul_origin_type.json"},{"id":"claim_kongo_1491_missionization","subject_type":"Tradition","subject_id":"trad_kongo_christianity","statement":"Nzinga a Nkuwu, ruler of Kongo, was baptized 3 May 1491 by Portuguese missionaries, taking the name João I; his son Nzinga a Mbemba (later Afonso I) and court officials were baptized alongside him. João I abandoned Christianity c. 1494-95, reportedly in significant part because Catholic monogamy requirements conflicted with the polygynous marriage-alliance politics central to Kongo's elective/matrilineal succession system — this specific causal claim is reported across secondary sources but was not traced to one named peer-reviewed primary citation in this research pass.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":1491,"latest":1495,"precision":"YEAR"},"zoom_min":"Z4","zoom_max":"Z6","region":["Central Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"General secondary historiography on the 1491 Kongo royal baptism and João I's apostasy.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Flagged for follow-up verification against Thornton directly or Anne Hilton, The Kingdom of Kongo (Oxford UP, 1985).","_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_kongo_1491_missionization.json"},{"id":"claim_kongo_afonso_state_adoption","subject_type":"Tradition","subject_id":"trad_kongo_christianity","statement":"Afonso I (r. 1509-1542), not João I, durably established Christianity as Kongo's state religion: he declared traditional \"idol\" worship illegal, burned at least one traditional shrine/temple, built churches/schools in the provinces, and used Christian doctrines of primogeniture/divine right to strengthen his own succession claim against rival lineage contenders. His surviving correspondence (John K. Thornton, Afonso I Mvemba a Nzinga, King of Kongo: His Life and Correspondence, Hackett, 2020, trans. Luís Madureira) includes a series beginning 1526 protesting the escalating, increasingly uncontrolled Atlantic slave trade to King João III of Portugal — even while Afonso himself operated a regulated slave trade.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":1509,"latest":1542,"precision":"YEAR"},"zoom_min":"Z4","zoom_max":"Z6","region":["Central Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Thornton, John K. Afonso I Mvemba a Nzinga, King of Kongo: His Life and Correspondence. Hackett Publishing, 2020.","author":"John K. Thornton","year":2020,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"The commonly cited \"24 letters\" figure applies specifically to the 1526+ anti-slave-trade series; the total surviving correspondence collected in Thornton's 2020 volume may be larger — not independently verified against the book's table of contents.","_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_kongo_afonso_state_adoption.json"},{"id":"claim_kongo_syncretism_translation","subject_type":"Tradition","subject_id":"trad_kongo_christianity","statement":"Missionaries and Kongo Christian intellectuals (including Afonso I himself) selected Nzambi a Mpungu as the Kikongo rendering of the Christian God, and nkisi was translated as \"holy\" — folding the Christian sacred into the same linguistic category as the traditional power-object concept rather than presenting it as categorically alien. This translation choice is traceable through the 1624 Kikongo catechism produced under Jesuit Mateus Cardoso (a now-lost 1557 Carmelite catechism preceded it). Cécile Fromont (The Art of Conversion, UNC Press, 2014; \"Under the Sign of the Cross in the Kingdom of Kongo,\" RES: Anthropology and Aesthetics) documents the preexisting Kongo dikenga/yowa cross-shaped cosmogram as a genuine point of visual-cosmological convergence enabling Kongo Christians to read the Christian crucifix through an existing framework, producing elaborate hybrid crucifixes.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"SURVIVING_MANUSCRIPT_DATE","date":{"earliest":1524,"latest":1624,"precision":"CENTURY"},"zoom_min":"Z4","zoom_max":"Z6","region":["Central Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Fromont, Cécile. The Art of Conversion: Christian Visual Culture in the Kingdom of Kongo. University of North Carolina Press, 2014.","author":"Cécile Fromont","year":2014,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"The 1624 Kikongo catechism produced under Jesuit Mateus Cardoso, translated by named Kongo \"best masters of the church.\"","author":null,"year":1624,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_kongo_syncretism_translation.json"},{"id":"claim_antonianism_reform","subject_type":"Tradition","subject_id":"trad_antonianism","statement":"Kimpa Vita (baptized Dona Beatriz), a young Kongolese noblewoman, claimed in 1704 to have died and been reincarnated/possessed by Saint Anthony of Padua, preaching that Jesus, Mary, and the saints were themselves Kongolese/African, and criticizing Italian Capuchin missionaries for excluding Black sainthood. Her movement arose amid civil wars over the Kongo throne following the 1665 Battle of Mbwila; John K. Thornton (The Kongolese Saint Anthony, Cambridge UP, 1998) reads it as substantially a peace movement functioning as \"something of a theocracy,\" aimed at ending the wars and restoring unified sacralized kingship — a REFORM of Kongo Christianity from within, not an import of a new tradition. She was executed by burning in 1706 on orders connected to King Pedro IV, with Capuchin missionary involvement in her heresy condemnation.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":1704,"latest":1706,"precision":"YEAR"},"zoom_min":"Z4","zoom_max":"Z6","region":["Central Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Thornton, John K. The Kongolese Saint Anthony: Dona Beatriz Kimpa Vita and the Antonian Movement, 1684-1706. Cambridge University Press, 1998.","author":"John K. Thornton","year":1998,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"No surviving African-authored primary source exists; the documentary record consists entirely of accounts by hostile Capuchin missionary witnesses (Bernardo da Gallo, Lorenzo da Lucca) — Thornton's methodological contribution is reading these \"against the grain.\"","_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_antonianism_reform.json"},{"id":"claim_mawu_lisa_hwanjile_import","subject_type":"Deity","subject_id":"dty_mawu_lisa","statement":"Hwanjile, the kpojito (\"queen mother\"/reign-mate) of King Tegbesu (r. c.1740-1774), is credited with importing the Mawu-Lisa cult from Aja territory and installing it as head of the Dahomean state pantheon, building it a shrine outside the royal palace and serving as its high priestess. This is treated in the scholarly literature as an act of religious-political legitimation tied to consolidating Tegbesu's contested succession — a datable historical/political act, not static inherited cosmology.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":1740,"latest":1774,"precision":"DECADE"},"zoom_min":"Z4","zoom_max":"Z6","region":["West Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Bay, Edna G. Wives of the Leopard: Gender, Politics, and Culture in the Kingdom of Dahomey. University of Virginia Press, 1998.","author":"Edna G. Bay","year":1998,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"\"Belief, Legitimacy and the Kpojito: An Institutional History of the 'Queen Mother' in Precolonial Dahomey.\" Journal of African History.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Author of the JAH kpojito article not independently confirmed (likely also Bay) — flagged for follow-up.","_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_mawu_lisa_hwanjile_import.json"},{"id":"claim_cherokee_origin_type","subject_type":"WritingSystem","subject_id":"ws_cherokee","statement":"Sequoyah (George Guess/Gist), a monolingual Cherokee speaker who never learned to read or write English, began developing a writing system c. 1809 after observing literate soldiers during the War of 1812/Creek War (including the Battle of Horseshoe Bend). He first attempted an unmanageable logographic (one-symbol-per-word) system, then pivoted to analyzing spoken Cherokee's syllable inventory, completing an 86-character (later 85) syllabary by 1821; his daughter Ayokeh (Ahyokah) demonstrated the system worked for someone who had not helped design it. Formally adopted by the Cherokee National Council in 1825; the bilingual Cherokee Phoenix newspaper launched 1828. His character shapes resemble Latin/Greek/Cyrillic letterforms he had seen but could not read, while sound values are unrelated to those alphabets' actual values — since he had no access to the source letters' phonetic values, only their shapes, this is a clean STIMULUS_DIFFUSION case: concept and some visual stock borrowed, sign-to-sound mapping invented from scratch.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":1821,"latest":1821,"precision":"YEAR","date_semantics":"EVENT_DATE"},"zoom_min":"Z4","zoom_max":"Z6","region":["North America"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"Cushman, Ellen. The Cherokee Syllabary: Writing the People's Perseverance. University of Oklahoma Press, 2011.","author":"Ellen Cushman","year":2011,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Cushman, Ellen. \"The Cherokee Syllabary: A Writing System in Its Own Right.\" Written Communication 28(3), 2011.","author":"Ellen Cushman","year":2011,"venue":"Written Communication","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"The often-repeated ~90% post-syllabary Cherokee literacy figure traces to Ellen Cushman and Theda Perdue (\"The Sequoyah Syllabary and Cultural Revitalization,\" 1994) but could not be independently traced to a period census or contemporaneous quantitative source this session — treat as a widely cited scholarly estimate, not a hard count.","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_cherokee_origin_type.json"},{"id":"claim_vai_origin_type","subject_type":"WritingSystem","subject_id":"ws_vai","statement":"Momolu Duwalu Bukele created the Vai syllabary in Liberia, c. 1832-1834. Missionary-recorded founding accounts describe a dream in which a stranger appeared with \"a book\" and taught him signs he reconstructed on waking with male relatives/friends; near-contemporary transcriptions of this story vary (a Christian missionary's 1834 account vs. Sigismund Koelle's 1849 recording), which scholars read as evidence the \"dream\" is a status-conferring founding narrative rather than a literal account of a mundane, contact-inspired invention process. Tuchscherer and Hair (History in Africa 29, 2002, pp. 427-486) document that a Cherokee man, Austin Curtis, emigrated to Liberia in 1823 and married into a Vai chief's family, raising the possibility that awareness of the Cherokee syllabary reached Bukele's circle — but Vai characters bear no visual resemblance to Cherokee ones, so any such contact would have transmitted only the concept of syllabic writing, not sign forms. Coded STIMULUS_DIFFUSION on this basis (broader Western/coastal-Liberian literacy exposure, possibly compounded by Cherokee-case awareness).","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":1833,"latest":1833,"precision":"YEAR","date_semantics":"EVENT_DATE"},"zoom_min":"Z4","zoom_max":"Z6","region":["Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":"The dream narrative is a recorded community tradition with internally inconsistent transcriptions; scholars treat it as likely a religious/status gloss on a documentable contact-inspired process, not a settled literal account either way.","sources":[{"type":"PRIMARY","citation":"Tuchscherer, Konrad, and P.E.H. Hair. \"Cherokee and West Africa: Examining the Origins of the Vai Script.\" History in Africa 29, 2002: 427-486.","author":"Tuchscherer and Hair","year":2002,"venue":"History in Africa","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Kelly, Piers. \"The Invention, Transmission and Evolution of Writing: Insights from the New Scripts of West Africa.\" In Paths into Script Formation in the Ancient Mediterranean, 2018.","author":"Piers Kelly","year":2018,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_vai_origin_type.json"},{"id":"claim_esu_domain_and_mistranslation","subject_type":"Deity","subject_id":"dty_esu","statement":"Multiple sources converge on Samuel Ajayi Crowther's A Vocabulary of the Yoruba Language (1842/1843) as an early — possibly the first — instance of English-language missionary lexicography rendering Èṣù as \"Satan\"/\"devil.\" This is significant because Crowther was himself Yorùbá (a freed slave who became the first African Anglican bishop), meaning the mistranslation was propagated through native-speaker Christian scholarship under missionary institutional pressure, not purely imposed from outside. Subsequent 19th-20th century dictionaries followed this precedent. In Yorùbá cosmology, Èṣù functions as messenger/intermediary between Olódùmarè and both the other Òrìṣà and humanity, delivering sacrifices/prayers, and as an enforcer of divine law — morally neutral, not evil.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":1843,"latest":1843,"precision":"YEAR"},"zoom_min":"Z4","zoom_max":"Z6","region":["West Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Crowther, Samuel Ajayi. A Vocabulary of the Yoruba Language. London, 1843 (expanded ed. with Owen Vidal, 1852).","author":"Samuel Ajayi Crowther","year":1843,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"This specific citation is repeated across several converging secondary sources (Guardian Nigeria, OkayAfrica, alamojayoruba.com) but none is a peer-reviewed academic citation independently verified page-by-page against the primary 1843/1852 text — flagged as needing a firmer check before treating as fully settled at HIGH confidence.","_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_esu_domain_and_mistranslation.json"},{"id":"claim_great_zimbabwe_colonial_denial","subject_type":"Polity","subject_id":"pty_great_zimbabwe_state","statement":"Karl Mauch (1871), the first European visitor, declared the ruins could not be African work, speculating Phoenician/Israelite/biblical-Ophir origin. Cecil Rhodes and the British South Africa Company funded Richard Nicklin Hall's 1902-4 excavation with an explicit brief to establish non-African origin; Hall destroyed roughly 12 feet of stratified archaeological deposits (which he called \"filth and decadence of the Kaffir occupation\"), permanently damaging the site's stratigraphic record. David Randall-MacIver (1905-6) and especially Gertrude Caton-Thompson (1929, with an all-female excavation team including a young Kathleen Kenyon; published as The Zimbabwe Culture, Oxford, Clarendon Press, 1931) confirmed the correct medieval-date, indigenous-African-construction conclusion — but this triggered roughly three decades of official disinterest because it was politically unwelcome to the white settler community. In 1970 the Rhodesian Front (Ian Smith) government formally enacted censorship rules preventing official publications from stating African construction as settled fact without \"equal platform\" for foreign-origin theories; Peter Garlake, Inspector of Monuments (1964-1970), resigned and left the country in 1970 after parliamentary pressure to accommodate this, returning after 1981 independence. This should be reported explicitly as discredited pseudo-archaeology motivated by and instrumentalized for racist settler-colonial ideology, actively state-enforced as late as 1970 — not as a neutral historiographical dispute.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":1871,"latest":1981,"precision":"CENTURY"},"zoom_min":"Z4","zoom_max":"Z6","region":["Southern Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Caton-Thompson, Gertrude. The Zimbabwe Culture: Ruins and Reactions. Oxford: Clarendon Press, 1931; reissued 1969.","author":"Gertrude Caton-Thompson","year":1931,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"\"Peter Garlake (1934-2011), Great Zimbabwe and the politics of the past in Zimbabwe.\"","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"\"Carl Mauch and Some Karanga Chiefs Around Great Zimbabwe 1871-1872.\" South African Historical Journal 65(3), 2013.","author":null,"year":2013,"venue":"South African Historical Journal","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_great_zimbabwe_colonial_denial.json"},{"id":"claim_bamum_origin_type","subject_type":"WritingSystem","subject_id":"ws_bamum","statement":"King Njoya of the Bamum Kingdom (Cameroon) invented the Bamum script starting 1896, evolving through six documented stages over c. 14 years (1896-1910): from an initial 465-pictogram/10-digit system (\"Lewa\") through intermediate forms to a true syllabary by 1902 onward. Used for a pharmacopoeia, a calendar, legal/administrative records, schools, a library, and a printing press. Suppressed after French colonial administration took over in 1919 (materials destroyed, teaching banned); undergoing a documented revival since 2022 via the Endangered Alphabets Project working with Njoya's great-grandson.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":1896,"latest":1910,"precision":"YEAR","date_semantics":"EVENT_DATE"},"zoom_min":"Z4","zoom_max":"Z6","region":["Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"Endangered Alphabets Project, \"Bamum\" entry.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"africanhistoryextra.com, \"The invention of writing in an African kingdom.\"","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_bamum_origin_type.json"},{"id":"claim_nko_origin_type","subject_type":"WritingSystem","subject_id":"ws_nko","statement":"Solomana Kanté (Souleymane Kanté) created N'Ko in Guinea/Côte d'Ivoire, completed 1949, after experimenting with and rejecting adaptations of Arabic and Latin script for Maninka's tone and vowel system. N'Ko is genuinely alphabetic (19 consonants, 7 vowels, 8 diacritics), written right-to-left and visually resembling Arabic script, but structurally diverges from it with obligatory tone marking — a stimulus-diffusion signature (visual/directional influence from Arabic, phonemic/tonal system built from scratch). The oft-repeated motivating anecdote — that Kanté was responding to a Lebanese journalist (attributed to Kamel Mrowa, founder of the Beirut daily Al-Hayat, 1946) claiming African languages were \"unwritable\" — is well-attested as N'Ko community/institutional history but was not independently confirmed to a source outside that tradition this session; Kanté's biographical background in Arabic and Ajami manuscript scholarship is independently documented regardless of the anecdote's precise accuracy.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":"EVENT_DATE","date":{"earliest":1949,"latest":1949,"precision":"YEAR","date_semantics":"EVENT_DATE"},"zoom_min":"Z4","zoom_max":"Z6","region":["Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"Oyler, Dianne White. \"The N'ko Alphabet as a Vehicle of Indigenist Historiography.\" History in Africa 24, 1997: 239-256.","author":"Dianne White Oyler","year":1997,"venue":"History in Africa","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Donaldson, Coleman. \"The Role of Islam, Ajami Writings, and Educational Reform in Sulemaana Kantè's N'ko.\" African Studies Review 63(3), 2020: 462-486.","author":"Coleman Donaldson","year":2020,"venue":"African Studies Review","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"The specific Mrowa quote/publication is described in accessible sourcing as \"an anecdote popular with N'Ko proponents\" — weaker sourcing than the Sequoyah battlefield account; treat the general motivation as well-attested, the specific attribution as community history not independently corroborated.","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_nko_origin_type.json"},{"id":"claim_agojie_does_not_demonstrate","subject_type":"GenderSystem","subject_id":"gs_fon","statement":"The Agojie/Mino were a real, large (peaking around 6,000 by the 1840s per Alpern, declining to roughly 1,500-3,000 by the 1892-94 Franco-Dahomean Wars), professionally organized, combat-effective female military institution, state-sponsored, with documented origins genuinely disputed among named scholars (the gbeto/elephant-huntress tradition per Alpern vs. a royal-bodyguard-evolution tradition vs. Robin Law's emphasis on chronic manpower shortage against numerically superior neighbors as \"perhaps the most persuasive possibility\"). Robin Law's \"become men\" analysis — trained female warriors were culturally understood to symbolically transform into a male social category, especially at the moment of a first kill — is direct evidence the underlying gender hierarchy was intact, not suspended, by the corps's existence. Their existence does NOT demonstrate general Fon/Dahomean gender equality: the dual-sex court-official system was narrower in scope and may have functioned as royal control of male officials as much as female empowerment (Bay); recruitment sometimes occurred via conscription after women were reported for \"misconduct\" by husbands/fathers, a disciplinary mechanism exercised by male kin; and Agojie were themselves required to be nominally celibate/non-childbearing during service, a severe individual restriction, not evidence of general female autonomy.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["West Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Law, Robin. \"The 'Amazons' of Dahomey.\" Paideuma 39, 1993: 245-260.","author":"Robin Law","year":1993,"venue":"Paideuma","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Alpern, Stanley B. Amazons of Black Sparta: The Women Warriors of Dahomey. New York University Press, 1998; 2nd ed. Hurst, 2011.","author":"Stanley B. Alpern","year":1998,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Bay, Edna G. Wives of the Leopard: Gender, Politics, and Culture in the Kingdom of Dahomey. University of Virginia Press, 1998.","author":"Edna G. Bay","year":1998,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["General Fon/Dahomean gender equality","That ordinary women had comparable status, labor conditions, household authority, or freedom from restriction"],"adversarial_counter":null,"status":"verified","notes":"The Woman King (2022) is documented to substantially sanitize Dahomey's slave-trade economy (Agojie historically functioned largely as instruments of slave-raiding warfare, including against the Mahi, portrayed in the film as rescued victims) and to soften King Ghezo's role in it — do not import the film's framing into this dataset.","_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_agojie_does_not_demonstrate.json"},{"id":"claim_aramaic_descends_phoenician","subject_type":"WritingSystem","subject_id":"ws_aramaic","statement":"Aramaic script derives from Phoenician, c. 8th century BCE — well established and uncontested. Aramaic's downstream branching is broad: Nabataean (a cursive regional variant) leads to Arabic script (from c. 4th century CE); Aramaic square script leads to the modern Hebrew alphabet (replacing the older Paleo-Hebrew/Phoenician-descended script); also ancestral to Syriac and, via Sogdian/Uyghur intermediaries, Mongolian script.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Western Asia"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"General epigraphic literature on Aramaic's Phoenician derivation and downstream branching (Nabataean/Arabic, square-script Hebrew, Syriac, Sogdian/Mongolian).","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_aramaic_descends_phoenician.json"},{"id":"claim_brahmi_aramaic_contested","subject_type":"WritingSystem","subject_id":"ws_brahmi","statement":"The Aramaic-derivation hypothesis for Brahmi dates to Albrecht Weber (1856) and has been the traditionally dominant candidate, tied to Achaemenid Persian administrative use of Aramaic in the Indus Valley from the 6th century BCE onward. However, no scholar has produced an adequate letter-by-letter derivation from Aramaic to Brahmi, and significant structural mismatches remain unexplained (including versus the related, more securely Aramaic-derived Kharoṣṭhī script). Richard Salomon (the standard reference scholar for Indian epigraphy) is engaged in this debate, specifically disputing claims of pre-Aśokan Brahmi inscriptions as \"pseudo-inscriptions\"/graffiti rather than genuine early Brahmi, which bears on the dating evidence relevant to any diffusion argument. A rival indigenous/Indus-script-derivation hypothesis exists but is characterized in current literature as speculative given the total absence of material evidence across the ~1000+ year gap between the Indus script's disappearance and Brahmi's appearance.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["South Asia"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"Weber's (1856) Aramaic-derivation hypothesis lacks a confirmed letter-by-letter derivation; a rival indigenous-origin hypothesis is called speculative by the same literature. Neither is settled.","sources":[{"type":"PRIMARY","citation":"Weber, Albrecht. Original Aramaic-derivation hypothesis for Brahmi, 1856.","author":"Albrecht Weber","year":1856,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Salomon, Richard. Indian Epigraphy. Oxford University Press, 1998.","author":"Richard Salomon","year":1998,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":"Salomon's specific positive position on Aramaic-vs-indigenous origin (as opposed to his separately verified work disputing pre-Aśokan Brahmi dating claims) was not independently confirmed to primary-text level this session — flagged for follow-up."}],"interpretations":[{"position":"Brahmi derives from Aramaic script, transmitted via Achaemenid administrative use in the Indus Valley from the 6th century BCE","holders":[{"name":"Albrecht Weber","work":"Original hypothesis, 1856","year":1856,"camp":"ARAMAIC-DERIVATION SCHOOL"}],"strongest_case":"Documented Achaemenid Persian administrative presence and Aramaic use in the Indus Valley region predating Brahmi's appearance, and Kharoṣṭhī (a neighboring script) IS securely Aramaic-derived, establishing the transmission channel was live.","status":"MAJORITY"},{"position":"Brahmi is an indigenous development, possibly with roots reaching back toward the Indus script tradition","holders":[{"name":"Unnamed proponents of the indigenous-origin hypothesis, per the surveyed literature","camp":"INDIGENOUS-ORIGIN SCHOOL"}],"strongest_case":"No adequate letter-by-letter Aramaic-to-Brahmi derivation has ever been produced, and structural mismatches with Aramaic (including relative to the more securely Aramaic-derived Kharoṣṭhī) remain unexplained.","status":"MINORITY"}],"does_not_demonstrate":["A confirmed, letter-by-letter Aramaic-to-Brahmi derivation"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_brahmi_aramaic_contested.json"},{"id":"claim_cascajal_authenticity_disputed","subject_type":"Text","subject_id":"text_cascajal_block","statement":"The Cascajal Block's status is genuinely disputed. It was recovered out of stratified archaeological context (found in a debris pile by road workers), and its proposed c. 900 BCE date rests on associated pottery/figurine dating, not direct dating of the stone. David Grove (University of Florida) reportedly described it as looking \"like a fake\"; Christopher Pool (University of Kentucky) expressed skepticism in 2010, citing the unusual horizontal sign orientation relative to other Mesoamerican scripts and unusually crisp incision-line weathering. Countervailing material-science analysis (Englehardt et al., Ancient Mesoamerica 31(2), 2020) using polynomial texture mapping, XRF, and SEM concluded the material and manufacture are consistent with genuine Formative-period Olmec production — supporting but not resolving the stratigraphic-context problem.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["North America"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"DISPUTED","scholarly_disagreement":"Named skeptics (Grove, Pool) dispute authenticity/context; Englehardt et al. 2020 material analysis supports genuine manufacture without resolving the out-of-context recovery problem.","sources":[{"type":"PRIMARY","citation":"Rodríguez Martínez, Ma. del Carmen, et al. Report on the Cascajal Block. Science, 2006.","author":null,"year":2006,"venue":"Science","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Skidmore, Joel. \"The Cascajal Block: The Earliest Precolumbian Writing.\" Mesoweb, 2006.","author":"Joel Skidmore","year":2006,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Englehardt, J., I. Insaurralde Caballero, E. Melgar Tísoc, Y. Velázquez Maldonado, C. Guzmán Torres, and R. Bernard. \"Digital Imaging and Archaeometric Analysis of the Cascajal Block: Establishing Context and Authenticity for the Earliest Known Olmec Text.\" Ancient Mesoamerica 31(2), 2020: 189.","author":null,"year":2020,"venue":"Ancient Mesoamerica","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"The block is a genuine Formative-period Olmec artifact bearing a real early writing system","holders":[{"name":"Englehardt, Insaurralde Caballero, Melgar Tísoc, Velázquez Maldonado, Guzmán Torres, and Bernard","work":"Ancient Mesoamerica 31(2), 2020","year":2020,"camp":"MATERIAL-AUTHENTICITY SCHOOL"}],"strongest_case":"Polynomial texture mapping, XRF, and SEM analysis found the stone's material and manufacture consistent with genuine Formative-period production.","status":"CONTESTED"},{"position":"The block's authenticity and/or dating is doubtful given its out-of-context recovery and anomalous features","holders":[{"name":"David Grove","work":"Personal assessment reported in secondary coverage","camp":"SKEPTICAL SCHOOL"},{"name":"Christopher Pool","work":"Personal assessment, 2010","year":2010,"camp":"SKEPTICAL SCHOOL"}],"strongest_case":"Recovered from a debris pile with no stratified context; unusual horizontal sign orientation relative to other Mesoamerican scripts; unusually crisp incision-line weathering.","status":"CONTESTED"}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_cascajal_authenticity_disputed.json"},{"id":"claim_chinese_neolithic_precursors_disputed","subject_type":"WritingSystem","subject_id":"ws_chinese_script","statement":"Neolithic sign-use candidates predating oracle bone script by millennia — Jiahu tortoise-shell/pottery symbols (c. 6600-6200 BCE, 11 identified symbols), Banpo pottery marks, and the Dinggong/Longshan potsherd (discovered 1992, 11-12 signs) — are NOT confirmed antecedents of Chinese writing by mainstream paleography. A 2003 Antiquity report on Jiahu (Li, Harbottle, Zhang, Wang) explicitly interprets the symbols \"not as writing itself, but as features of a lengthy period of sign-use.\" Dinggong's Neolithic dating is itself disputed (Feng Shi 1994 argues for it; other scholars dispute the dating). These candidates remain archaeologically and functionally disconnected from Shang script.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["East Asia"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":"Dinggong's dating and even its authenticity as a genuine Longshan-period inscription is actively disputed among specialists, not merely uncertain by default.","sources":[{"type":"PRIMARY","citation":"Li, X., G. Harbottle, J. Zhang, and C. Wang. \"The earliest writing? Sign use in the seventh millennium BC at Jiahu, Henan Province, China.\" Antiquity 77 (2003).","author":null,"year":2003,"venue":"Antiquity","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Boltz, William G. The Origin and Early Development of the Chinese Writing System. American Oriental Series 78, Eisenbrauns, 1994.","author":"William G. Boltz","year":1994,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["That oracle bone script has no undocumented antecedent development at all — Boltz notes the earliest oracle-bone script is already highly abstract and standardized, implying a real developmental gap not filled by these Neolithic finds"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_chinese_neolithic_precursors_disputed.json"},{"id":"claim_chinese_oracle_bone_dating","subject_type":"Text","subject_id":"text_oracle_bone_inscriptions","statement":"The conventional c. 1250 BCE start date for the Wu Ding-era oracle bone corpus is corroborated by two independent methods: astronomical (Zhang Peiyu's analysis of five lunar-eclipse records in the \"Bin group\" oracle bones places Wu Ding's reign at 1250-1192 BCE) and radiocarbon (inscriptions attributed to Wu Ding dated to 1254-1197 BCE, ±10 years).","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["East Asia"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS","ASTRONOMICAL"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"Keightley, David N. Sources of Shang History: The Oracle-Bone Inscriptions of Bronze Age China. University of California Press, 1978.","author":"David N. Keightley","year":1978,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"\"Radiocarbon Dating of Oracle Bones of Late Shang Period in Ancient China.\" Radiocarbon, Cambridge Core.","author":null,"year":null,"venue":"Radiocarbon","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_chinese_oracle_bone_dating.json"},{"id":"claim_chu_nom_credit_correction","subject_type":"WritingSystem","subject_id":"ws_japanese_kana","statement":"Vietnamese chữ Quốc ngữ (the Latin-based romanization that eventually replaced the Chinese-character-adapting chữ Nôm) is commonly and inaccurately credited solely to Alexandre de Rhodes. The documented history is multi-missionary and collaborative: Francisco de Pina (Portuguese Jesuit, 1585-1625) is credited as first to create a Latinized script for Vietnamese, with an orthography/tone treatise by 1623; Gaspar do Amaral and António Barbosa further developed the system; Alexandre de Rhodes compiled and published the first printed codification (Dictionarium Annamiticum Lusitanum et Latinum, 1651) and explicitly acknowledged Amaral and Barbosa's prior contributions in his own prologue. De Rhodes's role was institutionalizing/publishing/popularizing via print, not solitary invention.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["East Asia"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"De Rhodes, Alexandre. Dictionarium Annamiticum Lusitanum et Latinum. 1651.","author":"Alexandre de Rhodes","year":1651,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Britannica, \"Alexandre de Rhodes\"; Vietnamese Typography, \"History\"; Omniglot, \"Vietnamese Chu Nom script.\"","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["That de Rhodes worked alone (a documented popular error this claim corrects)"],"adversarial_counter":null,"status":"verified","notes":"Filed under ws_japanese_kana (East Asian derivative scripts research batch) since no dedicated chữ Nôm/Quốc ngữ WritingSystem entity was created this batch; chữ Nôm itself (earliest dated inscription 1209 CE, Bảo Ân temple stele) is a documented Chinese-character adaptation, systematized under the Trần dynasty, peak literary use 15th-19th centuries.","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_chu_nom_credit_correction.json"},{"id":"claim_cuneiform_decipherment_status","subject_type":"Text","subject_id":"text_behistun_inscription","statement":"Sumerian cuneiform and Akkadian/Babylonian cuneiform are both DECIPHERED. Decipherment proceeded via Old Persian cuneiform first (Grotefend 1802 partial breakthrough on ~10 of 37 signs; Rask 1826; Burnouf and Lassen 1836; Rawlinson's copying of the trilingual Behistun Inscription 1835-1847, published 1846-1847), then Akkadian/Babylonian, publicly confirmed on 29 May 1857 when the Royal Asiatic Society sent a newly discovered Assyrian text in sealed envelopes to four scholars working independently (Rawlinson, Edward Hincks, Jules Oppert, and William Henry Fox Talbot); their translations converged closely. Sumerian, a language isolate, was recoverable chiefly via bilingual Sumerian-Akkadian lexical lists preserved by later scribes. Despite DECIPHERED status, the sign system is large and highly polyphonic, many tablets are damaged, and Sumerian as a language remains imperfectly understood in places despite the script itself being fully read.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Western Asia"],"evidence_types":["WRITTEN_PRIMARY","INSCRIPTION"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Rawlinson, Henry Creswicke. The Persian Cuneiform Inscription at Behistun, Deciphered and Translated. 1846-1847.","author":"Henry Rawlinson","year":1846,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Account of the 29 May 1857 Royal Asiatic Society blind-translation test of Rawlinson, Hincks, Oppert, and Fox Talbot on a Tiglath-Pileser I prism text.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Exact Rawlinson Behistun publication date(s) split 1846/1847/1849 across sources, likely reflecting multi-part publication — flagged, not fully resolved.","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_cuneiform_decipherment_status.json"},{"id":"claim_cuneiform_origin_type","subject_type":"WritingSystem","subject_id":"ws_cuneiform","statement":"Cuneiform is classified by current scholarship as (probably) INDEPENDENT: the only major early writing tradition, alongside Chinese and Mesoamerican scripts, generally accepted as having no antecedent contact-based model. The positive evidentiary basis is a multi-millennium local \"token-to-tablet\" continuity: small clay counting tokens (attested from the Neolithic, 8th millennium BCE) evolving through sealed clay envelope-bullae into flat impressed/incised tablets, entirely within Mesopotamia, with no comparable intermediate stage found anywhere else prior.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Western Asia"],"evidence_types":["ARCHAEOLOGY","WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"Schmandt-Besserat, Denise. Before Writing, Vol. 1: From Counting to Cuneiform. University of Texas Press, 1992.","author":"Denise Schmandt-Besserat","year":1992,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Nissen, Hans J., Peter Damerow, and Robert K. Englund. Archaic Bookkeeping: Writing and Techniques of Economic Administration in the Ancient Near East. University of Chicago Press, 1993.","author":"Nissen, Damerow, Englund","year":1993,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Cuneiform Digital Library Initiative (CDLI), periods reference, dating proto-cuneiform Uruk IV to c. 3350-3200 BCE.","author":null,"year":null,"venue":"CDLI","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Tokens directly and mechanically became writing via bullae-impression (strong continuity thesis)","holders":[{"name":"Denise Schmandt-Besserat","work":"Before Writing (1992); How Writing Came About (1996)","year":1992,"camp":"ARCHAEOLOGICAL CONTINUITY SCHOOL"}],"strongest_case":"A documented, traceable multi-millennium sequence from Neolithic clay tokens through sealed bullae to flat impressed tablets, entirely within Mesopotamia.","status":"MAJORITY"},{"position":"The token-shape/meaning correlations are overgeneralized across too vast a span of time and geography, and the strong direct-descent mechanism is not established outside a narrow window","holders":[{"name":"Piotr Michalowski","work":"1993 review of Before Writing","year":1993,"camp":"CRITICAL QUALIFICATION SCHOOL"},{"name":"Paul Zimansky","work":"1993 review of Before Writing","year":1993,"camp":"CRITICAL QUALIFICATION SCHOOL"},{"name":"Jean-Jacques Glassner","work":"The Invention of Cuneiform: Writing in Sumer (Johns Hopkins UP, 2003; French orig. 2000)","year":2003,"camp":"CRITICAL QUALIFICATION SCHOOL"}],"strongest_case":"Archaeological context for most tokens is unrecoverable; the chronology (envelopes reliably predating writing) is not established from the Eastern Mediterranean to the Indus; the token system is only one strand feeding into writing, alongside pictography and seal practice.","status":"CONTESTED"}],"does_not_demonstrate":["That every individual token/tablet find independently corroborates the general theory","That the mechanism is settled consensus rather than a broadly-accepted core insight with a contested strong version"],"adversarial_counter":"The broadly accepted claim (\"writing grew out of accounting/counting practice\") should not be conflated with the specific, more contested claim (\"tokens were mechanically converted into writing via bullae-impression\") — this project has previously mis-stated a similarly narrow methodological finding as a settled conclusion (cf. CLAUDE.md's eleph-census pattern) and should not repeat it here.","status":"verified","notes":"origin_type field itself (INDEPENDENT) is HIGH confidence; the Schmandt-Besserat mechanism specifically is DISPUTED — see interpretations[].","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_cuneiform_origin_type.json"},{"id":"claim_cyrillic_descends_greek_not_glagolitic","subject_type":"WritingSystem","subject_id":"ws_cyrillic","statement":"Saints Cyril and Methodius created the Glagolitic script (c. 863 CE) for their Moravian mission — that is the script they actually invented. Cyrillic is a distinct, later script developed by their students, most specifically credited to Saint Clement of Ohrid and the circle at the Preslav Literary School (First Bulgarian Empire, under Tsar Boris I/Simeon I) in the 890s CE, using uncial Greek letterforms as its base (retaining a handful of Glagolitic letters for Slavic sounds absent from Greek), and named \"Cyrillic\" retrospectively in Cyril's honor rather than because he created it. The earliest dated Cyrillic epigraphic evidence is the Krepcha inscription (921 CE) and a Preslav ceramic vessel (931 CE).","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Europe"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"Britannica, \"Cyrillic alphabet\" and \"Preslav Literary School\" entries.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Wikipedia, \"Relationship of Cyrillic and Glagolitic Scripts.\"","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["That Cyril himself invented the Cyrillic script (a documented popular error this claim specifically corrects)"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_cyrillic_descends_greek_not_glagolitic.json"},{"id":"claim_denisovan_ancestry_by_population","subject_type":"Population","subject_id":"pop_homo_sapiens","statement":"Denisovan genetic ancestry is sharply population-specific: highest (approximately 3-6%, with some estimates narrowing this to 2-4%) in Melanesians, Papua New Guineans, and Aboriginal Australians (and, per Reich et al. 2011, also detected in Near Oceanians, Polynesians, Fijians, eastern Indonesians, and the Mamanwa of the Philippines, but explicitly not in the Jehai of Malaysia or the Onge of the Andaman Islands despite superficial phenotypic similarity); much lower (~0.1-0.2%) in mainland East Asian populations; and intermediate (~0.3-0.6%) in parts of South Asia. Native American populations carry a Denisovan signal via their East Asian ancestry, at roughly East Asian levels.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z1","zoom_max":"Z2","region":["Southeast Asia","East Asia","South Asia"],"evidence_types":["ANCIENT_DNA","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Reich, D. et al. \"Genetic history of an archaic hominin group from Denisova Cave in Siberia.\" Nature 468: 1053-1060.","author":"Reich et al.","year":2010,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Reich, D. et al. \"Denisova Admixture and the First Modern Human Dispersals into Southeast Asia and Oceania.\" American Journal of Human Genetics 89(4): 516-528.","author":"Reich et al.","year":2011,"venue":"American Journal of Human Genetics","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Vernot, B. et al. \"Excavating Neandertal and Denisovan DNA from the genomes of Melanesian individuals.\" Science 352(6282): 235-239.","author":"Vernot et al.","year":2016,"venue":"Science","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Sankararaman, S. et al. Denisovan ancestry in South Asian populations. Current Biology 26(9): 1241-1247.","author":"Sankararaman et al.","year":2016,"venue":"Current Biology","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["that populations sharing an older \"Negrito\" phenotypic classification share Denisovan ancestry as a group — the Jehai and Onge specifically do not show the elevated signal seen in Papuan/Melanesian/Aboriginal Australian populations"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_denisovan_ancestry_by_population.json"},{"id":"claim_egyptian_cuneiform_priority_uncertain","subject_type":"WritingSystem","subject_id":"ws_egyptian_hieroglyphs","statement":"Whether Egyptian hieroglyphs or Mesopotamian proto-cuneiform is earlier is genuinely unresolved, contrary to older popular sources that default to cuneiform priority. Tomb U-j at Abydos (excavated by Günter Dreyer, discovered 1988), containing ~150+ inscribed bone/ivory labels, dates to c. 3320-3150 BCE — overlapping substantially with proto-cuneiform Uruk IV (c. 3350-3200 BCE per CDLI) within each side's own dating uncertainty. The two systems emerged within the same roughly 200-year window in the late 4th millennium BCE; priority cannot currently be established with confidence.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Africa","Western Asia"],"evidence_types":["ARCHAEOLOGY"],"confidence":"UNKNOWN","scholarly_disagreement":"The comparative-earliness question between Egypt and Mesopotamia is live and unresolved; treat as UNCERTAIN, not resolvable to a single answer from current evidence.","sources":[{"type":"PRIMARY","citation":"Dreyer, Günter. Excavations at Abydos, Tomb U-j, 1988 and subsequent seasons (German Archaeological Institute, Cairo).","author":"Günter Dreyer","year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Cuneiform Digital Library Initiative (CDLI), periods reference.","author":null,"year":null,"venue":"CDLI","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["That cuneiform was definitively first (a common older popular-source framing not supported by the current dating overlap)"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_egyptian_cuneiform_priority_uncertain.json"},{"id":"claim_egyptian_decipherment_status","subject_type":"Text","subject_id":"text_rosetta_stone","statement":"Egyptian hieroglyphs are DECIPHERED. The Rosetta Stone was discovered 1799; Thomas Young published a partial decipherment (Encyclopaedia Britannica supplement, 1819) correctly intuiting that cartouches enclosed royal names and proposing phonetic values for 13 signs, but limited to foreign (Ptolemy/Cleopatra) names and never generalized. Jean-François Champollion's 1822 Lettre à M. Dacier was the decisive breakthrough: he recognized the phonetic principle was NOT limited to foreign names but applied generally to native Egyptian words, meaning hieroglyphic writing was fundamentally a mixed phonetic-and-ideographic system throughout — the distinction that separates \"Champollion alone solved it\" (an oversimplification) from \"Young essentially solved it first\" (also not accurate); modern historiography credits Champollion with the decisive, generalizing breakthrough while acknowledging Young's real contributory role. Actual pronunciation of Egyptian remains substantially a modern scholarly reconstruction, since hieroglyphic writing omits vowels in most cases — a genuine limitation distinct from the script/grammar being unread.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Africa"],"evidence_types":["WRITTEN_PRIMARY","INSCRIPTION"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Champollion, Jean-François. Lettre à M. Dacier relative à l'alphabet des hiéroglyphes phonétiques. 1822.","author":"Jean-François Champollion","year":1822,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Young, Thomas. Partial hieroglyphic decipherment, Encyclopaedia Britannica supplement, 1819.","author":"Thomas Young","year":1819,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Faulkner, Raymond O. A Concise Dictionary of Middle Egyptian. Griffith Institute, Oxford, 1962.","author":"Raymond O. Faulkner","year":1962,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_egyptian_decipherment_status.json"},{"id":"claim_egyptian_origin_type","subject_type":"WritingSystem","subject_id":"ws_egyptian_hieroglyphs","statement":"Mainstream current Egyptology classifies Egyptian hieroglyphic writing as INDEPENDENT: \"the earliest solid evidence of Egyptian writing differs in structure and style from the Mesopotamian and must therefore have developed independently.\" A stimulus-diffusion minority position (general awareness that writing was possible reaching Egypt via contact, not sign-borrowing) rests on real evidence of Egypt-Mesopotamia contact in the same period (Mesopotamian-style cylinder seals appear in Egyptian tombs from Naqada IIb-c, c. 3500-3300 BCE), but no serious current scholar argues hieroglyphs directly copied/modified cuneiform signs — the sign systems are structurally and visually too dissimilar for ADAPTATION.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Africa"],"evidence_types":["ARCHAEOLOGY","WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"INDEPENDENT (mainstream) vs. STIMULUS_DIFFUSION (documented minority position) — not INDEPENDENT vs. ADAPTATION, which is excluded by both camps.","sources":[{"type":"SECONDARY","citation":"Baines, John. \"The Origin of Writing in Relation to the Emergence of the Egyptian State\"; Visual and Written Culture in Ancient Egypt. Oxford University Press, 2007.","author":"John Baines","year":2007,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Regulski, Ilona. A Palaeographic Study of Early Writing in Egypt. Peeters, 2010.","author":"Ilona Regulski","year":2010,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Goldwasser, Orly. \"Cuneiform and Hieroglyphs in the Bronze Age: Script Contact and the Creation of New Scripts.\" In Pharaoh's Land and Beyond: Ancient Egypt and Its Neighbors, eds. Pearce, Creasman, Wilkinson. Oxford University Press, 2017.","author":"Orly Goldwasser","year":2017,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Independent indigenous development, situated within state-formation/elite display practices","holders":[{"name":"John Baines","work":"Visual and Written Culture in Ancient Egypt","year":2007,"camp":"INDEPENDENT-DEVELOPMENT SCHOOL"},{"name":"Ilona Regulski","work":"A Palaeographic Study of Early Writing in Egypt","year":2010,"camp":"INDEPENDENT-DEVELOPMENT SCHOOL"}],"strongest_case":"Regulski: proposed Sumerian/Elamite pictogram parallels to Predynastic Egyptian seals \"cannot be proved\" to show a proper writing system existed at that point comparable to the U-j labels — the seal-contact evidence establishes technology transfer, not sign-system transmission.","status":"MAJORITY"},{"position":"General stimulus diffusion — awareness that writing was possible transmitted via documented Mesopotamian contact (cylinder seals) — without sign-borrowing","holders":[{"name":"Orly Goldwasser","work":"\"Cuneiform and Hieroglyphs in the Bronze Age\" (2017)","year":2017,"camp":"SCRIPT-CONTACT SCHOOL"}],"strongest_case":"Documented Mesopotamian cylinder-seal imports in Egyptian tombs from Naqada IIb-c (c. 3500-3300 BCE), with a distinctively Egyptian glyptic tradition emerging by Naqada IId (c. 3300 BCE) on a Middle Uruk technological base, establishes real, dated contact in the same window writing emerges.","status":"MINORITY"}],"does_not_demonstrate":["That Egyptian hieroglyphic signs were adapted from cuneiform signs (ADAPTATION is excluded by all named scholars)"],"adversarial_counter":null,"status":"verified","notes":"An older, discredited early-20th-century \"Dynastic Race Theory\" strand (Flinders Petrie and others) entangled Mesopotamia-priority arguments with racialized claims about a foreign \"dynastic race\" bringing civilization to Egypt; this has lost mainstream support and should not be conflated with the sober, evidence-based Baines/Regulski/Goldwasser debate that remains live today.","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_egyptian_origin_type.json"},{"id":"claim_epas1_tibetan_adaptation","subject_type":"Population","subject_id":"pop_homo_sapiens","statement":"A high-altitude-adaptation gene variant (EPAS1) found at approximately 78-87% frequency in sampled Tibetan populations, and rare or absent in Han Chinese and other reference populations, more closely matches the Denisovan genome than any modern reference population and is understood as a case of adaptive introgression from Denisovans, later confirmed and refined by follow-up work. This locus-specific high frequency (a result of strong positive selection at this one gene) is distinct from Tibetans’ genome-wide Denisovan ancestry, which sits near ordinary East Asian levels (~0.1-0.2%) — the two figures should not be conflated.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z1","zoom_max":"Z2","region":["East Asia"],"evidence_types":["ANCIENT_DNA","SCIENTIFIC_ANALYSIS"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Huerta-Sánchez, E. et al. \"Altitude adaptation in Tibetans caused by introgression of Denisovan-like DNA.\" Nature 512: 194-197.","author":"Huerta-Sánchez et al.","year":2014,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Zhang, X. et al. \"The history and evolution of the Denisovan-EPAS1 haplotype in Tibetans.\" PNAS 118(22).","author":"Zhang et al.","year":2021,"venue":"PNAS","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"One of the best-replicated cases of adaptive archaic introgression in the literature; cited essentially without serious challenge per the research pass.","_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_epas1_tibetan_adaptation.json"},{"id":"claim_epi_olmec_decipherment_disputed","subject_type":"Text","subject_id":"text_la_mojarra_stela_1","statement":"Justeson, John S., and Terrence Kaufman (\"A Decipherment of Epi-Olmec Hieroglyphic Writing,\" Science 259(5102), 1993, pp. 1703-1711) claimed a decipherment of La Mojarra Stela 1 identifying the underlying language as pre-proto-Zoquean. Houston, Stephen D., and Michael D. Coe (\"Has Isthmian Writing Been Deciphered?\" Mexicon 25, 2003, pp. 151-161) argue Justeson and Kaufman imposed Mayan grammatical/spelling assumptions onto Epi-Olmec signs, and that the system failed an independent test when applied to a Teotihuacan-style Isthmian-script mask. Andrew Robinson's Lost Languages (2008 ed.) summarizes the field's state as \"decidedly unproven.\" Justeson and Kaufman have continued defending and refining the decipherment — this remains an active, unresolved two-camp dispute, not a settled decipherment.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["North America"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"Justeson and Kaufman [DECIPHERMENT-CLAIM SCHOOL] maintain the pre-proto-Zoquean reading; Houston and Coe [SKEPTICAL SCHOOL] argue the method imposed Mayan assumptions and failed an independent test.","sources":[{"type":"PRIMARY","citation":"Justeson, John S., and Terrence Kaufman. \"A Decipherment of Epi-Olmec Hieroglyphic Writing.\" Science 259(5102), 1993: 1703-1711.","author":"Justeson and Kaufman","year":1993,"venue":"Science","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Houston, Stephen D., and Michael D. Coe. \"Has Isthmian Writing Been Deciphered?\" Mexicon 25, 2003: 151-161.","author":"Houston and Coe","year":2003,"venue":"Mexicon","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Robinson, Andrew. Lost Languages: The Enigma of the World's Undeciphered Scripts. Thames & Hudson, 2nd ed., 2009.","author":"Andrew Robinson","year":2009,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Epi-Olmec script has been deciphered; underlying language is pre-proto-Zoquean","holders":[{"name":"John S. Justeson","camp":"DECIPHERMENT-CLAIM SCHOOL"},{"name":"Terrence Kaufman","camp":"DECIPHERMENT-CLAIM SCHOOL"}],"strongest_case":"A internally consistent reading of La Mojarra Stela 1 and the Tuxtla Statuette against a reconstructed pre-proto-Zoquean grammar, defended and refined against later challenges.","status":"CONTESTED"},{"position":"The claimed decipherment is unproven; the method imposed external (Mayan) grammatical assumptions and failed independent testing","holders":[{"name":"Stephen D. Houston","camp":"SKEPTICAL SCHOOL"},{"name":"Michael D. Coe","camp":"SKEPTICAL SCHOOL"}],"strongest_case":"Applying the Justeson-Kaufman system to an independent Isthmian-script object (a Teotihuacan-style mask) did not produce a coherent parse.","status":"CONTESTED"}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_epi_olmec_decipherment_disputed.json"},{"id":"claim_erectus_ergaster_dispute","subject_type":"Population","subject_id":"pop_homo_erectus","statement":"Whether African early Homo erectus-attributed material should be classified as a separate species, Homo ergaster, distinct from Asian Homo erectus sensu stricto, remains a live and unresolved taxonomic debate, though the field appears to be trending toward treating both as one polytypic species.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z1","zoom_max":"Z2","region":["Africa","East Asia","Southeast Asia"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"DISPUTED","scholarly_disagreement":"Whether cranial/facial differences between African and Asian erectus-attributed material (sagittal keels, cranial vault thickness, robusticity) represent species-level distinction or normal intraspecific geographic variation.","sources":[{"type":"PRIMARY","citation":"Groves, C. & Mazák, V. Original erection of Homo ergaster, using KNM-ER 992 as type specimen.","author":"Groves, C. & Mazák, V.","year":1975,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Wood, B. & Collard, M. \"The Changing Face of Genus Homo.\" Evolutionary Anthropology 8(6): 195-207.","author":"Wood & Collard","year":1999,"venue":"Evolutionary Anthropology","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Antón, S.C. \"Natural history of Homo erectus.\" American Journal of Physical Anthropology 122(S37): 126-170.","author":"Antón, S.C.","year":2003,"venue":"American Journal of Physical Anthropology","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"African material warrants separate species status as Homo ergaster","holders":[{"name":"Colin Groves & Vratislav Mazák","work":"Original 1975 naming, using KNM-ER 992 as type","year":1975,"camp":"[PALEOANTHROPOLOGY — SPLITTING]"},{"name":"Bernard Wood & Mark Collard","work":"Evolutionary Anthropology 8(6):195-207","year":1999,"camp":"[PALEOANTHROPOLOGY — SPLITTING, PHYLOGENETIC METHOD]"}],"status":"CONTESTED","strongest_case":"Phylogenetic/functional analysis finds African and Asian samples form distinguishable clades under cladistic methods."},{"position":"A single, polytypic Homo erectus sensu lato spanning Africa and Asia is preferable","holders":[{"name":"Susan Antón","work":"American Journal of Physical Anthropology 122(S37):126-170 and later syntheses","year":2003,"camp":"[PALEOANTHROPOLOGY — LUMPING]"}],"status":"MAJORITY","strongest_case":"No consistent, non-overlapping character suite cleanly separates the African and Asian samples; variation falls within normal range for a geographically dispersed hominin."}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Reported trend is toward the lumping position gaining ground, but Homo ergaster remains in active use in the literature, particularly for KNM-ER 992-type and Dmanisi-adjacent material.","_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_erectus_ergaster_dispute.json"},{"id":"claim_greek_descends_phoenician","subject_type":"WritingSystem","subject_id":"ws_greek","statement":"The Greek alphabet derives from Phoenician, c. 800-700 BCE, with a genuine structural innovation: the Greeks repurposed several Phoenician consonantal signs representing sounds absent from Greek (glottal/pharyngeal consonants — aleph, he, yod, ayin) as dedicated vowel letters (alpha, epsilon, iota, omicron), producing the first script with systematic vowel notation, distinct from Semitic matres lectionis (partial/optional vowel indication). Named authorities: Roger D. Woodard (grapheme-adaptation detail) and Barry B. Powell (argues the adaptation was purpose-driven, tied to recording Homeric epic). A live epigraphic debate exists over exactly how early/where transmission occurred, but the ~800 BCE date and the vowel-innovation mechanism itself are not contested.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Europe","Western Asia"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"Woodard, Roger D. Body of work on Phoenician-to-Greek grapheme adaptation.","author":"Roger D. Woodard","year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Powell, Barry B. Body of work arguing Greek alphabetic adaptation was purpose-driven for recording epic verse.","author":"Barry B. Powell","year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_greek_descends_phoenician.json"},{"id":"claim_habilis_species_dispute","subject_type":"Population","subject_id":"pop_homo_habilis","statement":"Whether \"Homo habilis\" represents one coherent species or should be split into Homo habilis sensu stricto and a separate species Homo rudolfensis remains an open, actively contested question in current paleoanthropology, not settled by consensus.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z1","zoom_max":"Z2","region":["Africa"],"evidence_types":["ARCHAEOLOGY","SCIENTIFIC_ANALYSIS"],"confidence":"DISPUTED","scholarly_disagreement":"Whether early-Homo variability in East Africa (OH 7, OH 13, KNM-ER 1470, KNM-ER 1813, etc.) represents one variable species or at least two co-existing species.","sources":[{"type":"PRIMARY","citation":"Wood, B. Koobi Fora Research Project monograph proposing the habilis/rudolfensis split.","author":"Wood, B.","year":1991,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Spoor, F., Gunz, P., Neubauer, S., et al. \"Reconstructed Homo habilis type OH 7 suggests deep-rooted species diversity in early Homo.\" Nature 519: 83-86.","author":"Spoor et al.","year":2015,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Early Homo material should be split into H. habilis sensu stricto and H. rudolfensis","holders":[{"name":"Bernard Wood","work":"Koobi Fora Research Project monograph","year":1991,"camp":"[PALEOANTHROPOLOGY — SPLITTING]"},{"name":"Fred Spoor et al.","work":"Nature 519:83-86 (CT reconstruction of OH 7)","year":2015,"camp":"[PALEOANTHROPOLOGY — SPLITTING]"}],"status":"CONTESTED","strongest_case":"Digital reconstruction of the crushed OH 7 mandible shows a long, narrow, primitive dental arcade distinct from other habilis-attributed material (e.g. OH 13, KNM-ER 1813), supporting real morphological diversity within \"early Homo.\""},{"position":"The traditional single, variable Homo habilis taxon remains defensible","holders":[{"name":"Traditional Leakey/Tobias/Napier-descended position, surveyed without full resolution by Susan Antón","work":"\"Early Homo: Who, When, and Where,\" Current Anthropology (2003, 2012 pieces)","year":2012,"camp":"[PALEOANTHROPOLOGY — LUMPING]"}],"status":"CONTESTED","strongest_case":"Variation among the attributed specimens falls within a plausible range for a single geographically and temporally dispersed species, given known intraspecific variability in other hominins."}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_habilis_species_dispute.json"},{"id":"claim_hangul_phagspa_minority","subject_type":"WritingSystem","subject_id":"ws_hangul","statement":"Gari Ledyard (Columbia University, PhD thesis 1966, revised 1998, additional paper 1997), following an earlier 1820 suggestion by Jean-Pierre Abel-Rémusat, proposed that 5-6 basic Hangul consonant shapes were adapted from the Mongol 'Phags-pa script (itself derived from Tibetan, created under Kublai Khan), transmitted via Korean exposure during the Yuan dynasty's suzerainty over Goryeo (1270-1356). This hypothesis is explicitly characterized in the literature as \"less popular than the hypothesis that Hangul was largely an original invention\" — a minority view. Even Ledyard's own account limits any Phagspa influence to a small subset of letter shapes and explicitly maintains that Hangul's innovative featural phonetic principle was an original Korean achievement.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["East Asia"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"Ledyard's 'Phags-pa-influence hypothesis (minority) vs. the mainstream original-invention position — both acknowledge the featural phonetic principle itself as an original Korean achievement regardless.","sources":[{"type":"PRIMARY","citation":"Ledyard, Gari K. PhD thesis (Columbia University, 1966, revised 1998) and 1997 paper on the 'Phags-pa/Hangul hypothesis.","author":"Gari Ledyard","year":1998,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Hangul is largely an original invention, with the featural phonetic principle as a genuine Korean innovation","holders":[{"name":"Mainstream Korean linguistics / the Haerye's own account","camp":"ORIGINAL-INVENTION SCHOOL"}],"strongest_case":"The Hunminjeongeum Haerye itself, a contemporary primary document, credits Sejong and the Hall of Worthies scholars with the design.","status":"MAJORITY"},{"position":"5-6 basic consonant shapes were adapted from the Mongol 'Phags-pa script","holders":[{"name":"Gari Ledyard","work":"PhD thesis, 1966/1998","year":1998,"camp":"PHAGSPA-INFLUENCE SCHOOL"}],"strongest_case":"Documented Korean court exposure to 'Phags-pa via the Yuan dynasty's suzerainty over Goryeo (1270-1356), and specific shape correspondences Ledyard identifies for a handful of letters.","status":"MINORITY"}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_hangul_phagspa_minority.json"},{"id":"claim_ifa_oyo_patronage","subject_type":"Polity","subject_id":"pty_oyo_empire","statement":"Ṣàngó's historicization as an early Aláàfin (king) of Òyó is embedded in Òyó's own dynastic oral-historical record, as reconstructed by Samuel Johnson (The History of the Yorubas, completed 1897, published 1921) and treated as serious material by Sàngó in Africa and the African Diaspora (eds. Tishken, Falola, Akinyemi; Indiana UP, 2009). This is a real, sourced link between Òyó's political history and the Ifá/Òrìṣà religious system, though active royal \"patronage\" in the sense of state-funded temple/priesthood infrastructure for Ṣàngó specifically was not traced to a named-scholar mechanism claim distinct from the king-list/historicization point itself.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["West Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Johnson, Samuel. The History of the Yorubas. Ed. Obadiah Johnson, 1921 (completed 1897).","author":"Samuel Johnson","year":1921,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Tishken, Joel E., Toyin Falola, and Akintunde Akinyemi, eds. Sàngó in Africa and the African Diaspora. Indiana University Press, 2009.","author":null,"year":2009,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_ifa_oyo_patronage.json"},{"id":"claim_independent_invention_count_hedged","subject_type":"WritingSystem","subject_id":"ws_cuneiform","statement":"John DeFrancis (The Chinese Language: Fact and Fantasy, University of Hawaii Press, 1984) states: \"the idea of using a pictograph in the new function of representing sound may have occurred only three times: once in Mesopotamia, perhaps by the Sumerians, once in China, apparently by the Chinese themselves, and once in Central America, by the Mayas\" — a three-way minimal count excluding Egypt as independent. The current mainstream range is four pristine/independent inventions (Sumer, Egypt, China, Mesoamerica), with Egypt's independence itself contested (see claim_egyptian_origin_type) — which would drop the count back to three if Egypt is read as stimulus-diffused. Genuinely live additional candidates that could extend the range further: the Indus script (contested whether it is writing at all — claim_indus_writing_status_disputed) and rongorongo (contested pre/post-contact dating — claim_rongorongo_dating_disputed, strengthened somewhat by 2024 radiocarbon evidence). Recommended hedged figure: 3 to 5, depending on how these contested cases are counted, not a single point figure.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z1","zoom_max":"Z5","region":[],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"DeFrancis's minimal 3-way count (Sumer/China/Maya) vs. the broader modern 4-way count (adding Egypt) vs. an extended 5-way range if Indus and/or rongorongo are eventually confirmed as independent writing — genuinely unresolved, hedge rather than pick one number.","sources":[{"type":"SECONDARY","citation":"DeFrancis, John. The Chinese Language: Fact and Fantasy. University of Hawaii Press, 1984.","author":"John DeFrancis","year":1984,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Independent invention of writing occurred a minimal three times: Mesopotamia, China, Mesoamerica (Maya) — Egypt excluded as independent","holders":[{"name":"John DeFrancis","work":"The Chinese Language: Fact and Fantasy","year":1984,"camp":"MINIMAL-COUNT SCHOOL"}],"strongest_case":"DeFrancis's own stated reasoning for excluding Egypt from the independent count as of his 1984 writing.","status":"MINORITY"},{"position":"The mainstream modern count is four pristine/independent inventions (Sumer, Egypt, China, Mesoamerica), giving Egypt the benefit of the doubt on independence","holders":[{"name":"General comparative writing-origins literature surveyed this session","camp":"BROADER-COUNT SCHOOL"}],"strongest_case":"No confirmed sign-borrowing (ADAPTATION) links Egyptian hieroglyphs to cuneiform even under the stimulus-diffusion minority reading — see claim_egyptian_origin_type.","status":"MAJORITY"}],"does_not_demonstrate":["A single settled count of independent writing inventions"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_independent_invention_count_hedged.json"},{"id":"claim_indus_writing_status_disputed","subject_type":"WritingSystem","subject_id":"ws_indus","statement":"Whether the ~400-sign Indus corpus constitutes writing at all is a live, unresolved dispute. Steve Farmer, Richard Sproat, and Michael Witzel (\"The Collapse of the Indus-Script Thesis: The Myth of a Literate Harappan Civilization,\" Electronic Journal of Vedic Studies 11(2), 2004, pp. 19-57) argue inscription brevity, non-increasing sign combinatorics over 600+ years of use, and statistical properties inconsistent with known linguistic scripts point to a non-linguistic system of religious/political/clan emblems, closer to heraldry than writing. Asko Parpola (Deciphering the Indus Script, Cambridge University Press, 1994) and Rajesh P.N. Rao et al. (\"Entropic Evidence for Linguistic Structure in the Indus Script,\" Science 324(5931), 2009: 1165) argue the script's conditional-entropy pattern statistically resembles known linguistic sequences rather than non-linguistic sign systems; Sproat disputed the strength of the entropy argument alone, and Rao et al. clarified they never claimed entropy similarity alone proves linguistic status. The exchange is genuinely unresolved — cite both sides, not one as winning. Parpola's Dravidian-family hypothesis for the underlying language (if any) is the most published proposal but lacks consensus; a politically-motivated January 2025 Tamil Nadu state decipherment prize tied to a Dravidian-identity claim is not peer-reviewed evidence and should not be treated as resolving the question.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["South Asia"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"Farmer/Sproat/Witzel [NOT-WRITING SCHOOL] vs. Parpola / Rao et al. [PROBABLY-WRITING SCHOOL] — genuinely unresolved as of the most current literature reviewed.","sources":[{"type":"PRIMARY","citation":"Farmer, Steve, Richard Sproat, and Michael Witzel. \"The Collapse of the Indus-Script Thesis: The Myth of a Literate Harappan Civilization.\" Electronic Journal of Vedic Studies 11(2), 2004: 19-57.","author":"Farmer, Sproat, Witzel","year":2004,"venue":"Electronic Journal of Vedic Studies","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Parpola, Asko. Deciphering the Indus Script. Cambridge University Press, 1994.","author":"Asko Parpola","year":1994,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Rao, Rajesh P.N., Nisha Yadav, Mayank N. Vahia, Hrishikesh Joglekar, R. Adhikari, and Iravatham Mahadevan. \"Entropic Evidence for Linguistic Structure in the Indus Script.\" Science 324(5931), 2009: 1165. DOI 10.1126/science.1170391.","author":"Rao et al.","year":2009,"venue":"Science","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"The Indus corpus is not writing — a non-linguistic heraldic/emblematic sign system","holders":[{"name":"Steve Farmer","camp":"NOT-WRITING SCHOOL"},{"name":"Richard Sproat","camp":"NOT-WRITING SCHOOL"},{"name":"Michael Witzel","camp":"NOT-WRITING SCHOOL"}],"strongest_case":"Inscription brevity, non-increasing sign combinatorics over 600+ years, and statistical properties inconsistent with known linguistic scripts.","status":"CONTESTED"},{"position":"The Indus corpus is probably writing, encoding an unidentified (possibly Dravidian) language","holders":[{"name":"Asko Parpola","camp":"PROBABLY-WRITING SCHOOL"},{"name":"Rajesh P.N. Rao","camp":"PROBABLY-WRITING SCHOOL"}],"strongest_case":"Conditional-entropy statistical patterns resembling known linguistic sequences (Rao et al. 2009, Science).","status":"CONTESTED"}],"does_not_demonstrate":["That the January 2025 Tamil Nadu decipherment-prize announcement constitutes new peer-reviewed evidence resolving the underlying-language question"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_indus_writing_status_disputed.json"},{"id":"claim_iyanifa_controversy","subject_type":"Tradition","subject_id":"trad_ifa_orisa","statement":"The Ifá priesthood (babaláwo) is historically male-dominated/male-exclusive in most documented lineages. Whether women can legitimately be initiated as Ifá priests (Ìyánífá, \"Mother of Secrets\") is a genuinely live, contested question — not a single unified \"traditional\" position. The controversy sharpened publicly at a 2006 global Ifá meeting in Venezuela, where Cuban babaláwos told a female Ifá initiate \"there is no such thing as a woman Ifá priest,\" while Nigerian babaláwo present argued for women's acceptability. This is explicitly a Nigeria-vs-Cuban-lineage disagreement.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["West Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"Whether female Ifá initiation (Ìyánífá) is legitimate — Cuban Lucumí and some Nigerian lineages reject it grounded in lineage tradition and specific Odù readings; other Nigerian lineages and the Ìyánífá/Ìyáláwo movement initiate women and treat this as legitimate/traditional.","sources":[{"type":"SECONDARY","citation":"\"Mamalawo? The Controversy Over Women Practicing Ifa Divination.\" Utambuzi: Journal for the Study of the Religions of Africa and its Diaspora, University of Johannesburg journals platform.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":"Title and venue located (journals.uj.ac.za/index.php/ujsrad/article/view/3406); author name and full argument could not be fetched in this research pass due to network egress restrictions — flagged for follow-up."}],"interpretations":[{"position":"Female Ifá initiation is illegitimate; Ifá priesthood is reserved for men per lineage tradition and specific Odù readings around ritual restrictions tied to the Òrìṣà Odù","holders":[{"name":"Orthodox Cuban Lucumí lineages and some Nigerian lineages, per the 2006 Venezuela meeting account","camp":"EXCLUSIONARY LINEAGE SCHOOL"}],"strongest_case":"Grounded in specific, named lineage-transmitted readings of the Odù corpus.","status":"CONTESTED"},{"position":"Female Ifá initiation (Ìyánífá) is legitimate and traditional","holders":[{"name":"Nigerian lineages participating in the Ìyánífá/Ìyáláwo movement, per the 2006 Venezuela meeting account","camp":"INCLUSIVE LINEAGE SCHOOL"}],"strongest_case":"Nigerian babaláwo present at the 2006 meeting argued directly for this position against the Cuban lineage rejection.","status":"CONTESTED"}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_iyanifa_controversy.json"},{"id":"claim_kaggen_domain","subject_type":"Deity","subject_id":"dty_kaggen","statement":"/Kaggen (the Mantis) is the central trickster-creator figure in /Xam narrative as recorded in the Bleek-Lloyd archive: shapeshifting (mantis, eland, snake, louse, hare), morally ambiguous rather than purely benevolent, central to the eland-creation narrative — he made the first eland from a piece of shoe leather nurtured with honey, and wept when it was killed by his in-laws, his released tears/gall creating the first darkness.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["Southern Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Bleek, Wilhelm, and Lucy Lloyd. Specimens of Bushman Folklore. 1911.","author":null,"year":1911,"venue":null,"contemporary_with_event":true,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_kaggen_domain.json"},{"id":"claim_kana_descends_chinese","subject_type":"WritingSystem","subject_id":"ws_japanese_kana","statement":"Hiragana and katakana both derive from man'yōgana (Chinese characters used phonetically for Japanese sounds, traceable to the 5th century CE); hiragana emerged as cursive simplification of whole man'yōgana kanji, katakana by taking fragments/components of kanji, both taking recognizable shape in the 9th-century Heian period. The popular attribution of hiragana's invention to the monk Kūkai (774-835 CE) is a legend, not documented history: no signed document supports it, and modern scholarship has similarly revised the traditional Kūkai attribution for the Iroha poem to a later Heian-period date. The documented picture instead shows a gradual, collective, multi-decade development with no single named inventor.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["East Asia"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"General secondary/encyclopedic sourcing on man'yōgana-to-kana development and the Kūkai legend; not independently cross-checked against a primary Japanese-linguistics monograph this session.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":"Recommend checking Christopher Seeley, A History of Writing in Japan (Brill, 1991), directly before treating this as fully primary-sourced."}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Provisionally verified via tertiary/encyclopedic sources rather than a named academic monograph — flagged for a stronger citation pass if higher rigor is needed.","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_kana_descends_chinese.json"},{"id":"claim_khipu_writing_status_disputed","subject_type":"WritingSystem","subject_id":"ws_khipu","statement":"Whether khipu (Andean knotted-string devices) constitute writing at all, beyond a purely numerical/accounting notation, is itself a live dispute distinct from any origin-type question. Gary Urton (Signs of the Inka Khipu: Binary Coding in the Andean Knotted-String Records, University of Texas Press, 2003) argues khipu construction (fiber, ply direction, knot type/direction, attachment) encodes binary-coded information beyond pure accounting, explicitly against a \"mere mnemonic\" reading. Newly analyzed epistolary khipu with as many as 95 distinct symbols (within logosyllabic range, well beyond pure-accounting khipu's symbol count) and statistical studies reporting Zipf/Shannon-entropy signatures consistent with natural-language structure (matching Quechua entropy figures) have been presented as evidence of intelligible content, but these remain indirect statistical arguments, not confirmed readings. Colonial Spanish sources describe khipu used for histories, genealogies, poetry, and law, but no confirmed decipherment of narrative content exists. Mainstream caution holds most khipu are confidently readable only as numerical/accounting records.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["South America"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"Urton and subsequent statistical work argue for narrative/linguistic content beyond accounting; mainstream caution holds only numerical content is confidently read — actively debated, not resolved.","sources":[{"type":"PRIMARY","citation":"Urton, Gary. Signs of the Inka Khipu: Binary Coding in the Andean Knotted-String Records. University of Texas Press, 2003.","author":"Gary Urton","year":2003,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Urton, Gary. \"Writing with Twisted Cords: The Inscriptive Capacity of Andean Khipus.\" Current Anthropology 58(3), 2017.","author":"Gary Urton","year":2017,"venue":"Current Anthropology","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Khipu construction encodes binary-coded linguistic/narrative information beyond pure numerical accounting","holders":[{"name":"Gary Urton","work":"Signs of the Inka Khipu (2003); \"Writing with Twisted Cords\" (2017)","year":2017,"camp":"INSCRIPTIVE-CAPACITY SCHOOL"}],"strongest_case":"Epistolary khipu with up to 95 distinct symbols (within logosyllabic range) and statistical entropy signatures resembling natural-language structure.","status":"CONTESTED"},{"position":"Khipu are confidently readable only as numerical/accounting records; narrative content remains unconfirmed","holders":[{"name":"Mainstream Andean-studies caution, per the surveyed literature","camp":"ACCOUNTING-ONLY SCHOOL"}],"strongest_case":"No accepted decipherment of narrative khipu content exists; entropy-signature arguments are indirect and statistical, not a reading.","status":"MAJORITY"}],"does_not_demonstrate":["A confirmed decipherment of narrative/linguistic khipu content (statistical entropy signatures are suggestive, not a reading)"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_khipu_writing_status_disputed.json"},{"id":"claim_kimpa_vita_does_not_demonstrate","subject_type":"GenderSystem","subject_id":"gs_kongo","statement":"Kimpa Vita's case demonstrates that a Kongo woman could achieve the highest tier of religious-political authority available in the society — functioning, per Thornton's characterization, as the effective center of \"something of a theocracy\" — and command a mass following during a specific historical crisis (the post-1665 civil wars), within an already-existing cultural space for female spirit possession as a recognized channel of authority. It does NOT demonstrate that women's political authority was routine, institutionalized, or legally secured in Kongo society generally (her authority was charismatic/prophetic and crisis-contingent); that commoner or non-elite women had comparable access (she was aristocratic-born, and Thornton's broader 2006 findings on elite women's post-1665 political action are specifically about elite women); or that the outcome validates the movement as a durable structural gain for women's status — she was tried and executed as a heretic, with the same missionary establishment that had elsewhere facilitated elite women's authority (e.g. Queen Leonor) playing the decisive role in her condemnation.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["Central Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Thornton, John K. The Kongolese Saint Anthony: Dona Beatriz Kimpa Vita and the Antonian Movement, 1684-1706. Cambridge University Press, 1998.","author":"John K. Thornton","year":1998,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Thornton, John K. \"Elite Women in the Kingdom of Kongo.\" Journal of African History 47(3), 2006: 437-460.","author":"John K. Thornton","year":2006,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["Routine/institutionalized female political authority in Kongo generally","Comparable authority for non-elite women","A durable structural gain for women's status (she was tried and executed as a heretic)"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_kimpa_vita_does_not_demonstrate.json"},{"id":"claim_latin_descends_greek_etruscan","subject_type":"WritingSystem","subject_id":"ws_latin","statement":"The Latin alphabet derives from Greek, transmitted via the Etruscan alphabet (itself imported from Euboean Greek colonies at Cumae/Ischia in the Gulf of Naples, 8th century BCE; archaeological support includes the 1957-58 Veii excavations by the British School at Rome showing Cumae/Ischia contact from the mid-8th century BCE). Whether Latin's direct source is Etruscan intermediation or a more direct Cumaean-Greek borrowing bypassing Etruscan is a genuine, documented, unresolved scholarly dispute — both positions are live in the literature.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Europe"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":"Etruscan-mediated transmission vs. direct Cumaean-Greek borrowing bypassing Etruscan — both positions live, no clear majority signal found in this research pass.","sources":[{"type":"PRIMARY","citation":"British School at Rome, Veii excavation reports, 1957-58.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"General epigraphic literature on the Etruscan-vs-direct-Greek transmission dispute for Latin.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_latin_descends_greek_etruscan.json"},{"id":"claim_ld350_genus_dispute","subject_type":"Population","subject_id":"pop_early_homo","statement":"Whether the LD 350-1 mandible’s mix of primitive (Australopithecus-like) and derived (Homo-like) traits justifies genus-level (Homo) assignment from a single mandible and dentition was formally disputed in the scientific literature.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z1","zoom_max":"Z2","region":["Africa"],"evidence_types":["ARCHAEOLOGY"],"confidence":"DISPUTED","scholarly_disagreement":"Whether one mandible/dentition with a mix of primitive and derived traits is sufficient to assign genus-level (Homo) status, versus requiring more complete cranial or postcranial material.","sources":[{"type":"SECONDARY","citation":"Comment on \"Early Homo at 2.8 Ma...\" Science, doi:10.1126/science.aab0591","author":null,"year":2015,"venue":"Science","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Villmoare et al., reply to Comment. Science, doi:10.1126/science.aab1122","author":null,"year":2015,"venue":"Science","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"The mandibular and dental morphology justifies assignment to Homo","holders":[{"name":"Villmoare, B. et al.","work":"Science 347(6228) and reply to Comment","year":2015,"camp":"[PALEOANTHROPOLOGY — ORIGINAL DESCRIPTION TEAM]"}],"status":"MAJORITY","strongest_case":"The derived, thinned symphyseal and dental proportions fall outside the Australopithecus afarensis range and align with later Homo."},{"position":"Genus-level assignment from a single mandible/dentition is not adequately supported","holders":[{"name":"Authors of the 2015 Science Comment (unnamed in retrieved sources)","work":"Comment on \"Early Homo at 2.8 Ma...\", Science, doi:10.1126/science.aab0591","year":2015,"camp":"[PALEOANTHROPOLOGY — TAXONOMIC SKEPTIC]"}],"status":"MINORITY","strongest_case":"Dental and mandibular traits alone have historically been unreliable for genus-level hominin taxonomy without cranial or postcranial confirmation."}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Commentary authors’ names were not resolved in the research pass; cite by publication (Comment on Science 347(6228), doi:10.1126/science.aab0591) rather than by name until independently confirmed.","_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_ld350_genus_dispute.json"},{"id":"claim_linear_a_2026_ai_claim_unverified","subject_type":"Text","subject_id":"text_linear_a_tablets","statement":"A mid-2026 claimed decipherment of Linear A by self-taught AI/ML engineer Tom Di Mino (first reported ~30 July 2026, expanded ~13 August 2026), identifying the underlying language as Semitic with a 40-42 sign readings, a 408-508-word lexicon, and ~443 proposed translations built using AI-assisted text organization and comparative work against Semitic inscriptions, is under review by linguists at Rutgers and Cambridge, has no peer-reviewed publication, and no independent confirmation. Di Mino has no formal linguistics training, and the field treats the claim with explicit \"calibrated skepticism\" given a long history of failed amateur Linear A decipherment claims. This claim does NOT change decipherment_status from UNDECIPHERED and should not be pre-encoded as resolved.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z6","zoom_max":"Z7","region":["Europe"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"LOW","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"GreekReporter.com coverage of the Di Mino Linear A claim, 30 Jul 2026 and 13 Aug 2026.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null},{"type":"SECONDARY","citation":"AI Insiders, \"An AI Engineer Says He Decoded Linear A. Here Is What He Actually Showed.\"","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"SEARCH_SNIPPET","access_note":null}],"interpretations":[],"does_not_demonstrate":["That Linear A has been deciphered (this remains an unpublished, unreviewed, contested claim as of the current date)"],"adversarial_counter":null,"status":"verified","notes":"Included specifically as a live example of the \"definitely says X\" popular-overclaim risk this project is built to catch — do not let this claim's existence read as endorsement.","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_linear_a_2026_ai_claim_unverified.json"},{"id":"claim_linear_b_descends_linear_a","subject_type":"WritingSystem","subject_id":"ws_linear_b","statement":"Linear B's signary is derived from Linear A's (visually similar sign forms, shared syllabic sign inventory); Mycenaean scribes repurposed that signary to notate a completely different, known language — Greek — with phonetic modifications for Greek sound patterns. Michael Ventris announced in 1952 that Linear B encoded archaic Mycenaean Greek; John Chadwick independently confirmed it; jointly published in the Journal of Hellenic Studies (1953) and Documents in Mycenaean Greek (Cambridge University Press, 1956, published after Ventris's death). Cracking Linear B did not solve Linear A precisely because sign forms carry over but sign-to-sound values do not transfer across different underlying languages.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Europe"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Ventris, Michael, and John Chadwick. \"Evidence for Greek Dialect in the Mycenaean Archives.\" Journal of Hellenic Studies, 1953.","author":"Ventris and Chadwick","year":1953,"venue":"Journal of Hellenic Studies","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Ventris, Michael, and John Chadwick. Documents in Mycenaean Greek. Cambridge University Press, 1956.","author":"Ventris and Chadwick","year":1956,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_linear_b_descends_linear_a.json"},{"id":"claim_mahrem_attestation","subject_type":"Deity","subject_id":"dty_mahrem","statement":"Mahrem is attested via interpretatio graeca as \"Ares\" in the Monumentum Adulitanum (surviving only via Cosmas Indicopleustes's copy, made at Adulis c. 518-525 CE, published in his Christian Topography c. 547-549 CE — the original stone is lost and its own composition date is only estimated, 2nd-3rd century CE), and directly by name in King Ezana's own pre-Christian Ge'ez inscriptions (likely 330s CE), in which Aksumite kings style themselves \"son of the invincible Mahrem.\" Comparison to the South Arabian war god Almaqah is repeatedly made in secondary literature but the degree of identity is explicitly uncertain in the sources found.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["Horn of Africa/Aksum"],"evidence_types":["INSCRIPTION"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Ezana's pre-Christian Ge'ez inscriptions (RIÉ 185 I/II = DAE 6-7).","author":null,"year":null,"venue":null,"contemporary_with_event":true,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Cosmas Indicopleustes. Christian Topography (Monumentum Adulitanum copy), c. 547-549 CE.","author":null,"year":null,"venue":null,"contemporary_with_event":false,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["That Mahrem is simply equivalent to the South Arabian Almaqah — repeatedly asserted in secondary literature but not established with the degree of identity the comparison implies"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_mahrem_attestation.json"},{"id":"claim_maya_decipherment_history","subject_type":"Text","subject_id":"text_san_bartolo_murals","statement":"Maya script decipherment was a decades-long collaborative process, not a single breakthrough. J. Eric S. Thompson dominated the field into the 1960s championing a purely ideographic, non-phonetic, non-historical reading of the script and rejected Yuri Knorozov's 1952 phonetic (logogram + CV-syllable) argument until Thompson's own death in 1975; Cold War-era politics around Knorozov's Soviet nationality are documented (though not to full academic-historiography rigor in this pass) as a real contributing factor in the delay. Tatiana Proskouriakoff (\"Historical Implications of a Pattern of Dates at Piedras Negras, Guatemala,\" American Antiquity 25(4), 1960, pp. 454-475) demonstrated that stelae date-patterns recorded real dynastic events of named rulers, overturning Thompson's purely calendrical/religious reading. Linda Schele, Floyd Lounsbury, Peter Mathews, David Stuart, and Nikolai Grube completed the collaborative phonetic/logosyllabic decipherment through the 1970s-1990s. Current status: DECIPHERED, with roughly 80-90% of signs/inscriptions readable per David Stuart (University of Texas) — core grammar solved, but a nontrivial minority of rare/unique signs and some toponyms remain unread or contested; do not report as 100% solved.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["North America"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Knorozov, Yuri. \"Drevnyaya pis'mennost' Tsentral'noy Ameriki\" [Ancient writing of Central America]. Sovetskaya Etnografiya, 1952.","author":"Yuri Knorozov","year":1952,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Proskouriakoff, Tatiana. \"Historical Implications of a Pattern of Dates at Piedras Negras, Guatemala.\" American Antiquity 25(4), 1960: 454-475.","author":"Tatiana Proskouriakoff","year":1960,"venue":"American Antiquity","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Coe, Michael D. Breaking the Maya Code. Thames & Hudson, 1st ed. 1992, 3rd ed. 2012.","author":"Michael D. Coe","year":2012,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Martin, Simon, and Nikolai Grube. Chronicle of the Maya Kings and Queens. Thames & Hudson, 2000.","author":"Martin and Grube","year":2000,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"No single authoritative recent (2020s) peer-reviewed percentage-deciphered figure was found; 80% and 90% both circulate in current reporting (David Stuart quoted at ~90% in The Alcalde, UT Austin, 2012) — treat as an approximate range.","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_maya_decipherment_history.json"},{"id":"claim_maya_origin_type","subject_type":"WritingSystem","subject_id":"ws_maya_script","statement":"The relationship between Maya script and earlier Mesoamerican traditions (Olmec-associated symbols, Zapotec script) is unresolved, not a settled linear derivation. The \"mother culture\" (Olmec as single ancestral source) vs. \"sister cultures\" (multiple simultaneous, mutually-influencing regional developments) debate, documented by Kent V. Flannery and Joyce Marcus (University of Michigan) and David C. Grove (University of Illinois) for Mesoamerican archaeology generally, extends to writing specifically: the pre-2006 assumption of Maya writing deriving from an earlier Olmec or Zapotec source is complicated by the 2005-2006 San Bartolo discovery, which shows a mature, fully developed Maya script by c. 300-200 BCE with no obvious transitional forms linking back to Olmec symbols — leading several scholars to regard Maya writing as plausibly a separate \"homegrown\" development. The macro-level claim that Mesoamerican writing as a whole developed with no Old World contact is on much firmer ground than any micro-level claim about which Mesoamerican tradition gave rise to which other.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["North America"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"UNKNOWN","scholarly_disagreement":"\"Mother culture\" (Olmec-derived) vs. \"sister cultures\" (independent regional development) framings both have named proponents and neither is settled for the specific case of script derivation.","sources":[{"type":"PRIMARY","citation":"Saturno, William A., David Stuart, and Boris Beltrán. \"Early Maya Writing at San Bartolo, Guatemala.\" Science 311(5765), 2006: 1281-1283.","author":"Saturno, Stuart, Beltrán","year":2006,"venue":"Science","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Marcus, Joyce. Mesoamerican Writing Systems. Princeton University Press, 1992.","author":"Joyce Marcus","year":1992,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":"Full text not directly accessible this session (network egress blocked); position on Zapotec-as-independent-candidate not independently confirmed beyond secondary framing."}],"interpretations":[],"does_not_demonstrate":["A confirmed single-source derivation chain from Olmec through Zapotec/Epi-Olmec to Maya"],"adversarial_counter":null,"status":"verified","notes":"I could not directly verify Marcus's own position on whether Zapotec writing is a plausible independent-origin candidate (her 1992 book and the Michigan Oaxaca-project pages were blocked from direct fetch this session) — flagged for follow-up.","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_maya_origin_type.json"},{"id":"claim_meroitic_descends_egyptian","subject_type":"WritingSystem","subject_id":"ws_meroitic","statement":"Meroitic script exists in two forms, both derived from Egyptian writing: hieroglyphic (columnar, monumental), descended from Egyptian hieroglyphs, and cursive (horizontal, right-to-left, the majority of surviving texts), descended from Egyptian demotic. Francis Llewellyn Griffith (Oxford) established the phonetic values of the 23-sign script between 1909 and 1911, using bilingual/onomastic evidence (Meroitic royal names cross-matched against Egyptian hieroglyphic renderings, and funerary formulas invoking Isis/Osiris whose Egyptian pronunciation was known). This is a strong PARTIAL-decipherment example: the phonetic values are read reliably, but the Meroitic language remained only partly understood for decades until Claude Rilly (CNRS) demonstrated it belongs to a Nilo-Saharan branch he named Northern East Sudanic, alongside Nubian, Nara, Taman, and Nyima (Rilly and de Voogt, The Meroitic Language and Writing System, Cambridge University Press, 2012), ending a century of dispute about the language's affiliation.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Griffith, Francis Llewellyn. Establishment of Meroitic phonetic values, 1909-1911.","author":"Francis Llewellyn Griffith","year":1911,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Rilly, Claude, and Alex de Voogt. The Meroitic Language and Writing System. Cambridge University Press, 2012.","author":"Rilly and de Voogt","year":2012,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_meroitic_descends_egyptian.json"},{"id":"claim_mwari_great_zimbabwe_disputed","subject_type":"Tradition","subject_id":"trad_shona_religion","statement":"Whether the Mwari cult was Great Zimbabwe's state religion during the site's 13th-15th century floruit is genuinely contested, not settled. Some earlier/popular accounts and the \"Mbire\" oral migration tradition treat the cult as continuous with or originating at Great Zimbabwe. David Beach argued documentary/oral linkage between the archaeological site and the cult during that period is weak — the cult's source-rich documented history begins with its 17th-18th century Rozvi (Changamire dynasty) association and Matopos/Njelele shrine geography. Richard Werbner (Kalanga fieldwork) argues further that the cult historically was never structurally bound to any specific state/polity at all. Innocent Pikirayi (The Zimbabwe Culture, AltaMira Press, 2001) cautions against reading the cult as a mere instrument of state power even in its later, better-documented Rozvi-era form.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["Southern Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"Whether the Mwari cult's political-religious association with Great Zimbabwe specifically (as opposed to its later, better-documented Rozvi/Matopos-era form) is real continuity or backward extrapolation from later evidence.","sources":[{"type":"PRIMARY","citation":"Pikirayi, Innocent. The Zimbabwe Culture: Origins and Decline of Southern Zambezian States. AltaMira Press, 2001.","author":"Innocent Pikirayi","year":2001,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Beach, David. Work on Great Zimbabwe religious evidence, 1973 and later.","author":"David Beach","year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"The Mwari cult originated at or was continuous with Great Zimbabwe, later moving to the Matopos with Rozvi political power","holders":[{"name":"Proponents of the \"Mbire migration\" oral tradition, per the surveyed literature","camp":"CONTINUITY SCHOOL"}],"strongest_case":"Oral tradition places cult officials migrating south from the Lake regions with Karanga clans in the 14th century.","status":"MINORITY"},{"position":"The cult's documented history begins later (17th-18th c. Rozvi era); its presence at Great Zimbabwe specifically is inferential, not independently evidenced","holders":[{"name":"David Beach","camp":"SKEPTICAL SCHOOL"},{"name":"Richard Werbner","camp":"SKEPTICAL SCHOOL"}],"strongest_case":"No archaeological dating specific to the Njelele shrine or documentary linkage to Great Zimbabwe's own floruit has been established; Werbner's Kalanga fieldwork finds no structural state-cult binding at any period.","status":"CONTESTED"}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_mwari_great_zimbabwe_disputed.json"},{"id":"claim_mwari_structure","subject_type":"Deity","subject_id":"dty_mwari","statement":"Mwari (Mwali) is a high-god oracular tradition centered on the Matopo/Matobo Hills, principal historical shrine at Njelele (also Matonjeni; Shona Mabweadziva, \"place of spring waters\"), with a broader network of subsidiary shrines. The god's voice is delivered through mediums from within cave shrines; historically served both Shona/Kalanga and, after Ndebele settlement in the 1830s-40s, Ndebele consultors, especially for rainmaking and political counsel. M.L. Daneel, The God of the Matopo Hills: An Essay on the Mwari Cult in Rhodesia (Mouton, 1970), based on 1965-67 fieldwork, is the foundational modern academic study.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["Southern Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Daneel, M.L. The God of the Matopo Hills: An Essay on the Mwari Cult in Rhodesia. The Hague: Mouton, 1970.","author":"M.L. Daneel","year":1970,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_mwari_structure.json"},{"id":"claim_neanderthal_diversity_2026_complication","subject_type":"Population","subject_id":"pop_neanderthal","statement":"A 2026 study reports that late Neanderthals in northwestern Europe were not inbred and had greater genetic diversity than earlier low-diversity population estimates suggested, complicating the \"genetically doomed by inbreeding/low diversity\" strand of the extinction narrative for at least this regional population.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z1","zoom_max":"Z2","region":["Europe"],"evidence_types":["ANCIENT_DNA","SCIENTIFIC_ANALYSIS"],"confidence":"LOW","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"\"Genetic diversity of late Neanderthals in northwestern Europe.\" Nature (2026) — author list not independently confirmed in this research pass.","author":null,"year":2026,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"SEARCH_SNIPPET","access_note":"Single recent paper; full author list and independent replication not yet confirmed."}],"interpretations":[],"does_not_demonstrate":["that the broader small-population/low-diversity picture is wrong for Neanderthals generally — this finding is regionally and temporally specific to late northwestern European Neanderthals"],"adversarial_counter":null,"status":"verified","notes":"Confidence set LOW: single very recent (2026) finding, not yet cross-checked against independent replication or full field response in this research pass.","_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_neanderthal_diversity_2026_complication.json"},{"id":"claim_nehanda_does_not_demonstrate","subject_type":"GenderSystem","subject_id":"gs_shona","statement":"Mbuya Nehanda (medium of the Nehanda mhondoro spirit) was a central religious-political leader of the 1896-97 First Chimurenga against British South Africa Company rule, executed 27 April 1898; her recorded declaration before execution (\"my bones will rise\") rests on a single surviving eyewitness account (Fr. Francis Richartz), and should be treated as resting on one source, likely embellished by later nationalist mythology, even though the execution and general resistance leadership role are not in dispute. Her case demonstrates a specific woman could and did hold the highest religious-political authority position available at a moment of national crisis, and that spirit mediumship was not gender-restricted at the top tier (mediums could be possessed by a spirit of either sex). It does NOT demonstrate that Shona women generally held political, legal, or economic equality — mediumship access ran through spiritual selection/possession, a fundamentally different channel of authority from ordinary secular political office, landholding, marriage law, or household headship, all structurally male-dominated in the same society and period.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["Southern Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Ranger, Terence. Revolt in Southern Rhodesia 1896-97: A Study in African Resistance. Heinemann, 1967.","author":"Terence Ranger","year":1967,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Beach, David. \"An Innocent Woman, Unjustly Accused? Charwe, Medium of Nehanda Mhondoro Spirit, and the 1896-97 Central Shona Rising in Zimbabwe.\" 1998.","author":"David Beach","year":1998,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["General political, legal, or economic equality for Shona women"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_nehanda_does_not_demonstrate.json"},{"id":"claim_neography_comparative_literature","subject_type":"WritingSystem","subject_id":"ws_cherokee","statement":"A named comparative research program exists for modern individually-attributed script inventions, under the term \"neography\": Piers Kelly (linguistic anthropologist, Max Planck Institute / University of New England), across \"The Invention, Transmission and Evolution of Writing: Insights from the New Scripts of West Africa\" (2018, covering Vai/Bamum/Masaba comparatively), \"The Art of Not Being Legible: Invented Writing Systems as Technologies of Resistance in Mainland Southeast Asia\" (2018, covering Pahawh Hmong and other Southeast Asian cases), and \"Unsettled Scripts: Script Invention and the Bind of Digital Recognition\" (Modern Languages Open). No single Kelly paper treats Cherokee, Vai, Pahawh Hmong, and N'Ko together as one set — each covers a regional subset — so this should be characterized as an active but recent/fragmented research program, not a single canonical synthesis text. Stephen Houston's edited The First Writing: Script Invention as History and Process (Cambridge UP, 2004) covers a different topic (ancient first-writing systems: cuneiform, proto-Elamite, Egyptian, Chinese, Mesoamerican) and should not be cited as covering these modern cases despite the similar title.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":[],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"Kelly, Piers. \"The Invention, Transmission and Evolution of Writing: Insights from the New Scripts of West Africa.\" In Paths into Script Formation in the Ancient Mediterranean, 2018.","author":"Piers Kelly","year":2018,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Kelly, Piers. \"The Art of Not Being Legible: Invented Writing Systems as Technologies of Resistance in Mainland Southeast Asia.\" 2018.","author":"Piers Kelly","year":2018,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Houston, Stephen (ed.). The First Writing: Script Invention as History and Process. Cambridge University Press, 2004.","author":"Stephen Houston","year":2004,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["That Houston 2004 covers modern individually-attributed script inventions (it does not — flagged to prevent miscitation)"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_neography_comparative_literature.json"},{"id":"claim_no_indigenous_writing_regions","subject_type":"WritingSystem","subject_id":"ws_cuneiform","statement":"At least three world regions are well documented as having no indigenous writing system before external contact: (1) pre-contact Aboriginal Australia — mainstream consensus holds message sticks and notched digging sticks are graphic/mnemonic communication (Piers Kelly, Australian Message Stick Database, Journal of Material Culture, 2020) rather than writing proper, with no rigorous named-scholar causal explanation for the absence found at citation quality this session; (2) most pre-colonial sub-Saharan Africa outside the Nile Valley, the Ethiopian highlands (Ge'ez), and the West African cases documented separately (Ajami, Nsibidi, and the 19th-20th century Vai/Bamum/N'Ko inventions) — confirmed specifically for Southern African Bantu-speaking societies, with the caveat that a modern invented script for Southern Bantu languages (isiBheqe Sohlamvu/Ditema tsa Dinoko) was created by South African linguists starting c. 2015, analogous to Bamum/Vai/N'Ko, not evidence of pre-colonial tradition; (3) North America north of Mesoamerica — no native writing system existed at first European contact, with post-contact inventions (most famously Sequoyah's Cherokee syllabary) representing informed invention, not indigenous continuity. The distinction between \"adapted an outside script\" (Ajami, Ge'ez, Meroitic-from-Egyptian) and \"no writing system used at all\" is the one worth encoding — conflating them (as some polemical sources do) would reproduce the kind of overclaim this project's standing rules are built to avoid, in the other direction.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z3","zoom_max":"Z6","region":["Oceania","Africa","North America"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Kelly, Piers. \"Australian message sticks: Old questions, new directions.\" Journal of Material Culture, 2020.","author":"Piers Kelly","year":2020,"venue":"Journal of Material Culture","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Britannica-sourced consensus on absence of pre-contact writing in North America outside Mesoamerica.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["That the absence of indigenous writing implies an absence of sophisticated knowledge-transmission systems (oral tradition, song-line, and mnemonic systems in these regions are independently well documented and are not lesser substitutes)"],"adversarial_counter":null,"status":"verified","notes":"Some search results for \"sub-Saharan Africa no writing\" surfaced polemical sources arguing the framing is itself a colonial myth; these were not relied on for factual claims, per the flag in the underlying research report.","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_no_indigenous_writing_regions.json"},{"id":"claim_nyame_titles","subject_type":"Deity","subject_id":"dty_nyame","statement":"The Akan supreme being carries multiple names/praise-titles used contextually rather than as fully interchangeable synonyms: Onyame (basic term for Deity), Onyankopon (\"the one who alone is great/Supreme One\"), Odomankoma (\"the Infinite/Interminable One,\" creator epithet), and Borebore (\"carver/excavator/originator\"). Source: J.B. Danquah's own tripartite distinction (The Akan Doctrine of God, 1944/2nd ed. 1968).","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["West Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Danquah, J.B. The Akan Doctrine of God: A Fragment of Gold Coast Ethics and Religion. 2nd ed., Frank Cass, 1968 (orig. 1944).","author":"J.B. Danquah","year":1944,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"Danquah (1895-1965) was himself an anticolonial lawyer/philosopher/politician (co-founder UGCC, died in Nkrumah-era detention), not a neutral ethnographer — per \"Joseph B. Danquah's The Akan Doctrine of God (1944): Anticolonial Fragments?\", Fighting Words, Peter Lang, 2017, he used monotheism/Greek philosophical categories as his comparative benchmark, underwriting a \"Ghana hypothesis\" for postcolonial Akan/Ghanaian identity — read as a documented early-20th-century interpretive/political source, not neutral description.","_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_nyame_titles.json"},{"id":"claim_nzambi_meaning_disputed","subject_type":"Deity","subject_id":"dty_nzambi_mpungu","statement":"Whether Nzambi a Mpungu originally denoted a benevolent creator/sky-father (the older ethnographic-synthesis reading, reflected in most popular sources) is disputed by Wyatt MacGaffey's most recent textual work. MacGaffey, \"Precolonial Beliefs in God, Nzambi, and Chthonic Beings: Evidence from Kongo Texts,\" Journal of Religion in Africa 52(1-2), 2022, using early-20th-century manuscripts by indigenous ethnographers drawing on Karl Laman's ~10,000-page manuscript collection (Protestant converts, c. 1915), argues Nzambi's original semantic field centered on death, with the life/creation valence instead carried by bisimbi (chthonic, land/water-associated spirit forces). The \"benevolent creator\" framing reflects the post-missionary Christianized gloss on Nzambi once the term was repurposed to translate the Christian God.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["Central Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"Whether Nzambi a Mpungu's original precolonial meaning centered on death (MacGaffey 2022) or was already a benevolent creator/sky-father (older ethnographic synthesis).","sources":[{"type":"PRIMARY","citation":"MacGaffey, Wyatt. \"Precolonial Beliefs in God, Nzambi, and Chthonic Beings: Evidence from Kongo Texts.\" Journal of Religion in Africa 52(1-2), 2022: 1-21.","author":"Wyatt MacGaffey","year":2022,"venue":"Journal of Religion in Africa","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Nzambi a Mpungu was originally a personification of death; bisimbi carried the life/creation valence","holders":[{"name":"Wyatt MacGaffey","work":"Journal of Religion in Africa 52(1-2), 2022","year":2022,"camp":"ETHNOHISTORICAL-TEXTUAL SCHOOL"}],"strongest_case":"Direct textual analysis of the early-20th-century Laman manuscript collection, written by indigenous ethnographers close in time to living precolonial memory.","status":"MINORITY"},{"position":"Nzambi a Mpungu was already a high-god/creator sky-father figure in the precolonial period","holders":[{"name":"Older ethnographic synthesis tradition, e.g. K.K. Bunseki Fu-Kiau","camp":"CLASSIC ETHNOGRAPHIC SCHOOL"}],"strongest_case":"This is the dominant framing across most 20th-century ethnography and remains the majority popular/reference-work position.","status":"MAJORITY"}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_nzambi_meaning_disputed.json"},{"id":"claim_ogun_domain_history","subject_type":"Deity","subject_id":"dty_ogun","statement":"Ògún is consistently sourced as patron of iron-working, hunting, and war from an early period, with the domain demonstrably expanding over time to cover new iron/steel-adjacent technologies. Sandra T. Barnes, ed., Africa's Ogun: Old World and New (Indiana UP, 1989/1997), the standard interdisciplinary scholarly volume, is explicitly organized around this transformation-across-manifestations thesis. A popular (non-academic) claim that Ògún was a historicized Ifè king could not be verified against any academic source in this research pass — contrast with Ṣàngó, whose historicization is well-attested in named academic literature; do not report the Ògún claim with comparable confidence.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["West Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Barnes, Sandra T., ed. Africa's Ogun: Old World and New. Indiana University Press, 1989/2nd ed. 1997.","author":null,"year":1997,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":["That Ògún was a historicized Ifè king — a popular, non-academically-sourced claim distinct from Ṣàngó's well-attested historicization case"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_ogun_domain_history.json"},{"id":"claim_osun_badejo","subject_type":"Deity","subject_id":"dty_osun","statement":"Diedre L. Badejo, Ọ̀ṣun Ṣèègèsí: The Elegant Deity of Wealth, Power, and Femininity (Africa World Press, 1996), described as the first full-length original research study of a major Yorùbá goddess, is based on fieldwork at Ọ̀ṣun's principal shrine in Òṣogbo, drawing on ritual orature, sacred songs, and festival drama, and explicitly traces the goddess's presence across West Africa, Cuba, Brazil, and the US.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["West Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Badejo, Diedre L. Ọ̀ṣun Ṣèègèsí: The Elegant Deity of Wealth, Power, and Femininity. Africa World Press, 1996.","author":"Diedre L. Badejo","year":1996,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_osun_badejo.json"},{"id":"claim_phoenician_descends_proto_sinaitic","subject_type":"WritingSystem","subject_id":"ws_phoenician","statement":"Phoenician script descends from Proto-Sinaitic/Proto-Canaanite. The conventional \"c. 1050 BCE\" cutoff for \"Phoenician alphabet begins\" is an artifact of a gap in the epigraphic record, not a confirmed founding date; the actual process is a gradual post-Proto-Canaanite standardization phase spanning roughly the late 10th-early 9th century BCE, with a fully standardized 22-letter script emerging c. 1000-900 BCE. The oldest securely dated Phoenician inscriptions are from the 10th century BCE.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Western Asia"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"General epigraphic literature on Proto-Canaanite/Phoenician transition, converging on c. 1000-900 BCE standardization.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_phoenician_descends_proto_sinaitic.json"},{"id":"claim_proto_sinaitic_descends_egyptian","subject_type":"WritingSystem","subject_id":"ws_proto_sinaitic","statement":"Proto-Sinaitic script is an acrophonic adaptation of a small subset of Egyptian hieroglyphic signs, established by Alan H. Gardiner (\"The Egyptian Origin of the Semitic Alphabet,\" Journal of Egyptian Archaeology 3, 1916, pp. 1-16), who deciphered the Sinai inscriptions as encoding the Semitic goddess name Ba'alat using Egyptian signs repurposed by their first sound in the Semitic word for the pictured object. Orly Goldwasser (2006-2020) has extended this framework and proposed a tightened c. 1850 BCE core dating tied to Middle Kingdom mining seasons at Serabit el-Khadim; the Wadi el-Hol inscriptions independently date to roughly the same window.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Western Asia","Africa"],"evidence_types":["INSCRIPTION","ARCHAEOLOGY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Gardiner, Alan H. \"The Egyptian Origin of the Semitic Alphabet.\" Journal of Egyptian Archaeology 3, 1916: 1-16.","author":"Alan H. Gardiner","year":1916,"venue":"Journal of Egyptian Archaeology","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Goldwasser, Orly. Body of work 2006-2020 on Serabit el-Khadim dating and Proto-Sinaitic mechanism.","author":"Orly Goldwasser","year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_proto_sinaitic_descends_egyptian.json"},{"id":"claim_rock_art_shamanism_disputed","subject_type":"Tradition","subject_id":"trad_juhoansi_trance_healing","statement":"David Lewis-Williams (with Thomas Dowson) proposed the \"neuropsychological model\" — that San rock art motifs (geometric \"entoptic\" forms and therianthropes) represent imagery experienced during trance/altered states, based on analogy to 19th-20th century San ethnography, including both the Bleek-Lloyd /Xam material and later Kalahari (Ju/'hoansi) trance-dance ethnography. Anne Solomon directly disputes this, arguing Lewis-Williams elides /Xam (Cape, 19th century) and Kalahari San (20th century) ethnography into a single narrative, and that there is no clear evidence the historical /Xam themselves connected dance/trance states with healing in the way the Kalahari material documents. Mathias Guenther (Tricksters and Trancers, Indiana UP, 1999) takes a qualified middle position, accepting \"shaman\" as broadly appropriate terminology while emphasizing ambiguity and cultural variability over a single fixed reading.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["Southern Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"Whether San rock art imagery can be confidently linked to specific documented trance/healing cosmological content, and whether /Xam and Kalahari San ethnographic material can be combined for this purpose.","sources":[{"type":"PRIMARY","citation":"Lewis-Williams, David, and Thomas Dowson. \"The Signs of All Times: Entoptic Phenomena in Upper Palaeolithic Art.\" Current Anthropology 29:2, 1988.","author":"Lewis-Williams and Dowson","year":1988,"venue":"Current Anthropology","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Solomon, Anne. \"The southern San and the trance dance: a pivotal debate in the interpretation of San rock paintings.\" Antiquity.","author":"Anne Solomon","year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"San rock art imagery represents trance/altered-state experience, per a neuropsychological model applicable across San groups and periods","holders":[{"name":"David Lewis-Williams","camp":"NEUROPSYCHOLOGICAL SCHOOL"},{"name":"David Pearce","camp":"NEUROPSYCHOLOGICAL SCHOOL"}],"strongest_case":"19th-20th century San ethnography (Bleek-Lloyd plus Kalahari) supports the trance-dance interpretive framework, per Lewis-Williams and Pearce's continued defense.","status":"CONTESTED"},{"position":"The trance-dance link elides genuinely distinct /Xam and Kalahari San evidentiary bases and overstates continuity","holders":[{"name":"Anne Solomon","camp":"REVISIONIST SCHOOL"}],"strongest_case":"No clear evidence the historical /Xam themselves connected dance/trance states with healing in the way later Kalahari material documents — Lewis-Williams's model conflates two different groups and centuries.","status":"CONTESTED"}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_rock_art_shamanism_disputed.json"},{"id":"claim_rongorongo_dating_disputed","subject_type":"WritingSystem","subject_id":"ws_rongorongo","statement":"Ferrara, Silvia, et al. (\"The invention of writing on Rapa Nui (Easter Island). New radiocarbon dates on the Rongorongo script,\" Scientific Reports 14, 2 Feb 2024, article 53063-7) radiocarbon-dated four rongorongo tablets in a Rome collection: three to the 18th-19th centuries (post-contact), one to 1493-1509 CE — over 200 years before Roggeveen's 1722 European arrival. The authors themselves state the dates \"do not allow [researchers] to reach any incontrovertible conclusion\" given the \"old wood\" problem (dated felling, not inscribing) and a sample size of one pre-contact date. Rongorongo's glyph forms don't resemble any known European or other script and have closest formal parallels in Rapa Nui's own rock-carving tradition (circumstantial support for indigenous origin); conversely, no expedition report before Eyraud's 1864 arrival mentions a writing system on the island despite earlier European visits, including a 1770 Spanish annexation ceremony where islanders reportedly witnessed officials \"signing\" a document (a plausible stimulus-diffusion trigger point). The dating question is genuinely unresolved even in the most recent (2024) primary literature.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Oceania"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"DISPUTED","scholarly_disagreement":"Even the 2024 primary radiocarbon study's own authors decline to resolve pre- vs. post-contact origin from their single early date.","sources":[{"type":"PRIMARY","citation":"Ferrara, Silvia, et al. \"The invention of writing on Rapa Nui (Easter Island). New radiocarbon dates on the Rongorongo script.\" Scientific Reports 14, 2 Feb 2024, article 53063-7. PMID 38307972.","author":"Ferrara et al.","year":2024,"venue":"Scientific Reports","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Rongorongo plausibly predates European contact and represents an independent local invention","holders":[{"name":"Ferrara et al., interpreting their own 1493-1509 CE date cautiously","work":"Scientific Reports 14, 2024","year":2024,"camp":"PRE-CONTACT-PLAUSIBLE SCHOOL"}],"strongest_case":"One tablet's wood radiocarbon-dated to 1493-1509 CE, over 200 years before Roggeveen's 1722 arrival; glyph forms resemble no known outside script and parallel Rapa Nui's own petroglyph tradition.","status":"CONTESTED"},{"position":"Rongorongo more likely emerged after European contact, stimulated by witnessing literacy","holders":[{"name":"Position inferable from the documented absence of any pre-1864 European report of writing on the island, per the surveyed literature","camp":"POST-CONTACT-STIMULUS SCHOOL"}],"strongest_case":"No expedition report before Eyraud's 1864 arrival mentions a writing system, despite earlier visits including an 1770 Spanish annexation ceremony where islanders reportedly witnessed officials signing a document; the \"old wood\" problem means the single early radiocarbon date does not establish inscription date.","status":"CONTESTED"}],"does_not_demonstrate":["That rongorongo is confirmed pre-contact/independent (the study's own authors decline this conclusion from a single dated specimen)"],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_rongorongo_dating_disputed.json"},{"id":"claim_rongorongo_fischer_decipherment_rejected","subject_type":"Text","subject_id":"text_rongorongo_tablets","statement":"Steven Roger Fischer (Rongorongo, the Easter Island Script: History, Traditions, Texts, Oxford University Press, 1997) claimed the Santiago Staff tablet encodes a repeating cosmogonic/creation-chant formula (\"X copulated with Y; there issued forth Z\"), based on a sign he read as \"copulate,\" recurring 564 times. This claim is not accepted by the field: Jacques B.M. Guy (1998 review/critique) and Konstantin Pozdniakov (\"Les Bases du Déchiffrement de l'Écriture de l'Ile de Pâques,\" Journal de la Société des Océanistes, 1996) argue the statistical/structural patterns Fischer relied on arise from the script's own repetitive internal triadic sign-grouping structure and generic Polynesian chant-formula patterns, not from content specific to his proposed reading — making the \"decipherment\" effectively unfalsifiable.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z5","region":["Oceania"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":"Fischer [DECIPHERMENT-CLAIM] vs. Guy and Pozdniakov [SPECIFIC, NAMED REJECTION] — this is a settled minority rejection, not an open dispute; the field does not accept Fischer's reading.","sources":[{"type":"PRIMARY","citation":"Fischer, Steven Roger. Rongorongo, the Easter Island Script: History, Traditions, Texts. Oxford University Press, 1997.","author":"Steven Roger Fischer","year":1997,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Pozdniakov, Konstantin. \"Les Bases du Déchiffrement de l'Écriture de l'Ile de Pâques.\" Journal de la Société des Océanistes, 1996.","author":"Konstantin Pozdniakov","year":1996,"venue":"Journal de la Société des Océanistes","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Guy, Jacques B.M. Review/critique of Fischer 1997, 1998.","author":"Jacques B.M. Guy","year":1998,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_rongorongo_fischer_decipherment_rejected.json"},{"id":"claim_sango_historicization","subject_type":"Deity","subject_id":"dty_sango","statement":"Yorùbá oral-historical tradition, as recorded by Samuel Johnson (The History of the Yorubas, completed 1897, published 1921), places Ṣàngó within the Òyó Aláàfin king-list as an early king — though sources disagree on his exact ordinal position (third vs. fourth Aláàfin), which should be reported as varying by source, not as a fixed number. Sàngó in Africa and the African Diaspora (eds. Tishken, Falola, Akinyemi; Indiana UP, 2009), a peer-edited academic volume, is explicitly organized around the mythic-Ṣàngó/historical-Ṣàngó/syncretic-diaspora-traditions split as a central open question, confirming this is real, taken-seriously scholarly territory rather than a popular oversimplification.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["West Africa"],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"PRIMARY","citation":"Johnson, Samuel. The History of the Yorubas. Ed. Obadiah Johnson, 1921 (completed 1897).","author":"Samuel Johnson","year":1921,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Tishken, Joel E., Toyin Falola, and Akintunde Akinyemi, eds. Sàngó in Africa and the African Diaspora. Indiana University Press, 2009.","author":null,"year":2009,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_sango_historicization.json"},{"id":"claim_sapiens_origin_no_single_point","subject_type":"Population","subject_id":"pop_homo_sapiens","statement":"No single point in time or place can currently be identified for the origin of Homo sapiens. A major synthesis frames modern human ancestry as unfolding across three overlapping phases (worldwide dispersal and archaic admixture, 40-60 ka; African-based diversification of modern-human ancestry, 60-300 ka; complex separation from archaic lineages, 0.3-1 million years ago), and the \"pan-African\" model — that sapiens features assembled as a mosaic across a subdivided, gene-flow-connected African population network rather than in a single East African \"cradle\" — is the majority but not unanimous position.","claim_tier":"INTERPRETATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z1","zoom_max":"Z2","region":["Africa"],"evidence_types":["ARCHAEOLOGY","ANCIENT_DNA","SCIENTIFIC_ANALYSIS"],"confidence":"DISPUTED","scholarly_disagreement":"Whether the mosaic-trait evidence (e.g. Jebel Irhoud, Omo I/II, Florisbad, Herto) reflects genuinely parallel regional evolutionary processes across Africa, or a single lineage with mosaic trait accumulation and one identifiable structural threshold.","sources":[{"type":"PRIMARY","citation":"Bergström, A., Stringer, C., Hajdinjak, M., Scerri, E.M.L., Skoglund, P. \"Origins of modern human ancestry.\" Nature 590: 229-237. DOI: 10.1038/s41586-021-03244-5","author":"Bergström et al.","year":2021,"venue":"Nature","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"PRIMARY","citation":"Scerri, E.M.L. et al. \"Did Our Species Evolve in Subdivided Populations across Africa, and Why Does It Matter?\" Trends in Ecology & Evolution 33(8): 582-594.","author":"Scerri et al.","year":2018,"venue":"Trends in Ecology & Evolution","contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-08-31","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[{"position":"Pan-African/subdivided-population (multiregional-within-Africa) model","holders":[{"name":"Jean-Jacques Hublin","work":"Nature 546:289-292","year":2017,"camp":"[PALEOANTHROPOLOGY]"},{"name":"Eleanor Scerri","work":"Trends in Ecology & Evolution 33(8):582-594","year":2018,"camp":"[PALEOANTHROPOLOGY — AFRICAN MULTIREGIONALISM]"},{"name":"Chris Stringer","camp":"[PALEOANTHROPOLOGY]"},{"name":"Anders Bergström & Pontus Skoglund","work":"Nature 590:229-237","year":2021,"camp":"[POPULATION GENETICS]"}],"status":"MAJORITY","strongest_case":"Fossils from geographically distant African sites (Morocco, Ethiopia, South Africa) all show mixtures of archaic and modern traits at different, overlapping dates, consistent with regional populations connected by sporadic gene flow rather than one point of origin."},{"position":"Extended single-African-origin, with mosaic trait accumulation but one identifiable structural threshold (acquisition of neurocranial globularity)","holders":[{"name":"Andra Meneganzin, Telmo Pievani & Giorgio Manzi","work":"\"Pan-Africanism vs. single-origin of Homo sapiens,\" Evolutionary Anthropology 31(4): 199-212","year":2022,"camp":"[PHILOSOPHY OF BIOLOGY / EVOLUTIONARY THEORY]"}],"status":"MINORITY","strongest_case":"The pan-African model has inferential and terminological weaknesses; the mosaic evidence is real but is better explained by a still-recognizable single lineage than by fully independent parallel regional assembly."}],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase2-human-evolution/claim_sapiens_origin_no_single_point.json"},{"id":"claim_writing_dataset_gap","subject_type":"WritingSystem","subject_id":"ws_cuneiform","statement":"No systematic, actively-maintained, structured (queryable) scholarly database of writing systems with decipherment-status/origin-classification metadata comparable to what this app's data model needs was found. ISO 15924 (maintained with the Unicode Consortium as registration authority, 210+ scripts) is a practical identification/encoding standard for software localization and digital text processing — useful as a script-existence checklist and ID reference, but carries no historical-origin, genealogical-descent, or decipherment-status metadata. Omniglot (founded by Simon Ager, 1998; 2,200+ languages, 365 writing systems) is real and actively maintained but hobbyist-academic, not peer-reviewed. The standard academic reference remains a static print/digital volume: The World's Writing Systems, ed. Peter T. Daniels and William Bright (Oxford University Press, 1996, ~80 signed scholarly articles), not a queryable database. The peer-reviewed journal Writing Systems Research (founded 2009) ceased publication in 2019 — a real, citable gap.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z1","zoom_max":"Z7","region":[],"evidence_types":["WRITTEN_PRIMARY"],"confidence":"HIGH","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"ISO 15924 — Wikipedia; Unicode ISO 15924 Registration Authority.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null},{"type":"SECONDARY","citation":"Daniels, Peter T., and William Bright, eds. The World's Writing Systems. Oxford University Press, 1996.","author":"Daniels and Bright","year":1996,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":"This is itself a documented data gap worth recording, not something to paper over, per this project's standing \"Unknown is a valid answer\" discipline.","_source_path":"docs/timeline/data/claims/phase3-writing-systems/claim_writing_dataset_gap.json"},{"id":"claim_yemoja_diaspora_domain_shift","subject_type":"Deity","subject_id":"dty_yemoja","statement":"Yemọja was originally a Yorùbá river deity, specifically associated with the Ògùn River in Nigeria (not to be confused with the Òrìṣà Ògún — same name root, different referent). In the Americas, her domain shifted from river to ocean, widely attested across Cuban Santería (as Yemayá) and Brazilian Candomblé (as Yemanjá); sources attribute this to enslaved communities \"re-rooting\" the deity in the body of water that carried them into bondage. The fact of this domain shift is well-attested across multiple converging sources; no specific named scholar's causal account of the mechanism was traced to one academic citation in this research pass.","claim_tier":"OBSERVATION","related_observation_id":null,"date_semantics":null,"date":null,"zoom_min":"Z4","zoom_max":"Z6","region":["West Africa"],"evidence_types":["ETHNOGRAPHIC","LATER_HISTORICAL_ACCOUNT"],"confidence":"MODERATE","scholarly_disagreement":null,"sources":[{"type":"SECONDARY","citation":"Converging secondary sourcing on the Yemọja/Yemayá/Yemanjá river-to-ocean domain shift in the Americas.","author":null,"year":null,"venue":null,"contemporary_with_event":null,"independent_corroboration":null,"verified_by":"research-agent (WebSearch)","verified_date":"2026-09-01","verification_method":"CONVERGING_SECONDARY","access_note":null}],"interpretations":[],"does_not_demonstrate":[],"adversarial_counter":null,"status":"verified","notes":null,"_source_path":"docs/timeline/data/claims/phase4-religion-gender-africa/claim_yemoja_diaspora_domain_shift.json"}],"meta":{"entity_count":86,"claim_count":89,"claim_statuses":{"verified":89}}};
